window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s39-22","number":22,"surah":39,"verses":[9],"verseLabel":"الزمر: 9","question":"ما دلالة الانتقال من مقارنة القانت بغيره إلى سؤال ﴿هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾؟","answer":"القنوت ثمرة علم بالله والآخرة، فانتقل من صورة العالم العامل إلى قاعدة أن المعرفة الحقيقية لا تستوي مع الغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص129–139.","url":""}]},{"id":"s39-23","number":23,"surah":39,"verses":[10],"verseLabel":"الزمر: 10","question":"ما سر الجمع بين الإحسان في الدنيا وسعة أرض الله وتوفية الصابرين أجرهم بغير حساب؟","answer":"الإحسان وعد حاضر، وسعة الأرض تفتح طريق الثبات أو الهجرة، والأجر بغير حساب جزاء الصبر؛ فجمعت الآية العمل والمخرج والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص139–156.","url":""}]},{"id":"s39-24","number":24,"surah":39,"verses":[11,12],"verseLabel":"الزمر: 11–12","question":"ما دلالة تكرار الأمر بإخلاص الدين ثم وصف الرسول ﷺ بأنه أول المسلمين؟","answer":"تكرار الإخلاص يثبت أنه جوهر الرسالة، ووصفه بأول المسلمين يبين سبقه في امتثال ما يدعو إليه داخل أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص157–164.","url":""}]},{"id":"s39-25","number":25,"surah":39,"verses":[13],"verseLabel":"الزمر: 13","question":"ما سر وصف اليوم بالعظمة في ﴿عَذَابَ يَوْمٍ عَظِيمٍ﴾ بدل وصف العذاب نفسه؟","answer":"وصف اليوم بالعظمة ليشمل هوله وحسابه ومشاهده، فيصبح العذاب عظيمًا بعظمة الظرف الذي يقع فيه وما يجتمع فيه من شدائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص164–169.","url":""}]},{"id":"s39-26","number":26,"surah":39,"verses":[14],"verseLabel":"الزمر: 14","question":"ما دلالة تقديم اسم الجلالة في ﴿قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَهُ دِينِي﴾؟","answer":"تقديم ﴿اللَّهَ﴾ يفيد القصر في مقام التحدي: الله وحده أعبد، مهما اختار المشركون من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص169–175.","url":""}]},{"id":"s39-27","number":27,"surah":39,"verses":[2,14],"verseLabel":"الزمر: 2، 14","question":"ما سر التعبير أولًا بـ﴿مُخْلِصًا لَهُ الدِّينَ﴾ ثم بـ﴿مُخْلِصًا لَهُ دِينِي﴾؟","answer":"الأول أمر بأصل الإخلاص في الدين بوصفه تكليف الرسالة، والثاني إعلان شخصي ثابت: ديني أنا خالص لله في مواجهة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص758–771؛ ج50، ص169–175.","url":""}]},{"id":"s39-28","number":28,"surah":39,"verses":[15],"verseLabel":"الزمر: 15","question":"ما دلالة إطلاق الأمر للمشركين أن يعبدوا ما شاؤوا ثم بيان الخسران المبين؟","answer":"الأمر للتهديد لا للإباحة، كأنه يتركهم لما اختاروه بعد قيام الحجة ثم يكشف فورًا نهايته: الخسران الذي لا يخفى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص174–184.","url":""}]},{"id":"s39-29","number":29,"surah":39,"verses":[15],"verseLabel":"الزمر: 15","question":"ما سر تعريف الخاسرين بأنهم الذين خسروا أنفسهم وأهليهم يوم القيامة؟","answer":"خسران النفس فوات نجاتها، وخسران الأهل انقطاع الاجتماع النافع أو خسارتهم معهم؛ فليس الخسران مالًا بل الوجود والعلاقة والمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص175–184.","url":""}]},{"id":"s39-30","number":30,"surah":39,"verses":[16],"verseLabel":"الزمر: 16","question":"ما سر إعادة لفظ ﴿ظُلَلٌ﴾ في تصوير النار فوقهم ومن تحتهم؟","answer":"التكرار يجعل النار طبقات محيطة من أعلى وأسفل، وسميت السفلى ظللًا على سبيل المقابلة والتهكم؛ إذ لا ظل فيها ولا حماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص184–191.","url":""}]},{"id":"s39-31","number":31,"surah":39,"verses":[16],"verseLabel":"الزمر: 16","question":"ما دلالة الانتقال من مشهد النار إلى قوله ﴿ذَلِكَ يُخَوِّفُ اللَّهُ بِهِ عِبَادَهُ﴾ ثم ﴿يَا عِبَادِ فَاتَّقُونِ﴾؟","answer":"حوّل المشهد من خبر عن الغائب إلى تحذير حاضر، ثم ناداهم بالإضافة إليه ترغيبًا في الرجوع؛ فالتخويف طريق وقاية لا مجرد تهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص190–196.","url":""}]},{"id":"s39-32","number":32,"surah":39,"verses":[17,18],"verseLabel":"الزمر: 17–18","question":"ما سر اختيار الاجتناب في قوله ﴿وَالَّذِينَ اجْتَنَبُوا الطَّاغُوتَ أَنْ يَعْبُدُوهَا﴾؟","answer":"الاجتناب أبلغ من الترك؛ فهو ابتعاد عن الطاغوت وعن أسبابه ومسالك عبادته، لا مجرد امتناع لحظي عن فعل العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص196–205.","url":""}]},{"id":"s39-33","number":33,"surah":39,"verses":[17,18],"verseLabel":"الزمر: 17–18","question":"ما دلالة وصف عباد الله بأنهم ﴿يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُ﴾؟","answer":"لا يكتفون بسماع القول، بل يميزون ما يهدي إلى الحق فيتبعونه؛ فالصفة تجمع انفتاح السمع وحسن الاختيار والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص205–215.","url":""}]},{"id":"s39-34","number":34,"surah":39,"verses":[90],"verseLabel":"الزمر: 18؛ الأنعام: 90","question":"ما سر التعبير هنا بـ﴿أُولَئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ﴾، وفي الأنعام ﴿أُولَئِكَ الَّذِينَ هَدَى اللَّهُ﴾ بحذف المفعول؟","answer":"ذُكر مفعول الهداية هنا لتعيين أهل الاستماع والاتباع، وحذف في الأنعام مع سياق الأنبياء ليجري الهدى مطلقًا عامًا في وجوهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص196–214.","url":""}]},{"id":"s39-35","number":35,"surah":39,"verses":[19],"verseLabel":"الزمر: 19","question":"ما سر حذف مقابل الموصول في ﴿أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ﴾؟","answer":"حذف المقابل لأن حال من استحق العذاب لا تقبل الموازنة بمن نجا، ولأن جواب الشرط المفهوم يستدعي: أفتقدر على إنقاذه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص215–225.","url":""}]},{"id":"s39-36","number":36,"surah":39,"verses":[19],"verseLabel":"الزمر: 19","question":"ما دلالة سؤال الرسول ﷺ ﴿أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾ بعد ثبوت كلمة العذاب؟","answer":"الاستفهام ينفي قدرة الرسول على إنقاذ من ثبت عليه الحكم؛ فوظيفته البلاغ والهداية بالدلالة، لا تغيير الجزاء بعد استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص218–225.","url":""}]},{"id":"s39-37","number":37,"surah":39,"verses":[20],"verseLabel":"الزمر: 20","question":"ما سر تصوير مساكن المتقين بأنها غرف من فوقها غرف مبنية؟","answer":"الغرف العالية مبنية ثابتة، وفوقها غرف أخرى؛ فالصورة تجمع الرفعة والسعة والأمان في مقابلة طبقات النار المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص225–233.","url":""}]},{"id":"s39-38","number":38,"surah":39,"verses":[20],"verseLabel":"الزمر: 20","question":"ما سر ختم الوعد بقوله ﴿وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾؟","answer":"التوكيد يطمئن إلى أن هذا البناء ليس خيالًا، وتكرار اسم الله يقرر أن الذي وعد هو نفسه الذي لا يخلف الميعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص225–237.","url":""}]},{"id":"s39-39","number":39,"surah":39,"verses":[21],"verseLabel":"الزمر: 21","question":"ما دلالة تصوير دورة الماء من إنزاله وسلوكه ينابيع إلى إخراج الزرع ثم هيجه واصفراره وجعله حطامًا؟","answer":"تتابع المراحل يحول الماء الخفي في الأرض إلى زرع زاهٍ ثم هشيم؛ فيجعل دورة النبات مثلًا محسوسًا للحياة الدنيا وسرعة زوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص238–256.","url":""}]},{"id":"s39-40","number":40,"surah":39,"verses":[21],"verseLabel":"الزمر: 21","question":"ما سر اختيار ﴿فَسَلَكَهُ يَنَابِيعَ فِي الْأَرْضِ﴾ في تصوير نفاذ الماء؟","answer":"السلوك إدخال الشيء في طريق ممتد؛ فصور الماء نافذًا في مسالك الأرض حتى يظهر ينابيع موزعة بتقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص241–248.","url":""}]},{"id":"s39-41","number":41,"surah":39,"verses":[22],"verseLabel":"الزمر: 22","question":"ما دلالة تصوير الهداية بشرح الصدر للإسلام وكون صاحبه على نور من ربه؟","answer":"شرح الصدر توسعة لقبول الحق بلا ضيق، والنور بصيرة يسير بها؛ فجمعت الهداية استعداد الداخل ووضوح الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص257–266.","url":""}]},{"id":"s39-42","number":42,"surah":39,"verses":[22],"verseLabel":"الزمر: 22","question":"ما سر حذف مقابل ﴿أَفَمَنْ شَرَحَ اللَّهُ صَدْرَهُ لِلْإِسْلَامِ﴾ ثم التصريح بويل القاسية قلوبهم؟","answer":"حذف المقابل ليفوض الخيال في سعة الفرق، ثم صرح بالقاسية قلوبهم لأن القسوة هي العلة المقابلة للشرح واللين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص259–270.","url":""}]},{"id":"s39-43","number":43,"surah":39,"verses":[23],"verseLabel":"الزمر: 23","question":"ما سر وصف القرآن بأنه ﴿أَحْسَنَ الْحَدِيثِ كِتَابًا مُتَشَابِهًا مَثَانِيَ﴾؟","answer":"هو أحسن الكلام، متشابه يصدق بعضه بعضًا في الجودة، مثاني تتكرر فيه المواعظ والقصص والوعود بوجوه متجددة؛ فجمع الوحدة والتنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص271–278.","url":""}]},{"id":"s39-44","number":44,"surah":39,"verses":[23],"verseLabel":"الزمر: 23","question":"ما دلالة تدرج أثر القرآن من اقشعرار الجلود إلى لين الجلود والقلوب إلى ذكر الله؟","answer":"يقشعر الجلد أولًا من رهبة الوعيد، ثم يلين الجلد والقلب عند الرجاء والذكر؛ فانتقل الأثر من ظاهر البدن إلى باطن الوعي والطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص278–287.","url":""}]},{"id":"s39-45","number":45,"surah":39,"verses":[24],"verseLabel":"الزمر: 24","question":"ما الصورة التي يرسمها قوله ﴿أَفَمَنْ يَتَّقِي بِوَجْهِهِ سُوءَ الْعَذَابِ﴾؟","answer":"تصور إنسانًا ألجأه العذاب إلى أن يجعل أشرف أعضائه وقاية، بعدما عجزت يداه وسائر وسائل الدفاع؛ فهي صورة غاية العجز والإهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص288–293.","url":""}]},{"id":"s39-46","number":46,"surah":39,"verses":[24],"verseLabel":"الزمر: 24","question":"ما مناسبة قول ﴿ذُوقُوا مَا كُنْتُمْ تَكْسِبُونَ﴾ لمن يتقي العذاب بوجهه؟","answer":"الأمر بالذوق يجعل الجزاء خبرة مباشرة، وإضافته إلى ما كسبوا تربط ألم العذاب بأعمالهم لا بظلم واقع عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص294–299.","url":""}]},{"id":"s39-47","number":47,"surah":39,"verses":[25,26],"verseLabel":"الزمر: 25–26","question":"ما دلالة مقابلة تكذيب من قبلهم بإذاقتهم الخزي في الدنيا ووعيد الآخرة الأكبر؟","answer":"الخزي العاجل شاهد من التاريخ، وعذاب الآخرة أكبر قدرًا ودوامًا؛ فانتقل من العقوبة التي عرفت إلى ما كان ينبغي أن يحذروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص300–309.","url":""}]},{"id":"s39-48","number":48,"surah":39,"verses":[27,28],"verseLabel":"الزمر: 27–28","question":"ما سر تكرار ضرب الأمثال للناس ثم وصف القرآن بأنه عربي غير ذي عوج؟","answer":"ضرب الأمثال يقرب المعنى، وعروبة القرآن واستقامته تزيلان عذر الغموض؛ فتعدد البيان ليكون أقرب إلى تقواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص310–320.","url":""}]},{"id":"s39-49","number":49,"surah":39,"verses":[28],"verseLabel":"الزمر: 28","question":"ما دلالة وصف القرآن بأنه ﴿قُرْآنًا عَرَبِيًّا غَيْرَ ذِي عِوَجٍ﴾؟","answer":"عربي بلسانهم ليقوم الفهم، وغير ذي عوج في لفظه ومعناه وطريقه؛ فاجتمع وضوح الوسيلة واستقامة المضمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص310–320.","url":""}]},{"id":"s39-50","number":50,"surah":39,"verses":[29],"verseLabel":"الزمر: 29","question":"ما سر تمثيل الشرك برجل فيه شركاء متشاكسون والتوحيد برجل سلم لرجل واحد؟","answer":"المتشاكسون يتنازعون أمر العبد فيحار بينهم، أما السَّلَم فخالص لسيد واحد؛ فحوّل اضطراب الشرك وطمأنينة التوحيد إلى تجربة بشرية محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص321–331.","url":""}]},{"id":"s39-51","number":51,"surah":39,"verses":[30,31],"verseLabel":"الزمر: 30–31","question":"ما دلالة الانتقال من المثل إلى تقرير موت الرسول ﷺ وموت المخاطبين ثم اختصامهم عند ربهم؟","answer":"المثل يبين اختلاف العبادة، ثم الموت يسوي الأجساد، والاختصام يكشف عند الله من كان على الحق؛ فلا يحسم النزاع طول حياة أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص332–339.","url":""}]},{"id":"s39-52","number":52,"surah":39,"verses":[32],"verseLabel":"الزمر: 32","question":"ما دلالة الجمع بين الافتراء على الله وتكذيب الصدق حين جاء؟","answer":"افترى قولًا ونسبه إلى الله، ثم كذب الوحي الصادق حين بلغه؛ فجمع اختلاق الباطل ورفض الحق، وهما طرفا الجناية على المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص340–356.","url":""}]},{"id":"s39-53","number":53,"surah":39,"verses":[32,33],"verseLabel":"الزمر: 32–33","question":"ما سر مقابلة من كذب بالصدق بمن جاء بالصدق وصدق به؟","answer":"قوبل التكذيب بالصدق بمن حمل الصدق وصدّق به؛ فالمتقون يجمعون صحة الرسالة وصحة التلقي، خلاف من صنع الكذب ورد الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص348–368.","url":""}]},{"id":"s39-54","number":54,"surah":39,"verses":[33],"verseLabel":"الزمر: 33","question":"ما دلالة ترتيب المجيء بالصدق قبل التصديق به؟","answer":"المجيء بالصدق تبليغ له وإظهاره، ثم التصديق به قبول وامتثال؛ فقدم وصول الحق الذي تقوم به الحجة على موقف المتلقي منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص362–365.","url":""}]},{"id":"s39-55","number":55,"surah":39,"verses":[34,35],"verseLabel":"الزمر: 34–35","question":"ما دلالة الانتقال من كون المتقين لهم ما يشاؤون إلى تكفير أسوأ أعمالهم وجزائهم بأحسنها؟","answer":"ما يشاؤون فضل موجب، وتكفير السيئات إزالة للمانع، والجزاء بأحسن الأعمال مضاعفة للثواب؛ فجمع تمام العطاء ومحو النقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص369–387.","url":""}]},{"id":"s39-56","number":56,"surah":39,"verses":[35],"verseLabel":"الزمر: 35","question":"ما سر اختيار ﴿يُكَفِّرَ﴾ بدل «يغفر» في ﴿لِيُكَفِّرَ اللَّهُ عَنْهُمْ أَسْوَأَ الَّذِي عَمِلُوا﴾؟","answer":"التكفير ستر السيئة ومحو أثرها حتى كأنها غطيت، وهو هنا أنسب مع تعديته بـ﴿عَنْهُمْ﴾ لإفادة الإزالة والدفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص377–387.","url":""}]},{"id":"s39-57","number":57,"surah":39,"verses":[36,37],"verseLabel":"الزمر: 36–37","question":"ما دلالة المقابلة بين كفاية الله عبده وبين نفي الهادي لمن يضلله ونفي المضل لمن يهديه؟","answer":"كفاية الله تمنح الأمن، وإضلاله يمنع وجود هاد، وهدايته تمنع كل مضل؛ فالمقابلة تحصر الحفظ والهداية والتدبير فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص390–417.","url":""}]},{"id":"s39-58","number":58,"surah":39,"verses":[36,37,38],"verseLabel":"الزمر: 36–38","question":"ما سر التعبير عن الأصنام بضمير الإناث في ﴿هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ﴾؟","answer":"ضمير جمع المؤنث يستعمل لجمع غير العاقل، والأصنام كذلك، كما أن عددًا من أسمائها مؤنث؛ فوافق التعبير حقيقتها اللغوية وسياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص390–453.","url":""}]},{"id":"s39-59","number":59,"surah":39,"verses":[38],"verseLabel":"الزمر: 38","question":"ما سر تقديم الضر على الرحمة في الاحتجاج بعجز المعبودات؟","answer":"الضر أقرب إلى حمل المضطر على الدعاء وأشد كشفًا لعجز المعبودات، ثم ذكرت الرحمة لبيان أنهم لا يملكون كشف البلاء ولا منع العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص418–445.","url":""}]},{"id":"s39-60","number":60,"surah":39,"verses":[38],"verseLabel":"الزمر: 38","question":"ما دلالة ختم الحجة بقوله ﴿حَسْبِيَ اللَّهُ عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ﴾؟","answer":"بعد إبطال قدرة الأصنام أعلن كفاية الله وحده، ثم عمم التوكل في أهله؛ فانتقلت الحجة من نفي الباطل إلى عمل القلب الصحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص443–453.","url":""}]},{"id":"s39-61","number":61,"surah":39,"verses":[93],"verseLabel":"الزمر: 39؛ هود: 93","question":"ما سر التعبير هنا بـ﴿إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ﴾ بالفاء، وفي هود ﴿إِنِّي عَامِلٌ سَوْفَ تَعْلَمُونَ﴾ دونها؟","answer":"في الزمر جاء الوعيد مأمورًا بتبليغه فاشتد اتصال نتيجته بالفعل بالفاء، وفي هود صدر عن شعيب في سياق المحاورة فجاء الاستئناف دونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص454–468.","url":""}]},{"id":"s39-62","number":62,"surah":39,"verses":[39,40],"verseLabel":"الزمر: 39–40","question":"ما دلالة التهديد بالعمل على المكانة ثم تفصيل من يأتيه العذاب المخزي والمقيم؟","answer":"الأمر بالعمل على الحال تهديد بكشف العاقبة، ثم فصلها بعذاب يخزي في الدنيا وآخر مقيم لا ينقطع؛ فجمع قرب الوعيد ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص454–468.","url":""}]},{"id":"s39-63","number":63,"surah":39,"verses":[41],"verseLabel":"الزمر: 41","question":"ما سر اختيار ﴿أَنْزَلْنَا﴾ هنا بعد ﴿نَزَّلَ أَحْسَنَ الْحَدِيثِ﴾ في الآية 23؟","answer":"﴿نَزَّلَ﴾ في الآية 23 يلائم تفصيل القرآن وتكرار مثانيه، و﴿أَنْزَلْنَا﴾ هنا يقرر أصل إيصاله للناس بالحق؛ فاختيرت الصيغة بحسب زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص469–475.","url":""}]},{"id":"s39-64","number":64,"surah":39,"verses":[41],"verseLabel":"الزمر: 41","question":"ما دلالة قصر انتفاع المهتدي بالكتاب على نفسه وضرر الضال عليها؟","answer":"الهداية تعود ثمرتها على صاحبها، والضلال يعود وباله عليه؛ فليس الرسول وكيلًا يجبرهم أو يحمل تبعة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص469–484.","url":""}]},{"id":"s39-65","number":65,"surah":39,"verses":[42],"verseLabel":"الزمر: 42","question":"ما سر التعبير عن النوم والموت بتوفي الأنفس؟","answer":"التوفي استيفاء النفس وأخذها؛ ففي الموت إمساك تام، وفي النوم قبض مؤقت، ولذلك جمعهما اللفظ مع اختلاف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص485–499.","url":""}]},{"id":"s39-66","number":66,"surah":39,"verses":[42],"verseLabel":"الزمر: 42","question":"ما دلالة التفريق بين النفس التي قضى عليها الموت والتي يرسلها إلى أجل مسمى؟","answer":"يمسك التي حكم عليها بالموت فلا تعود إلى جسدها، ويرسل النائمة لتستأنف حياتها إلى أجلها؛ فالفارق في قضاء الإمساك أو الإرسال.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص489–505.","url":""}]},{"id":"s39-67","number":67,"surah":39,"verses":[43,44],"verseLabel":"الزمر: 43–44","question":"ما سر الانتقال من اتخاذ الشفعاء إلى قصر الشفاعة كلها على الله؟","answer":"أنكر اتخاذ وسطاء لا يملكون، ثم قرر أن الشفاعة كلها ملك لله؛ فلا تقع إلا بإذنه ولمن رضي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص506–524.","url":""}]},{"id":"s39-68","number":68,"surah":39,"verses":[43],"verseLabel":"الزمر: 43","question":"ما دلالة الاحتجاج على الشفعاء بأنهم لا يملكون شيئًا ولا يعقلون؟","answer":"نفي الملك يبطل قدرتهم، ونفي العقل يبطل علمهم بمن يستحق الشفاعة؛ فانتفى عنهم ركنا التصرف الصحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص511–520.","url":""}]},{"id":"s39-69","number":69,"surah":39,"verses":[45],"verseLabel":"الزمر: 45","question":"ما سر اختيار ﴿اشْمَأَزَّتْ﴾ لتصوير نفور قلوب غير المؤمنين بالآخرة عند ذكر الله وحده؟","answer":"الاشمئزاز انقباض شديد ممزوج بالنفور، فصور رد الفعل القلبي العنيف حين يفرد الله بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص525–539.","url":""}]},{"id":"s39-70","number":70,"surah":39,"verses":[45],"verseLabel":"الزمر: 45","question":"ما دلالة مقابلة اشمئزازهم عند ذكر الله وحده باستبشارهم عند ذكر الذين من دونه؟","answer":"انقبضوا من التوحيد وفرحوا بأسماء الشركاء، فالمقابلة تكشف أن الخلل ليس في أصل التذكير بل في تعلق قلوبهم بالشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص527–539.","url":""}]},{"id":"s39-71","number":71,"surah":39,"verses":[46],"verseLabel":"الزمر: 46","question":"ما مناسبة الدعاء بـ﴿اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ﴾ بعد اختلاف المشركين؟","answer":"لما تعذر اتفاقهم على الحق فوّض الحكم إلى منشئ الكون العليم بكل ظاهر وخفي؛ فهو وحده يعلم المختلف فيه ويحكم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص541–553.","url":""}]},{"id":"s39-72","number":72,"surah":39,"verses":[46],"verseLabel":"الزمر: 46","question":"ما سر تقديم ﴿فَاطِرِ﴾ على ﴿عَالِمِ﴾ والغيب على الشهادة؟","answer":"الفطر أصل إيجاد العالم، والعلم إحاطة بما يجري فيه؛ وقدم الغيب لأنه أخفى وأدل على كمال العلم ثم أتبع بالشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص545–549.","url":""}]},{"id":"s39-73","number":73,"surah":39,"verses":[47,48],"verseLabel":"الزمر: 47–48","question":"ما دلالة تكرار ﴿وَبَدَا لَهُمْ﴾ عند ظهور سوء العمل ثم إحاطة ما كانوا يستهزئون به؟","answer":"الأول ظهور مفاجئ لحقائق أعمال لم يحسبوها، والثاني تحقق الجزاء الذي سخروا منه؛ فكرر اللفظ لتوالي انكشاف الجريمة والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص554–576.","url":""}]},{"id":"s39-74","number":74,"surah":39,"verses":[47],"verseLabel":"الزمر: 47","question":"ما سر فرض امتلاك الظالمين ما في الأرض ومثله معه ليفتدوا به من سوء العذاب؟","answer":"بلغ الفرض أقصى ما يتصوره الإنسان من ملك مضاعف، ثم نفى إمكان الافتداء؛ ليبين أن عذاب الآخرة لا تدفعه أثمان الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص554–562.","url":""}]},{"id":"s39-75","number":75,"surah":39,"verses":[49,50,51],"verseLabel":"الزمر: 49–51","question":"ما دلالة تكرار نموذج الإنسان الذي يدعو عند الضر ثم يزعم أن النعمة أوتيها على علم؟","answer":"تكرار النموذج يثبت أنه طبع ممتد في الإنسان والأمم: يلجأ عند الضر، ثم ينسب النعمة إلى علمه، فتأتي الفتنة والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص577–607.","url":""}]},{"id":"s39-76","number":76,"surah":39,"verses":[49],"verseLabel":"الزمر: 49","question":"ما سر اختيار ﴿خَوَّلْنَاهُ نِعْمَةً مِنَّا﴾ ثم حكاية قوله ﴿إِنَّمَا أُوتِيتُهُ عَلَى عِلْمٍ﴾؟","answer":"﴿خَوَّلْنَاهُ﴾ يثبت أن النعمة منحة وتمكين منا، بينما المبني للمجهول في قوله يوهم انفصالها عن المنعم واستحقاقه لها بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص577–592.","url":""}]},{"id":"s39-77","number":77,"surah":39,"verses":[51],"verseLabel":"الزمر: 51","question":"ما دلالة مقابلة إصابة السابقين بسيئات ما كسبوا بوعيد الظالمين الحاضرين بمثلها؟","answer":"أصاب السابقين جزاء ما كسبوا، ثم نقل السنّة إلى ظالمي الحاضر؛ فالتاريخ ليس خبرًا منقطعًا بل إنذار بعاقبة مماثلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص599–607.","url":""}]},{"id":"s39-78","number":78,"surah":39,"verses":[52],"verseLabel":"الزمر: 52","question":"ما سر ذكر الرزق مع البسط وحذفه مع التقدير في ﴿يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ﴾؟","answer":"ذُكر الرزق أولًا لتعيين مجال البسط، ثم حذف مع ﴿يَقْدِرُ﴾ لدلالة المقابلة عليه وتجنب التكرار؛ فالإيجاز يزيد تلاحم الضدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص608–617.","url":""}]},{"id":"s39-79","number":79,"surah":39,"verses":[53],"verseLabel":"الزمر: 53","question":"ما سر نداء المسرفين بقوله ﴿يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ﴾؟","answer":"أضاف المسرفين إلى عبوديته مع جنايتهم ليفتح باب الأمل، ووصف إسرافهم بأنه على أنفسهم ليبين أن ضرره عائد إليهم لا إلى ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص618–623.","url":""}]},{"id":"s39-80","number":80,"surah":39,"verses":[53],"verseLabel":"الزمر: 53","question":"ما دلالة الجمع بين النهي عن القنوط وعموم مغفرة الذنوب؟","answer":"النهي يعالج اليأس، وعموم المغفرة يزيل سببه مهما كثرت الذنوب؛ وهو وعد لمن رجع قبل فوات زمن التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص623–628.","url":""}]},{"id":"s39-81","number":81,"surah":39,"verses":[53],"verseLabel":"الزمر: 53","question":"ما مناسبة تقديم ﴿الْغَفُورُ﴾ على ﴿الرَّحِيمُ﴾ في آية الرجاء؟","answer":"المقام مقام ذنوب تحتاج أولًا إلى ستر ومحو، فقدم الغفور، ثم الرحيم الذي يتفضل بعد إزالة أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص625–628.","url":""}]},{"id":"s39-82","number":82,"surah":39,"verses":[54,55],"verseLabel":"الزمر: 54–55","question":"ما سر ترتيب الإنابة ثم الإسلام ثم اتباع أحسن ما أنزل قبل مجيء العذاب؟","answer":"الإنابة رجوع القلب، والإسلام انقياد النفس، والاتباع ترجمة ذلك في العمل؛ فرتبت مراحل التوبة قبل مباغتة العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص629–641.","url":""}]},{"id":"s39-83","number":83,"surah":39,"verses":[56],"verseLabel":"الزمر: 56","question":"ما دلالة تحسر النفس بقولها ﴿يَا حَسْرَتَى عَلَى مَا فَرَّطْتُ فِي جَنْبِ اللَّهِ﴾؟","answer":"النداء يخرج الحسرة كأنها شيء يستدعى لشدة حضورها، و﴿فِي جَنْبِ اللَّهِ﴾ تعني التفريط في حقه وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص642–651.","url":""}]},{"id":"s39-84","number":84,"surah":39,"verses":[56],"verseLabel":"الزمر: 56","question":"ما معنى قول المفرط ﴿فِي جَنْبِ اللَّهِ﴾؟","answer":"المراد ما فرط في حق الله وأوامره، لا إثبات جارحة؛ فهو تعبير عن جانب الطاعة والحق الواجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص642–651.","url":""}]},{"id":"s39-85","number":85,"surah":39,"verses":[56,57,58],"verseLabel":"الزمر: 56–58","question":"ما دلالة ترتيب أعذار النفس من الحسرة على التفريط إلى تمني الهداية ثم تمني الرجعة؟","answer":"بدأت باعتراف متأخر بالتقصير، ثم نسبت الفوات إلى غياب الهداية، ثم طلبت فرصة جديدة؛ فتدرجت الأعذار مع بقاء المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص642–664.","url":""}]},{"id":"s39-86","number":86,"surah":39,"verses":[58],"verseLabel":"الزمر: 58","question":"ما سر تقديم رؤية العذاب على تمني الكرة والعمل من المحسنين؟","answer":"لم يتمن الرجعة حتى عاين العذاب، فدل الترتيب على أن الدافع اضطرار المشاهدة لا اختيار الإيمان بالغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص653–664.","url":""}]},{"id":"s39-87","number":87,"surah":39,"verses":[59],"verseLabel":"الزمر: 59","question":"ما دلالة الرد على أعذار النفس بقوله ﴿بَلَى قَدْ جَاءَتْكَ آيَاتِي﴾ ثم عدول الخطاب إلى جمع الكافرين؟","answer":"﴿بَلَى﴾ تبطل دعوى عدم الهداية وتثبت مجيء الآيات، ثم عمم الحكم على الكافرين لأن هذه النفس مثال لكل من كذب واستكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص665–676.","url":""}]},{"id":"s39-88","number":88,"surah":39,"verses":[60],"verseLabel":"الزمر: 60","question":"ما دلالة تصوير وجوه الذين كذبوا على الله مسودة يوم القيامة؟","answer":"اسوداد الوجوه يجعل كذب الباطن علامة ظاهرة لا تستر، ويقابل نور الوجوه ونجاة المتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص677–685.","url":""}]},{"id":"s39-89","number":89,"surah":39,"verses":[60],"verseLabel":"الزمر: 60","question":"ما مناسبة ختم الآية بوصفهم بالمتكبرين؟","answer":"التكبر هو الذي حملهم على اختلاق القول ورد الآيات؛ فجاء الوصف في الخاتمة كاشفًا لجذر الكذب ومستحق المأوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص680–685.","url":""}]},{"id":"s39-90","number":90,"surah":39,"verses":[61],"verseLabel":"الزمر: 61","question":"ما دلالة التعبير بأن الله ينجي المتقين ﴿بِمَفَازَتِهِمْ﴾؟","answer":"المفازة مصدر بمعنى الفوز واسم لموضع النجاة؛ فالتعبير يصور تقواهم سببًا وطريقًا ينجون به إلى مأمنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص686–697.","url":""}]},{"id":"s39-91","number":91,"surah":39,"verses":[61],"verseLabel":"الزمر: 61","question":"ما سر تقديم نفي مس السوء على نفي الحزن عن المتقين؟","answer":"مس السوء ضرر يقع من الخارج، والحزن ألم يقوم في الداخل؛ فقدم السلامة من العذاب ثم أتبع براحة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص691–697.","url":""}]},{"id":"s39-92","number":92,"surah":39,"verses":[62,63],"verseLabel":"الزمر: 62–63","question":"ما دلالة الجمع بين كون الله خالق كل شيء ووكيله وامتلاكه مقاليد السماوات والأرض؟","answer":"الخلق يثبت الإيجاد، والوكالة دوام الحفظ والتدبير، والمقاليد تمام الملك والتصرف؛ فجمعت الآيتان بدء الأشياء وبقاءها وسلطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص698–717.","url":""}]},{"id":"s39-93","number":93,"surah":39,"verses":[63],"verseLabel":"الزمر: 63","question":"ما الصورة التي يرسمها التعبير بـ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"المقاليد مفاتيح الخزائن، فصورت أرزاق السماوات والأرض وتدبيرها مغلقة على سلطان واحد لا يفتحها ولا يمسكها سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص706–717.","url":""}]},{"id":"s39-94","number":94,"surah":39,"verses":[64],"verseLabel":"الزمر: 64","question":"ما دلالة تقديم ﴿غَيْرَ اللَّهِ﴾ في الإنكار ﴿أَفَغَيْرَ اللَّهِ تَأْمُرُونِّي أَعْبُدُ﴾؟","answer":"تقديم ﴿غَيْرَ اللَّهِ﴾ يوجه الإنكار إلى المعبود المقترح نفسه: أهذا الغير تأمرونني أن أعبد مع وضوح انفراد الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص717–727.","url":""}]},{"id":"s39-95","number":95,"surah":39,"verses":[64],"verseLabel":"الزمر: 64","question":"ما سر وصف الآمرين بالشرك بالجهل بدل الكفر؟","answer":"الجهل وصف للسبب الذي أفسد أمرهم؛ إذ سووا المخلوق بالخالق مع قيام الدلائل، فليس أمرهم مبنيًا على معرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص724–727.","url":""}]},{"id":"s39-96","number":96,"surah":39,"verses":[65],"verseLabel":"الزمر: 65","question":"ما دلالة توجيه التحذير من الشرك إلى النبي ﷺ والرسل من قبله؟","answer":"توجيه الشرط المستحيل إلى أعظم الناس توحيدًا يبين فظاعة الشرك وعموم حكمه، فلا محاباة فيه لنبي ولا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص728–740.","url":""}]},{"id":"s39-97","number":97,"surah":39,"verses":[65],"verseLabel":"الزمر: 65","question":"ما سر إسناد الحبوط إلى العمل وتقديمه على الخسران؟","answer":"الحبوط يصيب العمل فيبطله ويمحو ثمرته، ولذلك قدم لأنه سبب الخسران الذي يجيء نتيجة بعد ضياع الرصيد كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص735–740.","url":""}]},{"id":"s39-98","number":98,"surah":39,"verses":[66],"verseLabel":"الزمر: 66","question":"ما دلالة تقديم اسم الجلالة في ﴿بَلِ اللَّهَ فَاعْبُدْ﴾ وتقديم العبادة على الشكر؟","answer":"تقديم اسم الله يقصر العبادة عليه ردًا على أمرهم بالشرك، وتقديم العبادة لأنها أصل، ثم يكون الشكر أثر معرفة النعمة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص741–748.","url":""}]},{"id":"s39-99","number":99,"surah":39,"verses":[67],"verseLabel":"الزمر: 67","question":"ما سر تكرار مادة القدر في ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾؟","answer":"التكرار يوبخهم على تقصير مزدوج: لم يعرفوا عظمة الله المعرفة التي تليق، ولم يعاملوه بحسب قدره وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص749–752.","url":""}]},{"id":"s39-100","number":100,"surah":39,"verses":[67],"verseLabel":"الزمر: 67","question":"ما دلالة تصوير الأرض جميعًا قبضة الله يوم القيامة والسماوات مطويات بيمينه؟","answer":"الصورة تقرب سلطانًا لا تحده المقاييس: الأرض كلها في قبضته والسماوات مطويات؛ فتتضاءل المعبودات والكون أمام قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص752–757.","url":""}]},{"id":"s39-101","number":101,"surah":39,"verses":[68],"verseLabel":"الزمر: 68","question":"ما دلالة بناء ﴿نُفِخَ فِي الصُّورِ﴾ للمجهول وتكرار النفخ؟","answer":"حذف النافخ لأن المقصود هول الحدث وآثاره بأمر الله، وتكرار الفعل يفصل نفخة الصعق عن نفخة القيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص758–771.","url":""}]},{"id":"s39-102","number":102,"surah":39,"verses":[68],"verseLabel":"الزمر: 68","question":"ما سر التعبير بـ﴿ثُمَّ نُفِخَ فِيهِ أُخْرَى﴾ دون «نفخة ثانية»؟","answer":"أقيمت الصفة ﴿أُخْرَى﴾ مقام النفخة لدلالة السياق، فركز التعبير على مغايرتها للأولى وأوجز تكرار الموصوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص765–769.","url":""}]},{"id":"s39-103","number":103,"surah":39,"verses":[69,70],"verseLabel":"الزمر: 69–70","question":"ما دلالة ترتيب إشراق الأرض بنور ربها ووضع الكتاب والإتيان بالنبيين والشهداء والقضاء بالحق؟","answer":"بدأ ظهور مشهد العدل بالنور، ثم سجل الأعمال، ثم شهود البلاغ والعمل، ثم الحكم والوفاء؛ فترتب القضاء من الإظهار إلى الإثبات فالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص772–793.","url":""}]},{"id":"s39-104","number":104,"surah":39,"verses":[69],"verseLabel":"الزمر: 69","question":"ما سر تقديم وضع الكتاب على الإتيان بالنبيين والشهداء؟","answer":"الكتاب هو السجل المرجعي الذي تضبط به الدعوى والشهادة، فقدم وضعه ثم جيء بمن يشهد على ضوئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص778–782.","url":""}]},{"id":"s39-105","number":105,"surah":39,"verses":[19,71],"verseLabel":"الزمر: 19، 71","question":"ما سر التعبير أولًا بـ﴿حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ﴾ بالتذكير، ثم ﴿حَقَّتْ كَلِمَةُ الْعَذَابِ﴾ بالتأنيث؟","answer":"التذكير جائز لأن تأنيث ﴿كلمة﴾ غير حقيقي، والتأنيث يوافق لفظها صراحة؛ فنوّع الأسلوب مع بقاء الحكم واحدًا، ولا يلزم ربطه بكثرة المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص215–225، 793–821.","url":""}]},{"id":"s39-106","number":106,"surah":39,"verses":[71,73],"verseLabel":"الزمر: 71، 73","question":"ما سر استعمال الفعل نفسه ﴿سِيقَ﴾ للكافرين والمتقين؟","answer":"السوق جمع وحركة إلى المصير بأمر الله، ويختلف حاله باختلاف الوجهة والاستقبال: سوق إهانة إلى النار وسوق تكريم إلى الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص793–821؛ ج51، ص1–19.","url":""}]},{"id":"s39-107","number":107,"surah":39,"verses":[71,73],"verseLabel":"الزمر: 71، 73","question":"ما سر التعبير في النار بـ﴿فُتِحَتْ أَبْوَابُهَا﴾، وفي الجنة بـ﴿وَفُتِحَتْ أَبْوَابُهَا﴾ بالواو؟","answer":"في النار جعل الفتح جواب بلوغهم ففوجئوا به، وفي الجنة أفادت الواو أن الأبواب مفتحة أو أن عندها حالًا مقدرًا من التكريم؛ فناسبت كرامة الاستقبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص793–821؛ ج51، ص1–19.","url":""}]},{"id":"s39-108","number":108,"surah":39,"verses":[71,72],"verseLabel":"الزمر: 71–72","question":"ما دلالة سؤال خزنة جهنم للكافرين عن مجيء الرسل قبل الأمر بدخولها؟","answer":"السؤال يقيم عليهم الحجة باعترافهم أن الرسل بلغوا، ثم يأتي الأمر بالدخول بعد سقوط العذر؛ فيظهر أن الجزاء حكم عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص794–823.","url":""}]},{"id":"s39-109","number":109,"surah":39,"verses":[72],"verseLabel":"الزمر: 72","question":"ما مناسبة وصف أهل النار بالمتكبرين في ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾؟","answer":"لأن التكبر حملهم على رد الرسل والآيات، سمي المثوى باسم علتهم الأخلاقية؛ فالجزاء يطابق الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص814–823.","url":""}]},{"id":"s39-110","number":110,"surah":39,"verses":[73],"verseLabel":"الزمر: 73","question":"ما دلالة قول خزنة الجنة للمتقين ﴿سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾؟","answer":"السلام أمان، و﴿طِبْتُمْ﴾ تزكية للنفوس والأعمال، والفاء تجعل الدخول ثمرة لهذا الطيب، والخلود تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص1–10.","url":""}]},{"id":"s39-111","number":111,"surah":39,"verses":[74],"verseLabel":"الزمر: 74","question":"ما دلالة انتقال أهل الجنة من حمد الله على صدق وعده إلى قولهم ﴿نَتَبَوَّأُ مِنَ الْجَنَّةِ حَيْثُ نَشَاءُ﴾؟","answer":"صدق الوعد يقرر أصل النعمة، والتبوؤ حيث يشاؤون يبين سعتها وتمكنهم منها؛ فانتقل الحمد من الوفاء إلى تفاصيل التملك الكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص11–18.","url":""}]},{"id":"s39-112","number":112,"surah":39,"verses":[75],"verseLabel":"الزمر: 75","question":"ما سر التعبير بـ﴿حَافِّينَ مِنْ حَوْلِ الْعَرْشِ﴾ دون «حافين حول العرش»؟","answer":"﴿مِنْ﴾ تفيد ابتداء نطاق الإحاطة والقرب، فتدل على أن صفوفهم تبدأ من حول العرش من غير فراغ متوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص19–37.","url":""}]},{"id":"s39-113","number":113,"surah":39,"verses":[75],"verseLabel":"الزمر: 75","question":"ما دلالة الجمع بين إحاطة الملائكة بالعرش وتسبيحهم بحمد ربهم؟","answer":"إحاطتهم تصور انتظامهم وقربهم في مقام الطاعة، والتسبيح بحمد الرب يجمع تنزيهه والثناء عليه عند تمام القضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص19–28.","url":""}]},{"id":"s39-114","number":114,"surah":39,"verses":[75],"verseLabel":"الزمر: 75","question":"ما سر بناء ﴿قُضِيَ بَيْنَهُمْ بِالْحَقِّ﴾ و﴿قِيلَ الْحَمْدُ لِلَّهِ﴾ للمجهول؟","answer":"حذف الفاعل لأن المقصود ظهور عدل القضاء وشيوع الحمد لا تعيين القائل؛ فامتلأ المشهد حكمًا بالحق وثناءً عامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص29–37.","url":""}]},{"id":"s39-115","number":115,"surah":39,"verses":[75],"verseLabel":"الزمر: 75","question":"ما مناسبة ختم السورة بقوله ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾؟","answer":"بدأت السورة بتنزيل الكتاب من رب العالمين في المعنى، وختمت بحمده بعد نفاذ حكمه؛ فالحمد إعلان أن الخلق والتشريع والجزاء كلها حق وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص31–37.","url":""}]},{"id":"s40-1","number":1,"surah":40,"verses":[1],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«غافر»، وما صلة الاسم بمطلعها ومحورها؟","answer":"اسم غافر يفتح السورة برجاء المغفرة وسط جدال الكافرين وشدة العقاب؛ فمحورها دعوة المذنب إلى الرجوع قبل المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص47–55.","url":""}]},{"id":"s40-2","number":2,"surah":40,"verses":[1],"verseLabel":"عنوان السورة","question":"ما دلالة تسمية السورة أيضًا بـ«المؤمن»؟","answer":"تستحضر مؤمن آل فرعون الذي دافع عن الحق بالحجة وسط الطغيان؛ فصار نموذج الإيمان الكاتم ثم المعلن محورًا مميزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص49–53.","url":""}]},{"id":"s40-3","number":3,"surah":40,"verses":[1,2,3],"verseLabel":"غافر: 1–3","question":"ما سر افتتاح أولى الحواميم بـ﴿حم﴾ ثم وصف القرآن بأنه تنزيل من الله العزيز العليم؟","answer":"الحروف تفتتح سلسلة الحواميم، ثم ينسب التنزيل إلى العزيز الذي لا يغلب والعليم الذي لا يخفى عليه جدالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص57–65.","url":""}]},{"id":"s40-4","number":4,"surah":40,"verses":[2],"verseLabel":"غافر: 2","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْعَلِيمِ﴾ في مصدر التنزيل؟","answer":"العزة تضمن نفاذ الوحي وقهر المعارض، والعلم يضمن إحكامه؛ وقدمت القوة لمقام مواجهة المجادلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص59–65.","url":""}]},{"id":"s40-5","number":5,"surah":40,"verses":[3],"verseLabel":"غافر: 3","question":"ما دلالة الجمع بين ﴿غَافِرِ الذَّنْبِ﴾ و﴿قَابِلِ التَّوْبِ﴾؟","answer":"غفران الذنب ستر ومحو للسيئة، وقبول التوب استقبال لرجوع صاحبها؛ فجمع أثر الرحمة في العمل والعامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص65–70.","url":""}]},{"id":"s40-6","number":6,"surah":40,"verses":[3],"verseLabel":"غافر: 3","question":"ما سر الجمع بين المغفرة وقبول التوبة وشدة العقاب والطَّول في تعريف الله؟","answer":"المغفرة والتوبة تفتحان الرجاء، وشدة العقاب تمنع الأمن، والطول يدل على الفضل والسعة؛ فتعريف جامع للخوف والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص65–75.","url":""}]},{"id":"s40-7","number":7,"surah":40,"verses":[3],"verseLabel":"غافر: 3","question":"ما دلالة فصل ﴿إِلَيْهِ الْمَصِيرُ﴾ وتقديم الجار والمجرور؟","answer":"الفصل يمنح المصير حكمًا مستقلًا، وتقديم ﴿إِلَيْهِ﴾ يقصر المرجع عليه وحده بعد نفي الإله غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص75–77.","url":""}]},{"id":"s40-8","number":8,"surah":40,"verses":[4],"verseLabel":"غافر: 4","question":"ما سر قصر المجادلة في آيات الله على الكافرين؟","answer":"الجدال المذموم إنكار للحق بعد ظهوره، وهذه صفة الكافر؛ أما حوار طالب الفهم أو المدافع عن الحق فليس داخلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص78–87.","url":""}]},{"id":"s40-9","number":9,"surah":40,"verses":[4],"verseLabel":"غافر: 4","question":"ما دلالة النهي عن الاغترار بتقلب الكافرين في البلاد بعد ذكر جدالهم؟","answer":"انتقالهم في التجارة والسلطان متاع مؤقت لا يثبت صحة الجدال؛ فلا يخدع الظاهر عن عاقبة الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص82–87.","url":""}]},{"id":"s40-10","number":10,"surah":40,"verses":[5],"verseLabel":"غافر: 5","question":"ما دلالة جمع تكذيب قوم نوح والأحزاب وهمِّ كل أمة بأخذ رسولها؟","answer":"قوم نوح أصل المثال، والأحزاب تتابعه، والهمّ بأخذ الرسول ذروة العدوان؛ فجمع تاريخ التكذيب من القول إلى البطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص87–98.","url":""}]},{"id":"s40-11","number":11,"surah":40,"verses":[5],"verseLabel":"غافر: 5","question":"ما الصورة التي يرسمها قوله ﴿وَجَادَلُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"الدحض إسقاط وزلق؛ فصور الباطل أداة يحاولون بها إزلاق الحق الثابت، لكن محاولة الساقط إسقاط الثابت تنقلب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص94–103.","url":""}]},{"id":"s40-12","number":12,"surah":40,"verses":[5,6],"verseLabel":"غافر: 5–6","question":"ما دلالة الانتقال من أخذ الأمم المكذبة إلى ثبوت كلمة العذاب على الكافرين؟","answer":"الأخذ التاريخي شاهد، ثم عمم إلى كلمة ثابتة على كل كافر؛ فانتقل من أمثلة العقوبة إلى سنتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص99–109.","url":""}]},{"id":"s40-13","number":13,"surah":40,"verses":[7],"verseLabel":"غافر: 7","question":"ما سر تقديم تسبيح حملة العرش وإيمانهم على استغفارهم للمؤمنين؟","answer":"التسبيح والإيمان يثبتان طهارتهم ومعرفتهم بالله، ومن هذا المقام الصالح يصدر استغفارهم المقبول لإخوانهم المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص110–116.","url":""}]},{"id":"s40-14","number":14,"surah":40,"verses":[7],"verseLabel":"غافر: 7","question":"ما دلالة تقديم الرحمة على العلم في دعاء الملائكة ﴿رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾؟","answer":"قدموا الرحمة لأنها مطلوب الدعاء ومناط المغفرة، ثم العلم الذي يحيط بمن يستحقها؛ فالأول رجاء والثاني حكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص116–124.","url":""}]},{"id":"s40-15","number":15,"surah":40,"verses":[7,8],"verseLabel":"غافر: 7–8","question":"ما دلالة انتقال دعاء الملائكة من المغفرة والوقاية إلى إدخال جنات عدن وجمع المؤمن بأهله الصالحين؟","answer":"بدأ برفع العذاب، ثم طلب النعيم الدائم، ثم تمام الأنس بالأهل الصالحين؛ فتدرج من النجاة الفردية إلى السعادة الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص119–137.","url":""}]},{"id":"s40-16","number":16,"surah":40,"verses":[8],"verseLabel":"غافر: 8","question":"ما سر التعبير بـ﴿جَنَّاتِ عَدْنٍ﴾ في دعاء حملة العرش؟","answer":"العدن إقامة واستقرار، فدعاؤهم لا يطلب دخولًا عابرًا بل جنات خلود لا تحول عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص123–132.","url":""}]},{"id":"s40-17","number":17,"surah":40,"verses":[9],"verseLabel":"غافر: 9","question":"ما دلالة الجمع بين الوقاية من السيئات والرحمة والفوز العظيم؟","answer":"الوقاية تمنع تبعات السيئات، والرحمة تمنح الخير فوق النجاة، وهذا الجمع هو الفوز الكامل العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص136–145.","url":""}]},{"id":"s40-18","number":18,"surah":40,"verses":[10],"verseLabel":"غافر: 10","question":"ما سر بناء ﴿يُنَادَوْنَ﴾ للمجهول في توبيخ أهل النار؟","answer":"حذف المنادي لأن العبرة بفظاعة النداء لا قائله، وليبدو التوبيخ صادرًا في الموقف كله لا من جهة محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص146–154.","url":""}]},{"id":"s40-19","number":19,"surah":40,"verses":[10],"verseLabel":"غافر: 10","question":"ما دلالة كون مقت الله لهم أكبر من مقتهم أنفسهم؟","answer":"مقتهم أنفسهم جاء بعد انكشاف الخسران، أما مقت الله لهم فكان حين دعوا إلى الإيمان فكفروا؛ وسبب الحكم أعظم من أثره المتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص149–158.","url":""}]},{"id":"s40-20","number":20,"surah":40,"verses":[11],"verseLabel":"غافر: 11","question":"ما سر انتقال أهل النار من الاعتراف بالذنوب إلى سؤالهم ﴿فَهَلْ إِلَى خُرُوجٍ مِنْ سَبِيلٍ﴾؟","answer":"اعترفوا بسبب الاستحقاق ثم بحثوا عن منفذ عملي، لكن السؤال جاء بعد انقضاء زمن التوبة؛ فصار الاعتراف بلا ثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص164–171.","url":""}]},{"id":"s40-21","number":21,"surah":40,"verses":[12],"verseLabel":"غافر: 12","question":"ما وجه الأسلوب الحكيم في جواب طلب الخروج ببيان موقفهم من التوحيد والشرك؟","answer":"لم يجبهم بنعم أو لا، بل كشف سبب استحالة الخروج: رفضوا التوحيد وقبلوا الشرك؛ فالعلاج كان في الدنيا لا بعد الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص172–184.","url":""}]},{"id":"s40-22","number":22,"surah":40,"verses":[12],"verseLabel":"غافر: 12","question":"ما سر اختلاف بناء الشرطين في ﴿إِذَا دُعِيَ اللَّهُ وَحْدَهُ كَفَرْتُمْ وَإِنْ يُشْرَكْ بِهِ تُؤْمِنُوا﴾؟","answer":"﴿إِذَا﴾ لما تكرر وقوعه من دعوتهم إلى التوحيد، و﴿إِنْ﴾ لصورة إشراك أي شريك؛ فخالف الأسلوب بحسب تحقق الحال وفرضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص176–180.","url":""}]},{"id":"s40-23","number":23,"surah":40,"verses":[12],"verseLabel":"غافر: 12","question":"ما مناسبة ختم الحكم لله باسمي ﴿الْعَلِيِّ الْكَبِيرِ﴾؟","answer":"العلي فوق شركائهم وحكمهم، والكبير المتعالي عن كل ند؛ فالاسمان يحسمان سلطة القضاء ووحدة الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص180–184.","url":""}]},{"id":"s40-24","number":24,"surah":40,"verses":[13],"verseLabel":"غافر: 13","question":"ما سر الجمع بين إراءة الله آياته وإنزال الرزق من السماء؟","answer":"الآيات هداية للعقل والرزق حياة للجسد؛ فجمع البرهان والنعمة ليقودا معًا إلى معرفة المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص185–195.","url":""}]},{"id":"s40-25","number":25,"surah":40,"verses":[13],"verseLabel":"غافر: 13","question":"ما دلالة تسمية المطر النازل من السماء ﴿رِزْقًا﴾؟","answer":"سمي المطر رزقًا باعتبار ما ينشأ عنه من نبات وأقوات، فاستحضر الأثر المقصود لا مجرد الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص189–193.","url":""}]},{"id":"s40-26","number":26,"surah":40,"verses":[14],"verseLabel":"غافر: 14","question":"ما دلالة الأمر بإخلاص الدين لله ولو كره الكافرون؟","answer":"الإخلاص حق لله لا يتغير برضا الناس؛ وذكر كراهتهم يثبت قيمة الثبات حين يعارض المجتمع التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص196–202.","url":""}]},{"id":"s40-27","number":27,"surah":40,"verses":[15],"verseLabel":"غافر: 15","question":"ما سر توالي الأوصاف بلا عطف في ﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ يُلْقِي الرُّوحَ﴾؟","answer":"تتابع الأوصاف يصور كمالات متصلة لا تحتاج وصلًا: علو الدرجات، وملك العرش، وإحياء القلوب بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص203–214.","url":""}]},{"id":"s40-28","number":28,"surah":40,"verses":[15],"verseLabel":"غافر: 15","question":"ما سر تسمية الوحي ﴿الرُّوحَ﴾ وتعدية إلقائه بـ﴿عَلَى﴾؟","answer":"الوحي يحيي القلوب كما تحيي الروح الأجساد، و﴿عَلَى﴾ تشعر بنزوله من علو وتمكنه ممن اصطفاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص209–216.","url":""}]},{"id":"s40-29","number":29,"surah":40,"verses":[15,16],"verseLabel":"غافر: 15–16","question":"ما سر تسمية القيامة ﴿يَوْمَ التَّلَاقِ﴾ ثم وصف الخلق بأنهم ﴿بَارِزُونَ﴾؟","answer":"التلاقي يجمع الخالق بالخلق والناس بعضهم ببعض، والبروز يكشفهم بلا ساتر؛ فالمشهد اجتماع وانكشاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص215–221.","url":""}]},{"id":"s40-30","number":30,"surah":40,"verses":[16],"verseLabel":"غافر: 16","question":"ما سر سؤال ﴿لِمَنِ الْمُلْكُ الْيَوْمَ﴾ ثم ذكر جوابه ﴿لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾؟","answer":"السؤال يقرر زوال كل ملك مدعى، والجواب يحصره في الواحد بلا شريك القهار الذي خضع له الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص219–227.","url":""}]},{"id":"s40-31","number":31,"surah":40,"verses":[54],"verseLabel":"غافر: 17؛ يس: 54","question":"ما سر تقديم الجزاء في ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ بِمَا كَسَبَتْ لَا ظُلْمَ الْيَوْمَ﴾، بينما قُدّم نفي الظلم في يس؟","answer":"غافر في مقام إعلان يوم الجزاء فقدم الحكم ثم نفى الظلم، ويس في مقام تطمين المحاسبين فقدم نفي الظلم قبل تفصيل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص228–239.","url":""}]},{"id":"s40-32","number":32,"surah":40,"verses":[17],"verseLabel":"غافر: 17","question":"ما دلالة تكرار ﴿الْيَوْمَ﴾ في تقرير الجزاء ونفي الظلم؟","answer":"كرر اليوم لاستحضار الموقف وتعظيمه: فيه يقع الجزاء وفيه يختفي الظلم؛ فتعلق الحكمان بزمن واحد حاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص228–239.","url":""}]},{"id":"s40-33","number":33,"surah":40,"verses":[18],"verseLabel":"غافر: 18","question":"ما سر العدول عن اسم القيامة إلى ﴿الْآزِفَةِ﴾ وتصوير القلوب لدى الحناجر؟","answer":"الآزفة القريبة تدفع وهم البعد، وبلوغ القلوب الحناجر يصور رعبًا يصعد من الداخل حتى يخنق النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص240–248.","url":""}]},{"id":"s40-34","number":34,"surah":40,"verses":[18],"verseLabel":"غافر: 18","question":"ما سر الجمع بين نفي الحميم ونفي الشفيع المطاع عن الظالمين؟","answer":"الحميم قريب مشفق، والشفيع صاحب وساطة مسموعة؛ فنفى العون بالمودة والعون بالجاه معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص248–254.","url":""}]},{"id":"s40-35","number":35,"surah":40,"verses":[19],"verseLabel":"غافر: 19","question":"ما وجه فرادة التعبير في ﴿يَعْلَمُ خَائِنَةَ الْأَعْيُنِ﴾؟","answer":"الخائنة النظرة المسارقة التي يظهر صاحبها غير ما يبطن؛ فحوّل الفعل الخفي العابر إلى شيء معلوم مكشوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص255–261.","url":""}]},{"id":"s40-36","number":36,"surah":40,"verses":[19],"verseLabel":"غافر: 19","question":"ما سر مقابلة خائنة الأعين بما تخفي الصدور؟","answer":"العين تكشف أول حركة خفية، والصدر يخزن مقصدها وما هو أعمق؛ فعلم الله يحيط بالإشارة والنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص259–264.","url":""}]},{"id":"s40-37","number":37,"surah":40,"verses":[20],"verseLabel":"غافر: 20","question":"ما دلالة مقابلة قضاء الله بالحق بعجز المدعوين من دونه عن القضاء بشيء؟","answer":"حكمه مطابق للحق علمًا وقدرة، ومعبوداتهم لا تملك أصل القضاء؛ فقوبل كمال الفعل بانعدامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص265–273.","url":""}]},{"id":"s40-38","number":38,"surah":40,"verses":[20],"verseLabel":"غافر: 20","question":"ما مناسبة ختم المقابلة بقوله ﴿إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"السميع يسمع الدعوى والدعاء، والبصير يرى العمل والحال؛ لذلك يقضي بالحق ولا تخفى عليه بينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص269–273.","url":""}]},{"id":"s40-39","number":39,"surah":40,"verses":[21],"verseLabel":"غافر: 21","question":"ما دلالة جمع قوة الأمم السابقة وآثارها في الأرض ثم بيان أن الله أخذهم بذنوبهم؟","answer":"القوة والعمارة لم تمنع الأخذ لأن الذنوب أفسدت أساس الحماية؛ فالعبرة بعلاقة القوة بالله لا بكثرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص274–287.","url":""}]},{"id":"s40-40","number":40,"surah":40,"verses":[21],"verseLabel":"غافر: 21","question":"ما سر زيادة ضمير الفصل في ﴿كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً﴾ وحذفه في نظائر أخرى؟","answer":"ضمير الفصل يبرز أنهم بالذات كانوا أشد من مكذبي مكة، ومع ذلك هلكوا؛ فزاد قوة المقارنة والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص274–296.","url":""}]},{"id":"s40-41","number":41,"surah":40,"verses":[6],"verseLabel":"غافر: 22؛ التغابن: 6","question":"ما سر التعبير هنا بـ﴿ذَلِكَ بِأَنَّهُمْ كَانَتْ تَأْتِيهِمْ رُسُلُهُمْ﴾، وفي التغابن ﴿ذَلِكَ بِأَنَّهُ كَانَتْ تَأْتِيهِمْ﴾؟","answer":"في غافر عاد الضمير إلى الأمم المتعددة فجمع رسلهم، وفي التغابن عاد إلى الأمر أو الشأن المفرد؛ فاختلف المرجع والسياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص274–296.","url":""}]},{"id":"s40-42","number":42,"surah":40,"verses":[22],"verseLabel":"غافر: 22","question":"ما دلالة الجمع بين كفر الأمم وأخذ الله لهم ووصفه بالقوي شديد العقاب؟","answer":"الكفر سبب مكتسب، والأخذ أثر عدل، والقوة وشدة العقاب تضمنان نفاذه؛ فتكامل السبب والتنفيذ والصفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص288–295.","url":""}]},{"id":"s40-43","number":43,"surah":40,"verses":[23,24],"verseLabel":"غافر: 23–24","question":"ما سر الجمع بين فرعون وهامان وقارون في تلقي رسالة موسى مع اختلاف مواقعهم؟","answer":"فرعون رأس السلطة، وهامان جهازها التنفيذي، وقارون سلطان المال؛ فشملت الرسالة أركان الطغيان السياسي والإداري والاقتصادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص297–303.","url":""}]},{"id":"s40-44","number":44,"surah":40,"verses":[24],"verseLabel":"غافر: 24","question":"ما دلالة وصف موسى عند تكذيبه بأنه ﴿سَاحِرٌ كَذَّابٌ﴾ وتقديم الساحر؟","answer":"قدم السحر لأنه تفسيرهم الظاهري للآيات، ثم الكذب اتهامهم لمصدر الدعوة؛ فطعنوا في الدليل ثم صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص301–303.","url":""}]},{"id":"s40-45","number":45,"surah":40,"verses":[25],"verseLabel":"غافر: 25","question":"ما سر تكرار الأمر بقتل أبناء المؤمنين واستحياء نسائهم بعد نجاة موسى الأولى؟","answer":"الأمر الأول استضعاف لبني إسرائيل، والثاني تجدد لقمع المؤمنين بعد ظهور الحق؛ فالتكرار يكشف ثبات سياسة الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص304–313.","url":""}]},{"id":"s40-46","number":46,"surah":40,"verses":[26],"verseLabel":"غافر: 26","question":"ما سر ادعاء فرعون الخوف على دين قومه وأرضهم وهو المتجبر؟","answer":"لبس مصلحته الخاصة بثوب حماية الدين والوطن، وهي حجة الطاغية الذي يجعل بقاء سلطانه بقاءً للنظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص314–329.","url":""}]},{"id":"s40-47","number":47,"surah":40,"verses":[26],"verseLabel":"غافر: 26","question":"ما دلالة تقديم تبديل الدين على إظهار الفساد في حجة فرعون؟","answer":"تبديل الدين يهدد مرجعيته وسلطانه أولًا، ثم الفساد أثر يدعيه؛ فقدم ما يمس عرشه العقدي والسياسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص321–329.","url":""}]},{"id":"s40-48","number":48,"surah":40,"verses":[27],"verseLabel":"غافر: 27","question":"ما سر إضافة الرب إلى ضمير موسى ثم إلى ضمير قوم فرعون في استعاذته؟","answer":"قال ﴿رَبِّي﴾ إعلانًا لتوكله، ثم ﴿رَبِّكُمْ﴾ تذكيرًا بأن من يحميه هو رب خصومه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص330–339.","url":""}]},{"id":"s40-49","number":49,"surah":40,"verses":[27],"verseLabel":"غافر: 27","question":"ما مناسبة الاستعاذة من كل متكبر لا يؤمن بيوم الحساب؟","answer":"التكبر يورث رفض الحجة، وإنكار الحساب يزيل رادع العدوان؛ فاجتماعهما يصنع خطر الرجم والبطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص333–339.","url":""}]},{"id":"s40-50","number":50,"surah":40,"verses":[28],"verseLabel":"غافر: 28","question":"ما دلالة تنكير ﴿رَجُلٌ مُؤْمِنٌ﴾ وكتمان إيمانه مع نسبته إلى آل فرعون؟","answer":"التنكير يقدمه فردًا مجهول الشأن أمام سلطان كبير، وكتمان الإيمان يفسر قربه من المجلس وقدرته على النصح قبل انكشافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص339–350.","url":""}]},{"id":"s40-51","number":51,"surah":40,"verses":[28],"verseLabel":"غافر: 28","question":"ما سر بناء حجة مؤمن آل فرعون على احتمالين: ﴿وَإِنْ يَكُ كَاذِبًا﴾ و﴿وَإِنْ يَكُ صَادِقًا﴾؟","answer":"حتى على فرض كذبه فعليه كذبه، وعلى فرض صدقه يصبهم بعض الوعيد؛ فالحذر العقلي وحده يمنع قتله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص350–362.","url":""}]},{"id":"s40-52","number":52,"surah":40,"verses":[28],"verseLabel":"غافر: 28","question":"ما سر تقديم احتمال كذب موسى على احتمال صدقه؟","answer":"قدم الاحتمال الذي يوافقهم ليخفض مقاومتهم ويقيم الحجة من أرض مشتركة، ثم نقلهم إلى الخطر الأهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص354–357.","url":""}]},{"id":"s40-53","number":53,"surah":40,"verses":[28],"verseLabel":"غافر: 28","question":"ما مناسبة ختم حجة المؤمن بقوله ﴿إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ﴾؟","answer":"إن كان موسى مسرفًا كذابًا فلن يهديه الله، وإن كان صادقًا فوصفهم يرتد عليهم؛ فترك الخاتمة ميزانًا يكشف الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص360–368.","url":""}]},{"id":"s40-54","number":54,"surah":40,"verses":[29],"verseLabel":"غافر: 29","question":"ما دلالة تكرار النداء ﴿يَا قَوْمِ﴾ في خطاب المؤمن؟","answer":"النداء يكرر رابطة القوم ليوقظ الشفقة والانتماء كلما انتقل إلى حجة جديدة؛ فهو ناصح منهم لا عدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص369–386.","url":""}]},{"id":"s40-55","number":55,"surah":40,"verses":[29],"verseLabel":"غافر: 29","question":"ما دلالة مقابلة قول المؤمن ﴿مَنْ يَنْصُرُنَا مِنْ بَأْسِ اللَّهِ﴾ بدعوى فرعون ﴿وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ﴾؟","answer":"المؤمن يسأل عن ناصر حقيقي أمام بأس الله، وفرعون يزعم أنه مصدر الرشاد؛ فالمقابلة بين تحذير واقعي ودعاية سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص376–386.","url":""}]},{"id":"s40-56","number":56,"surah":40,"verses":[30,31],"verseLabel":"غافر: 30–31","question":"ما سر إجمال يوم الأحزاب أولًا ثم تفصيل قوم نوح وعاد وثمود ومن بعدهم؟","answer":"أجمل الاسم ليثير هول اجتماعهم على التكذيب، ثم فصل أشهر الأمم ليجعل التحذير تاريخًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص387–402.","url":""}]},{"id":"s40-57","number":57,"surah":40,"verses":[31],"verseLabel":"غافر: 31","question":"ما دلالة ذكر الأقوام وترتيبهم دون ذكر أنبيائهم؟","answer":"المقام لعاقبة الأمم وسنة التكذيب، لا لتفصيل سير الرسل؛ وترتيب الأقوام يمد خط التاريخ أمام السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص393–402.","url":""}]},{"id":"s40-58","number":58,"surah":40,"verses":[32,33],"verseLabel":"غافر: 32–33","question":"ما سر تسمية القيامة ﴿يَوْمَ التَّنَادِ﴾ وربطها بتوليهم مدبرين؟","answer":"التناد كثرة نداء الناس بعضهم بعضًا للاستغاثة، ثم يولون هاربين فلا ينفع النداء؛ فجمع الضجيج والفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص403–414.","url":""}]},{"id":"s40-59","number":59,"surah":40,"verses":[33],"verseLabel":"غافر: 33","question":"ما دلالة الجمع بين نفي العاصم من الله ونفي الهادي لمن أضله الله؟","answer":"لا قوة تعصم من حكم الله، ومن يخذله بسبب ضلاله لا يجد من يهديه؛ فانتفى الدفاع الداخلي والدليل الخارجي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص410–420.","url":""}]},{"id":"s40-60","number":60,"surah":40,"verses":[34],"verseLabel":"غافر: 34","question":"ما سر استدعاء قصة يوسف في أثناء خطاب مؤمن آل فرعون؟","answer":"يوسف رسول عرفه أهل مصر، وشكهم فيه ثم ندمهم بعد موته مثال قريب يثبت أن رفض موسى تكرار لمرض قديم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص421–437.","url":""}]},{"id":"s40-61","number":61,"surah":40,"verses":[34],"verseLabel":"غافر: 34","question":"ما سر التعبير بـ﴿حَتَّى إِذَا هَلَكَ﴾ عن وفاة يوسف؟","answer":"الهلاك يلفت إلى انقطاع وجوده بينهم وما أعقب ذلك من حكمهم المتعجل بانتهاء الرسالة؛ فاللفظ يخدم حجة السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص430–434.","url":""}]},{"id":"s40-62","number":62,"surah":40,"verses":[34],"verseLabel":"غافر: 34","question":"ما دلالة وصف المرتاب بأنه ﴿مُسْرِفٌ مُرْتَابٌ﴾؟","answer":"الإسراف تجاوز للحد في العمل، والارتياب اضطراب في الاعتقاد؛ فجمع فساد السلوك وفساد اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص434–437.","url":""}]},{"id":"s40-63","number":63,"surah":40,"verses":[35],"verseLabel":"غافر: 35","question":"ما دلالة وصف المجادلين بغير سلطان بأن جدالهم كبر مقتًا عند الله وعند المؤمنين؟","answer":"مقت الله لأنهم عاندوا حجته، ومقت المؤمنين لأنهم رأوا قبح العدوان على الحق؛ فتوافق الميزان الإلهي والفطرة السليمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص421–446.","url":""}]},{"id":"s40-64","number":64,"surah":40,"verses":[35],"verseLabel":"غافر: 35","question":"ما سر الجمع بين ﴿مُتَكَبِّرٍ﴾ و﴿جَبَّارٍ﴾ في وصف القلب المختوم عليه؟","answer":"المتكبر يرفض الحق في نفسه، والجبار يفرض باطله على غيره؛ فالقلب المختوم يجمع الاستعلاء والبطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص442–446.","url":""}]},{"id":"s40-65","number":65,"surah":40,"verses":[36,37],"verseLabel":"غافر: 36–37","question":"ما دلالة طلب فرعون بناء الصرح لبلوغ الأسباب والاطلاع إلى إله موسى؟","answer":"تظاهر بالبحث الحسي عن إله موسى، وهو طلب مستحيل صيغ للسخرية وتثبيت المادية في قومه لا لتحقيق المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص447–458.","url":""}]},{"id":"s40-66","number":66,"surah":40,"verses":[37],"verseLabel":"غافر: 37","question":"ما سر جمع فرعون بين قوله ﴿لَعَلِّي أَبْلُغُ الْأَسْبَابَ﴾ وقوله المؤكد ﴿وَإِنِّي لَأَظُنُّهُ كَاذِبًا﴾؟","answer":"﴿لَعَلِّي﴾ يوهم انفتاح البحث، والتوكيد بعده يكشف حكمه المسبق؛ فالتناقض يفضح أن الصرح مسرحية دعائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص452–458.","url":""}]},{"id":"s40-67","number":67,"surah":40,"verses":[38],"verseLabel":"غافر: 29؛ غافر: 38","question":"ما دلالة مقابلة دعوى فرعون ﴿أَهْدِيكُمْ سَبِيلَ الرَّشَادِ﴾ بقول المؤمن ﴿اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ﴾؟","answer":"فرعون يطلب اتباعه بلا برهان ويزعم الرشاد، والمؤمن يقول ﴿اتَّبِعُونِ﴾ ثم يقدم حجج الآخرة؛ فاتحد اللفظ واختلف صدق الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص382–386، 464–472.","url":""}]},{"id":"s40-68","number":68,"surah":40,"verses":[39],"verseLabel":"غافر: 39","question":"ما سر مقابلة الحياة الدنيا بوصفها متاعًا والآخرة بوصفها ﴿دَارُ الْقَرَارِ﴾؟","answer":"المتاع منفعة قصيرة تزول، والقرار موطن إقامة ثابت؛ فالمقابلة تصحح ميزان من أغراه ملك مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص464–477.","url":""}]},{"id":"s40-69","number":69,"surah":40,"verses":[40],"verseLabel":"غافر: 40","question":"ما دلالة مقابلة تقييد جزاء السيئة بالمثل بإطلاق رزق المؤمنين بغير حساب؟","answer":"قُيّد جزاء السيئة بالعدل فلا يزاد على مثلها، وأطلق رزق المؤمنين تفضلًا؛ فالمقابلة تجمع تمام العدل وسعة الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص464–485.","url":""}]},{"id":"s40-70","number":70,"surah":40,"verses":[40],"verseLabel":"غافر: 40","question":"ما سر التصريح بشمول الوعد للذكر والأنثى مع قوله ﴿وَهُوَ مُؤْمِنٌ﴾؟","answer":"التصريح يقطع توهم اختصاص الفضل بجنس، ويقرر أن مناط الجزاء هو العمل الصالح والإيمان للذكر والأنثى سواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص479–485.","url":""}]},{"id":"s40-71","number":71,"surah":40,"verses":[41],"verseLabel":"غافر: 41","question":"ما سر مقابلة دعوة المؤمن قومه إلى النجاة بدعوتهم إياه إلى النار؟","answer":"هو يدعوهم إلى سبب النجاة، وهم يدعونه إلى سبب النار؛ فالتقابل يكشف انقلاب الموازين عند قومه وشدة إخلاصه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص486–494.","url":""}]},{"id":"s40-72","number":72,"surah":40,"verses":[42],"verseLabel":"غافر: 42","question":"ما دلالة وصف ما يدعونه إليه بأنه شرك بما ليس له به علم؟","answer":"نفي العلم بالشريك ينفي أي برهان على عبادته؛ فالشرك دعوى لا دليل لها، بخلاف الدعوة إلى الله القائمة على المعرفة والوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص486–502.","url":""}]},{"id":"s40-73","number":73,"surah":40,"verses":[42],"verseLabel":"غافر: 42","question":"ما مناسبة ختم دعوة المؤمن بقوله ﴿وَأَنَا أَدْعُوكُمْ إِلَى الْعَزِيزِ الْغَفَّارِ﴾؟","answer":"العزيز قادر على إنقاذ المؤمن وقهر الطغاة، والغفار يفتح لقومه باب الرجوع؛ فاجتمع الأمان للداعي والرجاء للمدعوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص495–502.","url":""}]},{"id":"s40-74","number":74,"surah":40,"verses":[43],"verseLabel":"غافر: 43","question":"ما الفرق بين تعدية دعوتهم باللام في ﴿تَدْعُونَنِي إِلَيْهِ﴾ ونفي الدعوة بـ﴿لَا جَرَمَ أَنَّمَا تَدْعُونَنِي إِلَيْهِ لَيْسَ لَهُ دَعْوَةٌ﴾؟","answer":"دعوتهم متجهة إلى معبود موهوم، لكنه لا يملك دعوةً مستجابة ولا استحقاقًا لأن يُدعى؛ فانتقل من حكاية الاتجاه إليه إلى نفي حقيقته وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص486–512.","url":""}]},{"id":"s40-75","number":75,"surah":40,"verses":[43],"verseLabel":"غافر: 43","question":"ما سر الجمع بين بطلان دعوة الشركاء وثبوت مرد الجميع إلى الله؟","answer":"إذا بطلت ألوهية الشركاء ولم يثبت لهم تصرف، وثبت أن المرجع كله إلى الله، لزم إفراده بالدعاء والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص501–512.","url":""}]},{"id":"s40-76","number":76,"surah":40,"verses":[44],"verseLabel":"غافر: 44","question":"ما دلالة انتقال المؤمن من المحاجة إلى قوله ﴿فَسَتَذْكُرُونَ مَا أَقُولُ لَكُمْ﴾ ثم تفويض أمره إلى الله؟","answer":"بعد استيفاء الحجة أنذرهم بأن الحق سينكشف لهم، ثم سلّم نفسه لله؛ فجمع بلاغ الناصح وثقة المؤمن حين يهدده السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص513–521.","url":""}]},{"id":"s40-77","number":77,"surah":40,"verses":[44],"verseLabel":"غافر: 44","question":"ما سر اختيار ﴿أُفَوِّضُ أَمْرِي إِلَى اللَّهِ﴾ وختمه بأن الله بصير بالعباد؟","answer":"التفويض ردّ الأمر كله إلى تدبير الله عند انقطاع الأسباب، وختم البصر يطمئن إلى أنه يرى عبده ومكر أعدائه فيحكم بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص517–521.","url":""}]},{"id":"s40-78","number":78,"surah":40,"verses":[45,46],"verseLabel":"غافر: 45–46","question":"ما دلالة مقابلة وقاية الله المؤمن من سيئات مكرهم بحيق سوء العذاب بآل فرعون؟","answer":"وقاه الله آثار مكرهم، بينما أحاط بهم العذاب الذي صنعوه؛ فالمقابلة تظهر انقلاب المكر على أهله وحفظ المتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص522–534.","url":""}]},{"id":"s40-79","number":79,"surah":40,"verses":[46],"verseLabel":"غافر: 46","question":"ما دلالة عرض آل فرعون على النار غدوًا وعشيًا قبل قيام الساعة؟","answer":"العرض غدوًا وعشيًا يدل على عذاب يسبق قيام الساعة، ثم يشتد يومها؛ فجمعت الآية عذاب البرزخ وعذاب المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص530–534.","url":""}]},{"id":"s40-80","number":80,"surah":40,"verses":[47,48],"verseLabel":"غافر: 47–48","question":"ما دلالة محاجة الضعفاء للمستكبرين في النار ثم جواب الجميع ﴿إِنَّا كُلٌّ فِيهَا﴾؟","answer":"طلب الضعفاء نقل نصيب من العذاب إلى قادتهم، فأقر المستكبرون بالعجز العام؛ إذ لا امتياز لزعيم ولا تابع بعد حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص535–549.","url":""}]},{"id":"s40-81","number":81,"surah":40,"verses":[49],"verseLabel":"غافر: 49","question":"ما سر طلب أهل النار من الخزنة أن يدعوا ربهم لتخفيف يوم واحد من العذاب؟","answer":"لما يئسوا من القادة توجهوا إلى الخزنة، وطلبوا يومًا واحدًا فقط؛ فصغر الطلب يكشف شدة العذاب وكمال اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص550–556.","url":""}]},{"id":"s40-82","number":82,"surah":40,"verses":[50],"verseLabel":"غافر: 50","question":"ما دلالة رد الخزنة بتذكيرهم بمجيء الرسل بالبينات قبل قولهم ﴿فَادْعُوا﴾؟","answer":"ذكّروهم بأن باب الدعاء النافع فتحته الرسل في الدنيا فردوه؛ ثم جاء ﴿فَادْعُوا﴾ للتوبيخ والإياس لا للإذن باستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص557–569.","url":""}]},{"id":"s40-83","number":83,"surah":40,"verses":[50],"verseLabel":"غافر: 50","question":"ما سر ختم الحوار بقوله ﴿وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ﴾؟","answer":"دعاؤهم ضائع لأنه جاء في غير زمن العمل ومن قلوب ثبتت على الكفر؛ فختم الحوار بحكم يشمل كل محاولتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص564–569.","url":""}]},{"id":"s40-84","number":84,"surah":40,"verses":[51,52],"verseLabel":"غافر: 51–52","question":"ما دلالة الوعد بنصر الرسل والمؤمنين في الحياة الدنيا ويوم يقوم الأشهاد؟","answer":"النصر في الدنيا بإظهار الحجة وتأييد المؤمنين، ويتم يوم القيامة بقيام الشهود والحكم؛ فلا يضيع حق الرسالة في الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص570–584.","url":""}]},{"id":"s40-85","number":85,"surah":40,"verses":[51],"verseLabel":"غافر: 51","question":"ما سر تسمية القيامة ﴿يَوْمَ يَقُومُ الْأَشْهَادُ﴾؟","answer":"قيام الشهود أبرز ما يكشف الحق يومئذ؛ تشهد الرسل والملائكة والجوارح، فتسقط الأعذار ويظهر تمام العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص574–580.","url":""}]},{"id":"s40-86","number":86,"surah":40,"verses":[52],"verseLabel":"غافر: 52","question":"ما سر التعبير عن النار بـ﴿سُوءُ الدَّارِ﴾ بعد اللعنة؟","answer":"بعد الطرد من الرحمة صوّر مأواهم دارًا سيئة في ذاتها وإقامتها؛ فجمع فقدان الخير وحلول الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص580–584.","url":""}]},{"id":"s40-87","number":87,"surah":40,"verses":[53,54],"verseLabel":"غافر: 53–54","question":"ما دلالة تقديم إيتاء موسى الهدى على توريث بني إسرائيل الكتاب؟","answer":"الهدى ما أوتيه موسى من النبوة والدلالة، ثم صار الكتاب ميراثًا ممتدًا في بني إسرائيل؛ فقدم الأصل الشخصي ثم أثره الجماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص585–594.","url":""}]},{"id":"s40-88","number":88,"surah":40,"verses":[54],"verseLabel":"غافر: 54","question":"ما سر وصف الكتاب بأنه ﴿هُدًى وَذِكْرَى لِأُولِي الْأَلْبَابِ﴾؟","answer":"هو هدى يقود إلى الحق، وذكرى تجدد ما تدركه الفطر والعقول؛ وخص أولو الألباب لأنهم يحسنون الانتفاع بالدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص591–594.","url":""}]},{"id":"s40-89","number":89,"surah":40,"verses":[55],"verseLabel":"غافر: 55","question":"ما دلالة وصل الأمر بالصبر بتأكيد أن وعد الله حق والاستغفار للذنب؟","answer":"حقية الوعد تسند الصبر، والاستغفار يحفظ الداعي من العجب والتقصير؛ فجمع الثبات على الطريق وإصلاح النفس فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص595–606.","url":""}]},{"id":"s40-90","number":90,"surah":40,"verses":[55],"verseLabel":"غافر: 55","question":"ما سر تقديم العشي على الإبكار في التسبيح بحمد الله؟","answer":"المقام بعد أمر الصبر وما يلقاه الداعي آخر النهار، فقدم العشي ثم قرنه بالإبكار لاستيعاب طرفي الزمن وتجدد العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص603–606.","url":""}]},{"id":"s40-91","number":91,"surah":40,"verses":[56],"verseLabel":"غافر: 56","question":"ما دلالة تعليل مجادلة آيات الله بوجود كبر في صدور المجادلين؟","answer":"المجادلة بلا سلطان ليست طلبًا للحق، وإنما يحركها استعلاء باطني يرفض الاتباع؛ لذلك لن يبلغ أصحابها ما يتوهمون من العظمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص607–620.","url":""}]},{"id":"s40-92","number":92,"surah":40,"verses":[56],"verseLabel":"غافر: 56","question":"ما مناسبة الأمر بالاستعاذة وختم الآية باسمي ﴿السَّمِيعُ الْبَصِيرُ﴾؟","answer":"الاستعاذة تحصن من شر كبرهم وجدالهم، والسميع يسمع أقوالهم والبصير يرى تدبيرهم؛ فالله محيط بما يستعاذ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص613–620.","url":""}]},{"id":"s40-93","number":93,"surah":40,"verses":[57],"verseLabel":"غافر: 57","question":"ما دلالة الاحتجاج بأن خلق السماوات والأرض أكبر من خلق الناس؟","answer":"من قدر على خلق الكون الأعظم لا يعجزه إعادة الناس الأصغر؛ فالاحتجاج ينقلهم من المشاهد الأكبر إلى إمكان البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص621–628.","url":""}]},{"id":"s40-94","number":94,"surah":40,"verses":[58],"verseLabel":"غافر: 58","question":"ما سر اختلاف النسق بين ﴿الْأَعْمَى وَالْبَصِيرُ﴾ و﴿الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُسِيءُ﴾؟","answer":"جاء التقابل الأول بين وصفين مفردين متضادين، أما الثاني فقوبل فريق كامل الصفات بمفرد ﴿الْمُسِيءُ﴾؛ لأن الإيمان يتعدد خيره والإساءة يجمعها وصفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص629–639.","url":""}]},{"id":"s40-95","number":95,"surah":40,"verses":[57,58,59],"verseLabel":"غافر: 57–59","question":"ما سر تكرار ﴿أَكْثَرَ النَّاسِ﴾ مع اختلاف نفي العلم في الأولى ونفي الإيمان في الثانية؟","answer":"الأولى تنفي عن أكثر الناس علم نسبة الخلق، والثانية تنفي إيمانهم بالساعة رغم قيام الدليل؛ فجهل القدرة قاد إلى ضعف التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص621–649.","url":""}]},{"id":"s40-96","number":96,"surah":40,"verses":[15],"verseLabel":"غافر: 59؛ طه: 15","question":"ما سر التعبير هنا بـ﴿إِنَّ السَّاعَةَ لَآتِيَةٌ﴾ باللام، وفي خطاب موسى ﴿إِنَّ السَّاعَةَ آتِيَةٌ﴾ دونها؟","answer":"زاد التوكيد باللام في خطاب منكري البعث لتقوية الخبر في مقام الجدال، وخلا منها خطاب موسى لأن أصل وقوع الساعة مقرر عند المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص640–649.","url":""}]},{"id":"s40-97","number":97,"surah":40,"verses":[60],"verseLabel":"غافر: 60","question":"ما دلالة اقتران الأمر بالدعاء بالوعد المباشر ﴿أَسْتَجِبْ لَكُمْ﴾؟","answer":"الوعد جاء بلا واسطة ولا إبطاء لفظي ليبعث على الإقبال؛ فالدعاء عبادة مفتوحة، والاستجابة مضمونة على وفق حكمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص650–657.","url":""}]},{"id":"s40-98","number":98,"surah":40,"verses":[60],"verseLabel":"غافر: 60","question":"ما وجه الاحتباك بين الدعاء والاستجابة والعبادة ودخول جهنم؟","answer":"ذُكر الدعاء ودل عليه جواب الاستجابة، ثم ذُكرت العبادة ودل على تركها الاستكبار؛ فتقابل فعل العبد وجزاء الرب في تركيب موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص650–662.","url":""}]},{"id":"s40-99","number":99,"surah":40,"verses":[60],"verseLabel":"غافر: 60","question":"ما سر اختيار ﴿دَاخِرِينَ﴾ في جزاء المستكبرين عن العبادة؟","answer":"الدخور ذل مع صَغار، وهو الجزاء الموافق للاستكبار؛ فمن استعلى عن العبادة دخل النار مهانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص658–662.","url":""}]},{"id":"s40-100","number":100,"surah":40,"verses":[61],"verseLabel":"غافر: 61","question":"ما سر تقديم الليل على النهار، وذكر علة الليل وحذف علة النهار؟","answer":"قدم الليل لأنه أصل السكون، وصرح بعلة السكون لحاجة النفس إليه، ثم وصف النهار مبصرًا فدل وصفه على غاية الحركة والعمل دون تكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص663–674.","url":""}]},{"id":"s40-101","number":101,"surah":40,"verses":[61],"verseLabel":"غافر: 61","question":"ما دلالة وصف النهار بأنه ﴿مُبْصِرًا﴾؟","answer":"الإبصار في الحقيقة لأهل النهار، وأسند إليه لأنه ظرف ظهور الأشياء؛ فصوّر الضوء كأنه يجعل النهار نفسه مبصرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص671–674.","url":""}]},{"id":"s40-102","number":102,"surah":40,"verses":[61],"verseLabel":"غافر: 61","question":"ما مناسبة الانتقال من فضل الله على الناس إلى ذم أكثرهم بعدم الشكر؟","answer":"فضله ظاهر في انتظام الليل والنهار، لكن أكثر الناس يقابلون النعمة بالغفلة؛ فالانتقال يحول مشاهدة النظام إلى واجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص674–682.","url":""}]},{"id":"s40-103","number":103,"surah":40,"verses":[62,63],"verseLabel":"غافر: 62–63","question":"ما دلالة الانتقال من ﴿فَأَنَّى تُؤْفَكُونَ﴾ إلى ﴿كَذَلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بِآيَاتِ اللَّهِ يَجْحَدُونَ﴾؟","answer":"الاستفهام يعجب من صرفهم عن الخالق مع وضوح صفاته، ثم يبين أن هذا الصرف سنة من يجحد الآيات؛ فانتقل من حالتهم إلى سببها العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص683–695.","url":""}]},{"id":"s40-104","number":104,"surah":40,"verses":[62],"verseLabel":"غافر: 62","question":"ما مناسبة تقرير وحدانية الله بعد وصفه بأنه ربهم وخالق كل شيء؟","answer":"الربوبية والخلق دليلان على استحقاق العبادة، فنفي الإله غيره نتيجة لازمة لهما لا دعوى منفصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص683–690.","url":""}]},{"id":"s40-105","number":105,"surah":40,"verses":[61,64],"verseLabel":"غافر: 61، 64","question":"ما سر تكرار بناء ﴿اللَّهُ الَّذِي جَعَلَ لَكُمْ﴾ عند نعمتي الليل والنهار ثم الأرض والسماء؟","answer":"تكرار البناء يثبت وحدة المنعم في النعم الزمنية والكونية، ويجعل كل مجموعة منها حجة مستقلة على وجوب شكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص663–711.","url":""}]},{"id":"s40-106","number":106,"surah":40,"verses":[64],"verseLabel":"غافر: 64","question":"ما سر مقابلة ﴿الْأَرْضَ قَرَارًا﴾ بـ﴿السَّمَاءَ بِنَاءً﴾؟","answer":"القرار قرار واستقرار تحت الإنسان، والبناء سقف محكم فوقه؛ فالمقابلة ترسم المسكن الكوني من أسفل وأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص696–702.","url":""}]},{"id":"s40-107","number":107,"surah":40,"verses":[64],"verseLabel":"غافر: 64","question":"ما دلالة الجمع بين جعل الأرض والسماء وتصوير الإنسان ورزقه من الطيبات؟","answer":"هيأ العالم مسكنًا، ثم سوّى الإنسان المنتفع به، ثم أمده بالغذاء؛ فتدرج من المحيط إلى الذات ثم أسباب بقائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص701–711.","url":""}]},{"id":"s40-108","number":108,"surah":40,"verses":[65],"verseLabel":"غافر: 65","question":"ما دلالة الانتقال من ﴿هُوَ الْحَيُّ لَا إِلَهَ إِلَّا هُوَ﴾ إلى الأمر بدعائه مخلصين له الدين؟","answer":"حياته التي لا تزول ووحدانيته تبطلان دعاء الفانيات، ومن ثم جاء الأمر بالدعاء الخالص نتيجةً لما تقرر من صفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص712–720.","url":""}]},{"id":"s40-109","number":109,"surah":40,"verses":[66],"verseLabel":"غافر: 66","question":"ما سر مقابلة ﴿نُهِيتُ﴾ بـ﴿أُمِرْتُ﴾ في إعلان البراءة من الشرك والإسلام لله؟","answer":"النهي يقطع صلة الشرك، والأمر ينشئ صلة الإسلام؛ فليس التوحيد مجرد ترك للمعبودات بل خضوع إيجابي لرب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص721–731.","url":""}]},{"id":"s40-110","number":110,"surah":40,"verses":[67],"verseLabel":"غافر: 67","question":"ما دلالة ترتيب أطوار الإنسان من التراب إلى النطفة والعلقة والطفولة والشيخوخة؟","answer":"الترتيب يعرض أصل الخلق ثم أطواره في الرحم فخروجه ونضجه وهرمه؛ ليبرهن بتدبير الحياة المتدرج على القدرة والحكمة والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص732–754.","url":""}]},{"id":"s40-111","number":111,"surah":40,"verses":[67],"verseLabel":"غافر: 67","question":"ما سر إفراد ﴿طِفْلًا﴾ مع جمع المخاطبين؟","answer":"﴿طِفْلًا﴾ اسم جنس يصدق على كل واحد منهم، وفي إفراده استحضار للحالة المشتركة التي يمر بها جميع المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص741–744.","url":""}]},{"id":"s40-112","number":112,"surah":40,"verses":[67],"verseLabel":"غافر: 67","question":"ما دلالة الاعتراض بقوله ﴿وَمِنْكُمْ مَنْ يُتَوَفَّى مِنْ قَبْلُ﴾ وسط أطوار العمر؟","answer":"الاعتراض يبين أن السلسلة ليست لازمة لكل فرد؛ فالموت قد يقطعها في أي طور، وبذلك يظل الأجل لا العمر الطبيعي هو الحاكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص747–752.","url":""}]},{"id":"s40-113","number":113,"surah":40,"verses":[82],"verseLabel":"غافر: 68؛ يس: 82","question":"ما سر التعبير هنا بـ﴿فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾، وفي يس ﴿أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"في غافر جاءت الفاء جوابًا لشرط يشرح طريقة القضاء إذا أراد الله أمرًا، وفي يس جاء المصدر المؤول خبرًا عن شأنه؛ فاختلف الربط لا سرعة النفاذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص755–765.","url":""}]},{"id":"s40-114","number":114,"surah":40,"verses":[68],"verseLabel":"غافر: 68","question":"ما مناسبة الانتقال من أطوار الخلق إلى قوله ﴿هُوَ الَّذِي يُحْيِي وَيُمِيتُ﴾؟","answer":"بعد عرض انتقال الإنسان بين أطوار الحياة والموت عمّم القدرة: هو وحده منشئ الحياة والموت، ومن قدر عليهما قدر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص755–765.","url":""}]},{"id":"s40-115","number":115,"surah":40,"verses":[69,70],"verseLabel":"غافر: 69–70","question":"ما دلالة التعجيب من المجادلين في آيات الله ثم وصفهم بتكذيب الكتاب وما أرسل الله به رسله؟","answer":"التعجيب يواجه غرابة انصرافهم عن الآيات، ثم يكشف أن الجدال ليس عارضًا بل تكذيب بالكتاب وبسلسلة الوحي كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص766–782.","url":""}]},{"id":"s40-116","number":116,"surah":40,"verses":[71,72],"verseLabel":"غافر: 71–72","question":"ما دلالة تدرج عذاب المكذبين من الأغلال والسلاسل إلى السحب في الحميم ثم التسجير في النار؟","answer":"الأغلال تثبتهم، والسلاسل تجرهم، والحميم يحرقهم، ثم النار تسجرهم؛ فتدرج التصوير من القيد إلى السحب ثم الإحراق الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص782–790.","url":""}]},{"id":"s40-117","number":117,"surah":40,"verses":[71],"verseLabel":"غافر: 71","question":"ما سر تخصيص الأعناق بذكر الأغلال؟","answer":"العنق موضع القيد الذي يقاد منه الإنسان قسرًا، وذكره يصور إذلال المتكبرين وانعدام قدرتهم على الانفلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص782–784.","url":""}]},{"id":"s40-118","number":118,"surah":40,"verses":[73,74],"verseLabel":"غافر: 73–74","question":"ما سر تأخير ﴿مِنْ دُونِ اللَّهِ﴾ إلى صدر جوابهم في الآية التالية؟","answer":"أُبهم المسؤول عنه أولًا ليفتح باب الاعتراف، ثم صدر جوابهم بـ﴿مِنْ دُونِ اللَّهِ﴾ لإبراز موضع الجريمة قبل ذكر ضياع المعبودات.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص791–805.","url":""}]},{"id":"s40-119","number":119,"surah":40,"verses":[73,74],"verseLabel":"غافر: 73–74","question":"ما دلالة سؤالهم عن الشركاء ثم اعترافهم بأنهم ضلوا عنهم وأنهم لم يكونوا يدعون شيئًا؟","answer":"السؤال يلزمهم بما عبدوا، وضلال الشركاء يكشف عجزهم، ثم قولهم لم نكن ندعو شيئًا اعتراف بأن عبادتهم تعلقت بما لا حقيقة نافعة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص791–805.","url":""}]},{"id":"s40-120","number":120,"surah":40,"verses":[75],"verseLabel":"غافر: 75","question":"ما الفرق الدلالي بين ﴿تَفْرَحُونَ﴾ و﴿تَمْرَحُونَ﴾ في تعليل العذاب؟","answer":"الفرح هنا بطر بالباطل، والمرح تجاوزه إلى الخيلاء والنشاط المتكبر؛ فجمع فساد الشعور وظهوره في السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص805–812.","url":""}]},{"id":"s40-121","number":121,"surah":40,"verses":[76],"verseLabel":"غافر: 76","question":"ما سر مقابلة تكبرهم في الدنيا بقوله ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾؟","answer":"تكبروا عن الحق في الدنيا، فجاء مثواهم باسم صفتهم نفسها؛ ليظهر أن الجزاء مأوى بناه خُلقهم الذي أصروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص812–819.","url":""}]},{"id":"s40-122","number":122,"surah":40,"verses":[77],"verseLabel":"غافر: 77","question":"ما دلالة الجمع بين الأمر بالصبر وتأكيد أن وعد الله حق؟","answer":"الأمر بالصبر يواجه طول التكذيب، وتأكيد الوعد يثبت أن التأخر لا يعني التخلف؛ فالصبر قائم على يقين لا مجرد احتمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص9–17.","url":""}]},{"id":"s40-123","number":123,"surah":40,"verses":[77],"verseLabel":"غافر: 77","question":"ما دلالة التفصيل بين أن يُرى الرسول ﷺ بعض ما يوعدون أو يُتوفى قبل ذلك ثم يُرجعون إلى الله؟","answer":"سواء شهد الرسول بعض العقوبة أم مات قبلها فمرجعهم إلى الله؛ فالعبرة بتحقق الوعد لا بأن يرى الداعي كل مراحله في حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص17–26.","url":""}]},{"id":"s40-124","number":124,"surah":40,"verses":[78],"verseLabel":"غافر: 78","question":"ما سر تقسيم الرسل إلى من قُصّ على النبي ﷺ ومن لم يُقصص عليه؟","answer":"المقصوص يثبّت الرسول بأمثلة معلومة، وغير المقصوص يوسع أفق الرسالة ويقرر أن تاريخ النبوات أكبر مما ورد تفصيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص27–35.","url":""}]},{"id":"s40-125","number":125,"surah":40,"verses":[78],"verseLabel":"غافر: 78","question":"ما دلالة نفي أن يأتي رسول بآية إلا بإذن الله، ثم مجيء أمر الله والقضاء بالحق؟","answer":"الرسول عبد لا يقترح الخوارق من نفسه، فإذا أذن الله وجاء أمره وقع القضاء العادل وسقط المبطلون؛ فالآية تفصل الرسالة عن التحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص34–45.","url":""}]},{"id":"s40-126","number":126,"surah":40,"verses":[79,80],"verseLabel":"غافر: 79–80","question":"ما سر تقديم الركوب على الأكل في تعداد منافع الأنعام؟","answer":"الركوب منفعة بارزة في الأسفار وحمل الأثقال، ثم الأكل منفعة البقاء؛ وقدم ما يناسب سياق الحمل في البر والبحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص46–52.","url":""}]},{"id":"s40-127","number":127,"surah":40,"verses":[80],"verseLabel":"غافر: 80","question":"ما سر إسناد الحاجة إلى الصدور في ﴿حَاجَةً فِي صُدُورِكُمْ﴾؟","answer":"الصدر موضع الإرادة والهم، فالإسناد يشمل الحاجات الكامنة قبل تعيينها، لا مجرد حمل الأشياء الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص52–57.","url":""}]},{"id":"s40-128","number":128,"surah":40,"verses":[79,80],"verseLabel":"غافر: 79–80","question":"ما دلالة الجمع بين حمل الناس على الأنعام في البر وحملهم على الفلك في البحر؟","answer":"الأنعام سفن البر، والفلك مراكب البحر؛ وجمعهما يري وحدة التسخير التي تصل الإنسان عبر جهتي السفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص48–61.","url":""}]},{"id":"s40-129","number":129,"surah":40,"verses":[81],"verseLabel":"غافر: 81","question":"ما دلالة الانتقال من إراءة آيات الله إلى الاستفهام ﴿فَأَيَّ آيَاتِ اللَّهِ تُنْكِرُونَ﴾؟","answer":"إراءة الآيات تجعلها حاضرة لا غائبة، ثم جاء الاستفهام ليعجز المنكر عن تعيين آية يصح إنكارها بعد هذا البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص61–65.","url":""}]},{"id":"s40-130","number":130,"surah":40,"verses":[82],"verseLabel":"غافر: 82","question":"ما سر الجمع بين كثرة الأمم السابقة وشدة قوتها وآثارها في الأرض ثم نفي إغناء مكاسبها؟","answer":"جمع العدد والقوة والعمران ليبلغ بالمكاسب غايتها، ثم نفى إغناءها عند البأس؛ فلا يبقى موضع للاغترار بالحضارة المادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص66–79.","url":""}]},{"id":"s40-131","number":131,"surah":40,"verses":[83],"verseLabel":"غافر: 83","question":"ما دلالة فرح الأمم بما عندها من العلم عند مجيء الرسل بالبينات؟","answer":"اغتروا بمعارفهم الموروثة والجدلية فاستغنوا بها عن الوحي؛ والفرح يدل على رضا مغلق يمنع صاحبه من مراجعة ما عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص78–87.","url":""}]},{"id":"s40-132","number":132,"surah":40,"verses":[83],"verseLabel":"غافر: 83","question":"ما سر مقابلة فرحهم بعلمهم بحيق ما كانوا به يستهزئون؟","answer":"فرحهم كان ثقةً ساخرة بما عندهم، ثم أحاط بهم عين الجزاء الذي استهزؤوا به؛ فانقلب شعور التفوق إلى إحاطة لا مهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص80–87.","url":""}]},{"id":"s40-133","number":133,"surah":40,"verses":[84,85],"verseLabel":"غافر: 84–85","question":"ما دلالة إعلانهم الإيمان بالله وحده والكفر بالشركاء عند رؤية بأس الله، ثم نفي نفع هذا الإيمان؟","answer":"إيمان المعاينة اعتراف اضطراري بعد ظهور العقوبة، لا اختيارًا في زمن التكليف؛ لذلك جمع صحة الإقرار اللفظي وفوات نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص90–100.","url":""}]},{"id":"s40-134","number":134,"surah":40,"verses":[84],"verseLabel":"غافر: 84","question":"ما سر التصريح بالكفر بما أشركوا به بعد إعلان الإيمان بالله وحده؟","answer":"الإيمان بالله لا يتم مع إبقاء الشركاء، فصرحوا بنقض الشرك لتكتمل كلمة التوحيد؛ لكنه جاء بعد إغلاق باب الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص90–97.","url":""}]},{"id":"s40-135","number":135,"surah":40,"verses":[85],"verseLabel":"غافر: 85","question":"ما دلالة وصف عدم نفع الإيمان عند رؤية البأس بأنه سنة الله التي خلت في عباده؟","answer":"جعل ذلك سنة ثابتة ليبين أن الحكم ليس خاصًا بهذه الأمم: الإيمان عند معاينة البأس لا ينفع من اختار الكفر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص97–106.","url":""}]},{"id":"s40-136","number":136,"surah":40,"verses":[78,85],"verseLabel":"غافر: 78، 85","question":"ما سر تكرار ﴿وَخَسِرَ هُنَالِكَ﴾ ثم ختم السورة بقوله ﴿وَخَسِرَ هُنَالِكَ الْكَافِرُونَ﴾؟","answer":"الأولى تعقب القضاء العام بخسارة المبطلين في ذلك الموقف، والأخيرة تعيد العبارة خاتمةً للمسار كله وتصرح بالكافرين؛ فصار الختام تحقيقًا للإنذار السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص41–45، 103–106.","url":""}]},{"id":"s41-1","number":1,"surah":41,"verses":[1],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«فصلت»، وما صلة الاسم بمحورها؟","answer":"الاسم مأخوذ من وصف القرآن الذي فُصلت آياته بيانًا وتنويعًا للحجج؛ وهو محور السورة في وضوح الوحي مقابل الإعراض عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص108–112.","url":""}]},{"id":"s41-2","number":2,"surah":41,"verses":[1],"verseLabel":"عنوان السورة","question":"ما دلالة تسمية السورة أيضًا بـ«حم السجدة»؟","answer":"تجمع التسمية بين افتتاحها ضمن الحواميم وآية السجدة المميزة فيها، فتعرّفها ببنيتها وعبادتها العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص109–110.","url":""}]},{"id":"s41-3","number":3,"surah":41,"verses":[1],"verseLabel":"بناء السورة","question":"ما دلالة تكرر الحديث عن الإعراض والسآمة في بناء السورة؟","answer":"الإعراض يحجب الانتفاع بالآيات، والسآمة تكشف ضعف تعلق الإنسان بالخير؛ فتكرر المعنيان لرصد مرض التلقي في الكفر والابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص112–114.","url":""}]},{"id":"s41-4","number":4,"surah":41,"verses":[1,2,3],"verseLabel":"فصلت: 1–3","question":"ما سر الانتقال من ﴿حم﴾ إلى الجملة الاسمية ﴿تَنْزِيلٌ مِنَ الرَّحْمَنِ الرَّحِيمِ﴾ ثم إلى ﴿كِتَابٌ فُصِّلَتْ آيَاتُهُ﴾؟","answer":"الحروف توقظ السمع، ثم يثبت المصدر الرحيم للتنزيل، ثم يعرّف أثره كتابًا مفصلًا؛ فتدرج من المبنى إلى المنزّل ثم البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص115–126.","url":""}]},{"id":"s41-5","number":5,"surah":41,"verses":[2],"verseLabel":"فصلت: 2","question":"ما مناسبة اختيار اسمي ﴿الرَّحْمَنِ الرَّحِيمِ﴾ مصدرًا لتنزيل القرآن؟","answer":"التنزيل هداية ورحمة عامة، واختيار الاسمين يفتح باب الرجوع قبل تفصيل الإنذار والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص119–123.","url":""}]},{"id":"s41-6","number":6,"surah":41,"verses":[3],"verseLabel":"فصلت: 3","question":"ما سر اختيار ﴿فُصِّلَتْ آيَاتُهُ﴾ بدل «بُيّنت آياته»؟","answer":"التفصيل أوسع من البيان؛ فهو تمييز للمعاني وتنويع للحجج وترتيب للأحكام بحيث لا تختلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص123–126.","url":""}]},{"id":"s41-7","number":7,"surah":41,"verses":[3],"verseLabel":"فصلت: 3","question":"ما دلالة الجمع بين وصفي القرآن بأنه كتاب وأنه ﴿قُرْآنًا عَرَبِيًّا﴾؟","answer":"الكتاب يلحظ ثبوته وجمعه، والقرآن يلحظ تلاوته العربية؛ فجمع صورتي الحفظ والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص123–128.","url":""}]},{"id":"s41-8","number":8,"surah":41,"verses":[3],"verseLabel":"فصلت: 3","question":"ما سر تخصيص المنتفعين بتفصيل الآيات بأنهم ﴿قَوْمٍ يَعْلَمُونَ﴾؟","answer":"التفصيل ظاهر للجميع، لكن العلم هو الذي يحول الألفاظ إلى فهم وحجة؛ فخُصوا بالانتفاع لا بأصل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص127–129.","url":""}]},{"id":"s41-9","number":9,"surah":41,"verses":[4],"verseLabel":"فصلت: 4","question":"ما سر الجمع بين وصف القرآن بالبشير والنذير وتقديم البشارة؟","answer":"البشارة تفتح باب الرحمة قبل التحذير، والنذارة تمنع الاغترار؛ فجمع الترغيب والترهيب وقدم ما يوافق مصدره الرحيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص129–132.","url":""}]},{"id":"s41-10","number":10,"surah":41,"verses":[4],"verseLabel":"فصلت: 4","question":"ما دلالة قوله ﴿فَأَعْرَضَ أَكْثَرُهُمْ﴾ دون تعميم الإعراض عليهم جميعًا؟","answer":"حفظ الاستثناء الإنصاف وأثبت وجود من استجاب، فالذم للأكثرية الواقعة لا للجنس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص131–134.","url":""}]},{"id":"s41-11","number":11,"surah":41,"verses":[4],"verseLabel":"فصلت: 4","question":"ما المراد بنفي السماع في ﴿فَهُمْ لَا يَسْمَعُونَ﴾ مع سلامة أسماعهم؟","answer":"نفي سماع القبول والانتفاع لا إدراك الصوت؛ لأن الإعراض جعل السماع الحسي كالمعدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص133–137.","url":""}]},{"id":"s41-12","number":12,"surah":41,"verses":[5],"verseLabel":"فصلت: 5","question":"ما سر التدرج في اعتذار المعرضين من أكنة القلوب إلى وقر الآذان ثم الحجاب؟","answer":"جعلوا داخلهم محجوبًا بأكنة، ومدخل الخطاب مسدودًا بالوقر، وبين الطرفين حجابًا؛ فصوروا انسداد الفهم والسماع والتواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص137–149.","url":""}]},{"id":"s41-13","number":13,"surah":41,"verses":[5],"verseLabel":"فصلت: 5","question":"ما دلالة قولهم ﴿فَاعْمَلْ إِنَّنَا عَامِلُونَ﴾ بعد دعوى الحجاب؟","answer":"هو إعلان مفاصلة وتهديد: اعمل على دينك ونحن على ديننا؛ فانتقلوا من وصف الحواجز إلى الإصرار العملي عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص148–151.","url":""}]},{"id":"s41-14","number":14,"surah":41,"verses":[6],"verseLabel":"فصلت: 6","question":"ما سر إثبات بشرية الرسول ﷺ ومماثلته للمخاطبين قبل بيان اختصاصه بالوحي؟","answer":"المماثلة البشرية ترد طلب الملك وتيسر الاقتداء، ثم يثبت الوحي الفرق الوظيفي الذي اصطفاه الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص151–158.","url":""}]},{"id":"s41-15","number":15,"surah":41,"verses":[6],"verseLabel":"فصلت: 6","question":"ما دلالة الانتقال من إثبات بشرية الرسول ﷺ إلى تقرير وحدانية الله والأمر بالاستقامة إليه؟","answer":"إذا كان بشرًا يوحى إليه فلب الرسالة ليس شخصه بل توحيد المرسل؛ ومنه لزم قصد الله وحده والاستقامة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص156–160.","url":""}]},{"id":"s41-16","number":16,"surah":41,"verses":[6],"verseLabel":"فصلت: 6","question":"ما سر عطف الاستغفار على الاستقامة في ﴿فَاسْتَقِيمُوا إِلَيْهِ وَاسْتَغْفِرُوهُ﴾؟","answer":"الاستقامة لا تخلو من تقصير، فجاء الاستغفار لجبر الزلل؛ فجمع دوام الاتجاه وتصحيح الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص158–160.","url":""}]},{"id":"s41-17","number":17,"surah":41,"verses":[7],"verseLabel":"فصلت: 7","question":"ما سر وصف المشركين بأنهم لا يؤتون الزكاة ثم تقرير كفرهم بالآخرة؟","answer":"قيل الزكاة حق المال أو تطهير النفس بالتوحيد؛ وقرنها بالكفر بالآخرة لأن منع الحق ثمرة إنكار الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص160–165.","url":""}]},{"id":"s41-18","number":18,"surah":41,"verses":[7],"verseLabel":"فصلت: 7","question":"ما دلالة تكرار الضمير في ﴿وَهُمْ بِالْآخِرَةِ هُمْ كَافِرُونَ﴾؟","answer":"أعيد ﴿هُمْ﴾ لتقوية الحصر والتوكيد: كفرهم بالآخرة ثابت مخصوص بهم مع اجتماع دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص163–165.","url":""}]},{"id":"s41-19","number":19,"surah":41,"verses":[8],"verseLabel":"فصلت: 8","question":"ما سر وصف أجر المؤمنين بأنه ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"أي غير مقطوع ولا منقوص، أو غير محسوب عليهم بمنة؛ فدوامه يقابل انقطاع متاع الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص166–173.","url":""}]},{"id":"s41-20","number":20,"surah":41,"verses":[9],"verseLabel":"فصلت: 9","question":"ما دلالة اجتماع الاستفهام والتوكيد في ﴿أَئِنَّكُمْ لَتَكْفُرُونَ﴾؟","answer":"الاستفهام ينكر الفعل ويعجب منه، واللام تؤكد وقوع الكفر؛ فاشتد التوبيخ أمام عظمة المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص173–177.","url":""}]},{"id":"s41-21","number":21,"surah":41,"verses":[9],"verseLabel":"فصلت: 9","question":"ما سر تخصيص خلق الأرض في يومين بالذكر عند إنكار الكفر واتخاذ الأنداد؟","answer":"بدأ بالأرض الأقرب إلى إدراكهم وأصل معيشتهم؛ فمن خلقها في يومين لا تجوز مساواة الأنداد به.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص176–182.","url":""}]},{"id":"s41-22","number":22,"surah":41,"verses":[10],"verseLabel":"فصلت: 10","question":"ما سر التعبير بالجعل مع الرواسي وبالخلق مع الأرض؟","answer":"الخلق إنشاء أصل الأرض، والجعل ترتيب صفة عليها بعد وجودها؛ فناسب كل فعل مرحلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص182–187.","url":""}]},{"id":"s41-23","number":23,"surah":41,"verses":[10],"verseLabel":"فصلت: 10","question":"ما دلالة التصريح بأن الرواسي جُعلت ﴿مِنْ فَوْقِهَا﴾ مع أن ذلك مشاهد؟","answer":"يبرز إحكام تثبيتها وهي فوق سطحها، ويوقظ النظر إلى هيئة مألوفة غفلوا عن دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص185–187.","url":""}]},{"id":"s41-24","number":24,"surah":41,"verses":[10],"verseLabel":"فصلت: 10","question":"ما دلالة الجمع بين البركة وتقدير الأقوات في الأرض؟","answer":"البركة تجعل الأرض نامية الخيرات، وتقدير الأقوات يوزع أسباب الانتفاع؛ فجمع أصل الخير وتنظيم وصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص186–190.","url":""}]},{"id":"s41-25","number":25,"surah":41,"verses":[9,10],"verseLabel":"فصلت: 9–10","question":"ما سر التعبير بأربعة أيام في تقدير الأقوات مع سبق ذكر خلق الأرض في يومين؟","answer":"الأربعة تشمل يومي خلق الأرض واليومين اللذين تم فيهما جعل الرواسي والأقوات، لا أربعة مضافة إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص177–193.","url":""}]},{"id":"s41-26","number":26,"surah":41,"verses":[10],"verseLabel":"فصلت: 10","question":"ما دلالة ختم تفصيل خلق الأرض بقوله ﴿سَوَاءً لِلسَّائِلِينَ﴾؟","answer":"أي تمت الأيام الأربعة متساوية معلومة لمن يسأل، أو قدرت الأقوات على قدر حاجات الطالبين بلا خلل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص190–193.","url":""}]},{"id":"s41-27","number":27,"surah":41,"verses":[11],"verseLabel":"فصلت: 11","question":"ما سر التعبير عن السماء بأنها كانت ﴿دُخَانٌ﴾؟","answer":"الدخان يصور مادة أولية لطيفة غير متماسكة قبل تسويتها، ويظهر انتقال الخلق من حال إلى نظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص193–196.","url":""}]},{"id":"s41-28","number":28,"surah":41,"verses":[11],"verseLabel":"فصلت: 11","question":"ما دلالة تمثيل السماء والأرض بمخاطبَين قيل لهما ﴿ائْتِيَا طَوْعًا أَوْ كَرْهًا﴾؟","answer":"شُخصتا لإظهار نفاذ الأمر وسرعة الانقياد؛ فالكون كله يستجيب لخالقه طوعًا أو قهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص195–199.","url":""}]},{"id":"s41-29","number":29,"surah":41,"verses":[11],"verseLabel":"فصلت: 11","question":"ما سر جوابهما بصيغة جمع العقلاء ﴿أَتَيْنَا طَائِعِينَ﴾ بدل «طائعتين»؟","answer":"لما خوطبتا خطاب العقلاء وأظهرتا الطاعة أجري جوابهما على جمع العقلاء تعظيمًا لانقيادهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص197–200.","url":""}]},{"id":"s41-30","number":30,"surah":41,"verses":[11,12],"verseLabel":"فصلت: 11–12","question":"ما سر الانتقال من إفراد السماء وهي دخان إلى جمعها سبع سماوات؟","answer":"ذكرت مادتها الأولى مفردة، ثم بعد التسوية ظهرت طبقاتها السبع؛ فانتقل من الأصل إلى البنية المكتملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص193–204.","url":""}]},{"id":"s41-31","number":31,"surah":41,"verses":[12],"verseLabel":"فصلت: 12","question":"ما دلالة قوله ﴿وَأَوْحَى فِي كُلِّ سَمَاءٍ أَمْرَهَا﴾؟","answer":"أودع في كل سماء نظامها ووظيفتها وما تقوم به ملائكتها؛ فلكل طبقة أمر مقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص201–206.","url":""}]},{"id":"s41-32","number":32,"surah":41,"verses":[12],"verseLabel":"فصلت: 12","question":"ما سر الجمع بين تزيين السماء الدنيا بالمصابيح وحفظها؟","answer":"المصابيح زينة للناظرين ورجوم تحفظ من استراق السمع؛ فجمع الجمال والوظيفة الحارسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص206–211.","url":""}]},{"id":"s41-33","number":33,"surah":41,"verses":[12],"verseLabel":"فصلت: 12","question":"ما مناسبة ختم خلق السماوات والأرض بقوله ﴿ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴾؟","answer":"العزيز يقدر على هذا البناء، والعليم يقدره بلا خلل؛ فختم القدرة الكونية بالقوة والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص210–213.","url":""}]},{"id":"s41-34","number":34,"surah":41,"verses":[13],"verseLabel":"فصلت: 13","question":"ما سر وصف عذاب عاد بالصاعقة مع أن أداة إهلاكهم كانت الريح؟","answer":"الصاعقة اسم للهلاك الشديد المفاجئ، والريح أداته؛ فسمى العذاب بأثره الجامع لا بوسيلته فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص213–220.","url":""}]},{"id":"s41-35","number":35,"surah":41,"verses":[13],"verseLabel":"فصلت: 13","question":"ما دلالة الجمع بين عاد وثمود في إنذار واحد بقوله ﴿صَاعِقَةً مِثْلَ صَاعِقَةِ عَادٍ وَثَمُودَ﴾؟","answer":"جمعهما لتشابه التكذيب وحسم العاقبة مع اختلاف أداة الهلاك؛ فصار الماضي إنذارًا واحدًا للحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص217–220.","url":""}]},{"id":"s41-36","number":36,"surah":41,"verses":[14],"verseLabel":"فصلت: 14","question":"ما دلالة مجيء الرسل لعاد وثمود ﴿مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ﴾؟","answer":"أي توالت الرسل من كل جهة وزمان في إقامة الحجة، أو خاطبوهم بما أمامهم وخلفهم من دلائل؛ فالإحاطة تنفي العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص221–228.","url":""}]},{"id":"s41-37","number":37,"surah":41,"verses":[24],"verseLabel":"فصلت: 14؛ المؤمنون: 24","question":"ما سر التعبير هنا بقولهم ﴿لَوْ شَاءَ رَبُّنَا لَأَنْزَلَ مَلَائِكَةً﴾، وفي المؤمنون ﴿وَلَوْ شَاءَ اللَّهُ لَأَنْزَلَ مَلَائِكَةً﴾؟","answer":"﴿رَبُّنَا﴾ تحكي اعترافهم بالرب مع اعتراضهم على رسله، واسم الجلالة في المؤمنون يقرر أصل دعواهم؛ والسياق يختار زاوية الحكاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص229–234.","url":""}]},{"id":"s41-38","number":38,"surah":41,"verses":[15],"verseLabel":"فصلت: 15","question":"ما دلالة المشاكلة بين قول عاد ﴿مَنْ أَشَدُّ مِنَّا قُوَّةً﴾ والرد ﴿هُوَ أَشَدُّ مِنْهُمْ قُوَّةً﴾؟","answer":"كرر وصف القوة ليجعل الرد من لفظ غرورهم: خالقهم أشد منهم، فالصفة التي افتخروا بها حجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص234–244.","url":""}]},{"id":"s41-39","number":39,"surah":41,"verses":[16],"verseLabel":"فصلت: 16","question":"ما سر اختيار الريح الصرصر عقوبة لقوم اغتروا بقوتهم؟","answer":"الصرصر شديدة البرد أو الصوت، فقابلت قسوة قوتهم بعنصر لا يستطيعون دفعه، وأذلت الأجساد التي اغتروا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص251–256.","url":""}]},{"id":"s41-40","number":40,"surah":41,"verses":[19],"verseLabel":"فصلت: 16؛ القمر: 19","question":"ما سر وصف ريح عاد هنا بأنها ﴿فِي أَيَّامٍ نَحِسَاتٍ﴾، وفي القمر ﴿فِي يَوْمِ نَحْسٍ مُسْتَمِرٍّ﴾؟","answer":"فصلت تنظر إلى أيام العذاب المتعددة كلها فنعتها بالنحس، والقمر يركز على يوم ابتدائه الممتد الأثر؛ فتعدد المنظور.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص251–262.","url":""}]},{"id":"s41-41","number":41,"surah":41,"verses":[16],"verseLabel":"فصلت: 16","question":"ما دلالة مقابلة عذاب الخزي في الدنيا بكون عذاب الآخرة ﴿أَخْزَى﴾؟","answer":"الخزي الدنيوي مؤقت ومحدود، أما عذاب الآخرة فأشد إذلالًا وأدوم، ولا يجدون ناصرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص257–263.","url":""}]},{"id":"s41-42","number":42,"surah":41,"verses":[17],"verseLabel":"فصلت: 17","question":"ما سر تصوير اختيار ثمود للضلال بقوله ﴿فَاسْتَحَبُّوا الْعَمَى عَلَى الْهُدَى﴾؟","answer":"صور الهدى والعمى خيارين معروضين فآثروا العمى محبةً؛ فالضلال قرار لا غياب قسري للدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص264–269.","url":""}]},{"id":"s41-43","number":43,"surah":41,"verses":[17],"verseLabel":"فصلت: 17","question":"ما دلالة مقابلة استحباب العمى بعذاب الهون؟","answer":"اختاروا عمى يهين العقل، فجاءهم عذاب الهون؛ فالجزاء من جنس استحبابهم لما يحط قدرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص268–274.","url":""}]},{"id":"s41-44","number":44,"surah":41,"verses":[16,17,18],"verseLabel":"فصلت: 16–18","question":"ما دلالة مقابلة عذاب عاد وثمود بنجاة الذين آمنوا وكانوا يتقون؟","answer":"العذاب نتيجة الكفر والاستكبار، والنجاة نتيجة الإيمان والتقوى؛ فالمقابلة تبين عدل اختلاف المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص251–279.","url":""}]},{"id":"s41-45","number":45,"surah":41,"verses":[19],"verseLabel":"فصلت: 19","question":"ما سر تسمية المحشورين إلى النار ﴿أَعْدَاءَ اللَّهِ﴾ والتعبير عن ضبط أفواجهم بـ﴿يُوزَعُونَ﴾؟","answer":"العداوة تصف موقفهم المستمر من أمر الله، و﴿يُوزَعُونَ﴾ أي يحبس أولهم على آخرهم حتى تنتظم أفواجهم للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص279–287.","url":""}]},{"id":"s41-46","number":46,"surah":41,"verses":[20],"verseLabel":"فصلت: 20","question":"ما سر إفراد ﴿سَمْعُهُمْ﴾ وجمع ﴿أَبْصَارُهُمْ﴾ و﴿جُلُودُهُمْ﴾؟","answer":"السمع مصدر مفرد أو آلة تتلقى جهة واحدة، والأبصار والجلود متعددة بتعدد الأشخاص والأعضاء؛ فناسب الجمع المشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص287–300.","url":""}]},{"id":"s41-47","number":47,"surah":41,"verses":[20],"verseLabel":"فصلت: 20","question":"ما سر تخصيص الجلود بالشهادة مع أن السمع والأبصار تشهد أيضًا؟","answer":"الجلد محيط بالجسد وباشر طائفة واسعة من الأعمال، وشهادته أعجب لأنها من ظاهر الإنسان الذي ظنه ساترًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص291–300.","url":""}]},{"id":"s41-48","number":48,"surah":41,"verses":[20,21],"verseLabel":"فصلت: 20–21","question":"ما سر تخصيصهم الجلود بالسؤال ﴿لِمَ شَهِدْتُمْ عَلَيْنَا﴾ دون السمع والأبصار؟","answer":"لأن شهادة الجلد أشد مفاجأة وأوسع اتصالًا بأجسادهم، أما السمع والبصر فهما آلتا إدراك يتوقع ارتباطهما بالأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص287–308.","url":""}]},{"id":"s41-49","number":49,"surah":41,"verses":[21],"verseLabel":"فصلت: 21","question":"ما دلالة جواب الجلود ﴿أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ﴾؟","answer":"الله قادر أن يخلق النطق في كل موجود، فلا غرابة في كلام الجلد؛ والجواب يرد القدرة إلى مصدرها العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص295–304.","url":""}]},{"id":"s41-50","number":50,"surah":41,"verses":[21],"verseLabel":"فصلت: 21","question":"ما مناسبة الانتقال من إنطاق الجلود إلى التذكير بأن الله خلقهم أول مرة وإليه يرجعون؟","answer":"من أنشأهم أول مرة أنشأ جوارحهم وقادر على إنطاقها وإعادتهم؛ فجمع الخلق والشهادة والرجوع في دليل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص299–305.","url":""}]},{"id":"s41-51","number":51,"surah":41,"verses":[22],"verseLabel":"فصلت: 22","question":"ما دلالة إعادة ترتيب الجوارح: السمع ثم الأبصار ثم الجلود؟","answer":"ثبت الترتيب نفسه لأنه ينتقل من باب تلقي المسموع إلى رؤية المشاهد ثم العضو المحيط المباشر؛ فتوكد تطابق الشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص305–310.","url":""}]},{"id":"s41-52","number":52,"surah":41,"verses":[22],"verseLabel":"فصلت: 22","question":"ما سر التعبير بـ﴿وَمَا كُنْتُمْ تَسْتَتِرُونَ﴾ عن ظنهم أن جوارحهم لا تشهد؟","answer":"لم يكونوا يستطيعون الاختفاء عن جوارحهم، لكنهم لم يتحرزوا من المعصية لأنهم ظنوا أنها لا تشهد وأن الله لا يعلم كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص305–314.","url":""}]},{"id":"s41-53","number":53,"surah":41,"verses":[23],"verseLabel":"فصلت: 23","question":"ما سر تكرار مادة الظن في ﴿وَذَلِكُمْ ظَنُّكُمُ الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ﴾؟","answer":"التكرار يثبت أن هذا الظن صار عقيدة مصاحبة لهم، ويشهر نسبته إليهم قبل بيان أثره المهلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص318–324.","url":""}]},{"id":"s41-54","number":54,"surah":41,"verses":[23],"verseLabel":"فصلت: 23","question":"ما دلالة ترتيب سوء الظن بالله ثم الإرداء ثم الخسران؟","answer":"سوء تصور علم الله جرأهم على المعصية، فأهلكهم، وانتهى بهم إلى الخسارة؛ ففساد الاعتقاد أنشأ السلوك والمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص320–328.","url":""}]},{"id":"s41-55","number":55,"surah":41,"verses":[24],"verseLabel":"فصلت: 24","question":"ما سر التسوية بين صبر أهل النار وطلبهم العتبى في انقطاع النجاة؟","answer":"إن صبروا فالنار مقامهم، وإن طلبوا الرضا والرجوع فلن يقبل؛ فقد انتهى زمن العمل، فلا احتمال يفتح نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص328–337.","url":""}]},{"id":"s41-56","number":56,"surah":41,"verses":[25],"verseLabel":"فصلت: 25","question":"ما دلالة اختيار ﴿قَيَّضْنَا لَهُمْ قُرَنَاءَ﴾ في تصوير تسليط قرناء السوء؟","answer":"التقييض تهيئة الشيء وإلصاقه، فصور قرناء السوء مسلطين ملازمين لهم جزاء قبولهم طريق الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص337–343.","url":""}]},{"id":"s41-57","number":57,"surah":41,"verses":[25],"verseLabel":"فصلت: 25","question":"ما دلالة قوله ﴿فَزَيَّنُوا لَهُمْ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"زينوا حاضرهم من الشهوات ومستقبلهم من إنكار الجزاء، أو الدنيا والآخرة؛ فأحاط التزيين بالزمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص341–345.","url":""}]},{"id":"s41-58","number":58,"surah":41,"verses":[25],"verseLabel":"فصلت: 25","question":"ما سر تقديم الجن على الإنس في الأمم التي حقت عليها كلمة العذاب؟","answer":"الجن أقدم خلقًا وأشد خفاءً في الإغواء، فقدموا في سلسلة الأمم والقرناء، ثم أتبعوا بالإنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص343–352.","url":""}]},{"id":"s41-59","number":59,"surah":41,"verses":[26],"verseLabel":"فصلت: 26","question":"ما دلالة قول الكافرين ﴿لَا تَسْمَعُوا لِهَذَا الْقُرْآنِ وَالْغَوْا فِيهِ﴾؟","answer":"اعتراف ضمني بقوة القرآن: لم يملكوا حجته فطلبوا تعطيل السماع وإحداث الضوضاء ليمنعوا أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص352–357.","url":""}]},{"id":"s41-60","number":60,"surah":41,"verses":[26],"verseLabel":"فصلت: 26","question":"ما دلالة تعليل اللغو في القرآن بقولهم ﴿لَعَلَّكُمْ تَغْلِبُونَ﴾؟","answer":"جعلوا الغلبة في إسكات الصوت لا في إقامة البرهان؛ فـ﴿لَعَلَّكُمْ﴾ تكشف خوفهم من وصول القرآن إلى القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص354–359.","url":""}]},{"id":"s41-61","number":61,"surah":41,"verses":[27],"verseLabel":"فصلت: 27","question":"ما سر الجمع بين إذاقة الكافرين العذاب الشديد وجزائهم بأسوأ الذي كانوا يعملون؟","answer":"الإذاقة تشعر بمباشرة الألم، والجزاء بأسوأ أعمالهم يبرز تغليظ العقوبة على أصول الكفر والصد لا على مجرد هفوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص360–368.","url":""}]},{"id":"s41-62","number":62,"surah":41,"verses":[28],"verseLabel":"فصلت: 28","question":"ما سر الانتقال من ﴿جَزَاءَ أَعْدَاءِ اللَّهِ﴾ إلى تفسيره بقوله ﴿النَّارُ لَهُمْ فِيهَا دَارُ الْخُلْدِ﴾؟","answer":"أجمل الجزاء أولًا تعظيمًا ثم فسره بالنار، وزاد أنها دار الخلد؛ فانتقل من الحكم إلى ماهيته ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص368–374.","url":""}]},{"id":"s41-63","number":63,"surah":41,"verses":[28],"verseLabel":"فصلت: 28","question":"ما سر التعبير بـ﴿دَارُ الْخُلْدِ﴾ بدل التصريح بأنهم خالدون؟","answer":"جعل النار نفسها دار إقامة ملازمة لهم، وهو أبلغ من خبر عن طول المكث؛ فالمكان كله معرف بالخلود.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص369–372.","url":""}]},{"id":"s41-64","number":64,"surah":41,"verses":[29],"verseLabel":"فصلت: 29","question":"ما دلالة طلب الكافرين أن يروا اللذين أضلاهم من الجن والإنس ليجعلوهما تحت أقدامهم؟","answer":"انقلب الولاء إلى انتقام؛ يريدون إذلال مضليهم تحت أقدامهم ليكونوا أسفل منهم، لكن الجميع شركاء في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص374–384.","url":""}]},{"id":"s41-65","number":65,"surah":41,"verses":[29],"verseLabel":"فصلت: 29","question":"ما سر تقديم الجن على الإنس عند تحديد المضلين؟","answer":"الجن أسبق في الإغواء وأخفى طريقًا، فقدموا، ثم ذكر المضلين من البشر الذين باشروا دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص376–379.","url":""}]},{"id":"s41-66","number":66,"surah":41,"verses":[30],"verseLabel":"فصلت: 30","question":"ما سر الجمع بين قول ﴿رَبُّنَا اللَّهُ﴾ والاستقامة؟","answer":"القول يقرر أصل التوحيد، والاستقامة دوام مقتضاه في الاعتقاد والعمل؛ فلا يكفي الإعلان دون الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص384–389.","url":""}]},{"id":"s41-67","number":67,"surah":41,"verses":[30],"verseLabel":"فصلت: 30","question":"ما دلالة التعبير بتنزل الملائكة على المستقيمين؟","answer":"التنزل يفيد تتابع حضور الملائكة بالبشرى عند مواطن الخوف، ولا سيما الموت والبعث، تكريمًا للثابتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص387–391.","url":""}]},{"id":"s41-68","number":68,"surah":41,"verses":[30],"verseLabel":"فصلت: 30","question":"ما سر تقديم نفي الخوف على نفي الحزن في بشارة الملائكة؟","answer":"الخوف يتعلق بالمستقبل فناسب اللحظة المقبلة عليهم، والحزن بالماضي؛ فبدأ بما يواجههم ثم نفى ألم ما خلّفوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص390–393.","url":""}]},{"id":"s41-69","number":69,"surah":41,"verses":[30],"verseLabel":"فصلت: 30","question":"ما دلالة الجمع بين نفي الخوف والحزن والبشارة بالجنة؟","answer":"نفي الخوف والحزن يزيل المكروه من جهتي الزمن، والبشارة بالجنة تثبت الخير الباقي؛ فجمع الأمن والنعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص390–400.","url":""}]},{"id":"s41-70","number":70,"surah":41,"verses":[31],"verseLabel":"فصلت: 31","question":"ما سر قول الملائكة ﴿نَحْنُ أَوْلِيَاؤُكُمْ﴾ وتقديم الحياة الدنيا على الآخرة؟","answer":"ولايتهم بدأت بالحفظ والتأييد في الدنيا وتستمر بالبشرى والخدمة في الآخرة؛ فقدم محل الصحبة الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص400–404.","url":""}]},{"id":"s41-71","number":71,"surah":41,"verses":[31],"verseLabel":"فصلت: 31","question":"ما الفرق بين ﴿مَا تَشْتَهِي أَنْفُسُكُمْ﴾ و﴿مَا تَدَّعُونَ﴾ في نعيم الجنة؟","answer":"الشهوة رغبة النفس الباطنة، والادعاء ما يطلبونه ويستدعونه بالفعل؛ فلهم كل مرغوب حاضر وكل مطلوب مجاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص403–412.","url":""}]},{"id":"s41-72","number":72,"surah":41,"verses":[32],"verseLabel":"فصلت: 32","question":"ما سر وصف نعيم الجنة بأنه ﴿نُزُلًا مِنْ غَفُورٍ رَحِيمٍ﴾؟","answer":"النزل ما يعد للضيف عند قدومه، فإذا كان هذا النعيم ضيافة فما بعده أعظم؛ ونسب إلى مغفرة سبقت ورحمة أحاطت.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص412–420.","url":""}]},{"id":"s41-73","number":73,"surah":41,"verses":[33],"verseLabel":"فصلت: 33","question":"ما دلالة الاستفهام في ﴿وَمَنْ أَحْسَنُ قَوْلًا﴾، وما سر الجمع بين الدعوة والعمل الصالح؟","answer":"الاستفهام ينفي وجود قول أحسن، والدعوة تُصلح غيره والعمل يصدق دعواه؛ فجمع البلاغ والقدوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص420–426.","url":""}]},{"id":"s41-74","number":74,"surah":41,"verses":[33],"verseLabel":"فصلت: 33","question":"ما سر إعلان ﴿إِنَّنِي مِنَ الْمُسْلِمِينَ﴾ بعد الدعوة والعمل الصالح؟","answer":"أعلن انتماءه للمسلمين تواضعًا واتساقًا مع الدعوة، لا طلبًا لتميز شخصي؛ فهو واحد ممن خضعوا لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص425–430.","url":""}]},{"id":"s41-75","number":75,"surah":41,"verses":[34],"verseLabel":"فصلت: 34","question":"ما دلالة نفي استواء الحسنة والسيئة مع وضوح تفاوتهما؟","answer":"النفي يوقظ الحس الأخلاقي ويمنع مساواة الرد السيئ بالحسن؛ تمهيدًا لاختيار الوسيلة الأرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص430–440.","url":""}]},{"id":"s41-76","number":76,"surah":41,"verses":[34],"verseLabel":"فصلت: 34","question":"ما سر التعبير بـ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ﴾ بدل «ادفع بالحسنة»؟","answer":"اسم الموصول يطلب أرفع خصلة تناسب الموقف، فقد تكون الحسنة درجات؛ والمطلوب أحسنها لا مجرد رد غير سيئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص438–445.","url":""}]},{"id":"s41-77","number":77,"surah":41,"verses":[34],"verseLabel":"فصلت: 34","question":"ما دلالة انقلاب العدو بعد الدفع بالتي هي أحسن إلى ﴿وَلِيٌّ حَمِيمٌ﴾؟","answer":"الإحسان يقطع دورة العداوة ويوقظ ما في الخصم من قابلية للمودة، حتى يبدو القريب الحار في النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص443–449.","url":""}]},{"id":"s41-78","number":78,"surah":41,"verses":[35],"verseLabel":"فصلت: 35","question":"ما سر قصر نيل خصلة الدفع بالتي هي أحسن على الصابرين وذي الحظ العظيم؟","answer":"تحتاج إلى حبس الغضب واحتمال الأذى، فهي لا تُمنح إلا لصابر، وهي نصيب عظيم من الخلق والتوفيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص449–464.","url":""}]},{"id":"s41-79","number":79,"surah":41,"verses":[35],"verseLabel":"فصلت: 35","question":"ما سر الانتقال من جمع الصابرين إلى إفراد ﴿ذُو حَظٍّ عَظِيمٍ﴾؟","answer":"جمع الصابرين بوصف الطريق المتاح لجماعة، ثم أفرد صاحب الحظ لأن كل إنسان ينال نصيبه منه بقدر مجاهدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص458–462.","url":""}]},{"id":"s41-80","number":80,"surah":41,"verses":[36],"verseLabel":"فصلت: 36","question":"ما مناسبة الأمر بالاستعاذة بالله بعد الأمر بدفع السيئة بالتي هي أحسن؟","answer":"الإحسان يحتاج حماية من نزغ يدفع إلى الغضب أو الرياء؛ فما يعالج البشر بالخلق يعالج الشيطان بالاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص464–473.","url":""}]},{"id":"s41-81","number":81,"surah":41,"verses":[200],"verseLabel":"فصلت: 36؛ الأعراف: 200","question":"ما سر التعبير هنا بـ﴿إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ﴾، وفي الأعراف ﴿إِنَّهُ سَمِيعٌ عَلِيمٌ﴾؟","answer":"زاد ضمير الفصل والتعريف هنا لأن السياق مقاومة نزغ مخصوص يحتاج قصر السمع والعلم عليه، وفي الأعراف جاء الخبر مطلقًا مناسبًا للإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص467–482.","url":""}]},{"id":"s41-82","number":82,"surah":41,"verses":[37],"verseLabel":"فصلت: 37","question":"ما سر ترتيب الليل والنهار والشمس والقمر في عداد آيات الله؟","answer":"بدأ بالليل والنهار إطار الزمن، ثم بالشمس والقمر علامتيهما البارزتين؛ فانتقل من النظام إلى أشهر أجرامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص483–488.","url":""}]},{"id":"s41-83","number":83,"surah":41,"verses":[37],"verseLabel":"فصلت: 37","question":"ما سر تخصيص الشمس والقمر بالنهي عن السجود مع ذكر الليل والنهار؟","answer":"لأنهما كانا موضع عبادة فعلية وأشد إغراءً بالعظمة، فوجه النهي إليهما مع أن الجميع آيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص488–491.","url":""}]},{"id":"s41-84","number":84,"surah":41,"verses":[37],"verseLabel":"فصلت: 37","question":"ما دلالة مقابلة النهي عن السجود للشمس والقمر بالأمر بالسجود لله الذي خلقهن؟","answer":"نقل السجود من الآية المخلوقة إلى خالقها؛ فمن أعجبته الشمس والقمر فالأولى أن يعبد من أنشأهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص488–497.","url":""}]},{"id":"s41-85","number":85,"surah":41,"verses":[38],"verseLabel":"فصلت: 38","question":"ما سر مقابلة استكبار البشر بتسبيح الملائكة ليلًا ونهارًا دون سآمة؟","answer":"إن استكبر الناس فالملائكة الأقرب إلى الله يسبحون بلا انقطاع ولا ملل؛ فاستكبارهم لا ينقص عبادته بل يفضحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص497–508.","url":""}]},{"id":"s41-86","number":86,"surah":41,"verses":[39],"verseLabel":"فصلت: 39","question":"ما دلالة تصوير الأرض قبل المطر بأنها ﴿خَاشِعَةً﴾؟","answer":"الخشوع سكون وتطامن، فصورت الأرض اليابسة منخفضة هامدة تنتظر الماء، تمهيدًا لحركتها بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص508–515.","url":""}]},{"id":"s41-87","number":87,"surah":41,"verses":[39],"verseLabel":"فصلت: 39","question":"ما دلالة ترتيب قوله ﴿اهْتَزَّتْ وَرَبَتْ﴾ بعد نزول الماء؟","answer":"الاهتزاز حركة النبات عند الخروج، والربو نموه وارتفاعه؛ فقدم بدء الحركة ثم زيادة الحجم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص509–514.","url":""}]},{"id":"s41-88","number":88,"surah":41,"verses":[39],"verseLabel":"فصلت: 39","question":"ما وجه التمثيل بين إحياء الأرض وإحياء الموتى؟","answer":"كما يحول الماء أرضًا هامدة إلى حياة نامية، يخرج الله الموتى؛ والمشهد المتكرر دليل قدرة محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص508–523.","url":""}]},{"id":"s41-89","number":89,"surah":41,"verses":[40],"verseLabel":"فصلت: 40","question":"ما سر التعبير بالإلحاد في آيات الله، وما الصورة التي يرسمها اللفظ؟","answer":"الإلحاد ميل عن القصد والاستقامة، فصور المحرفين لمعاني الآيات مائلين عن طريقها الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص523–531.","url":""}]},{"id":"s41-90","number":90,"surah":41,"verses":[40],"verseLabel":"فصلت: 40","question":"ما دلالة المقابلة بين من يُلقى في النار ومن يأتي آمنًا يوم القيامة؟","answer":"الإلقاء في النار قسري مهين، والمجيء آمنًا حركة مطمئنة؛ فالمقابلة بين نهاية الإلحاد وثمرة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص529–538.","url":""}]},{"id":"s41-91","number":91,"surah":41,"verses":[40],"verseLabel":"فصلت: 40","question":"ما دلالة التهديد في ﴿اعْمَلُوا مَا شِئْتُمْ﴾ وختمه بقوله ﴿إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ﴾؟","answer":"الأمر تهديد لا إباحة: افعلوا فلن تخفوا شيئًا، وخاتمة البصر تجعل الحرية المؤقتة تحت مراقبة الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص536–543.","url":""}]},{"id":"s41-92","number":92,"surah":41,"verses":[41],"verseLabel":"فصلت: 41","question":"ما سر تسمية القرآن ﴿الذِّكْرِ﴾ ووصفه بأنه كتاب عزيز؟","answer":"هو ذكر يوقظ الفطرة ويشرف حامله، وعزيز ممتنع من الإبطال والتحريف والغلبة؛ فجمع أثره وحصانته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص543–551.","url":""}]},{"id":"s41-93","number":93,"surah":41,"verses":[42],"verseLabel":"فصلت: 42","question":"ما دلالة نفي إتيان الباطل للقرآن ﴿مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ﴾؟","answer":"ينفي الباطل عن جهاته كلها: لا يسبقه كتاب يبطله ولا يلحقه ما ينقضه، ولا يدخل بنيته من أي طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص552–555.","url":""}]},{"id":"s41-94","number":94,"surah":41,"verses":[42],"verseLabel":"فصلت: 42","question":"ما مناسبة وصف منزّل الكتاب بأنه ﴿حَكِيمٍ حَمِيدٍ﴾، وتقديم الحكمة؟","answer":"الحكيم أحكم الكتاب ووضع معانيه، والحميد يستحق الحمد على تنزيله؛ وقدمت الحكمة لأنها ظاهرة في البناء المنزّل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص556–559.","url":""}]},{"id":"s41-95","number":95,"surah":41,"verses":[43],"verseLabel":"فصلت: 43","question":"ما دلالة تسلية الرسول ﷺ بأنه ما يقال له إلا ما قيل للرسل من قبله؟","answer":"التكذيب والأذى سنة واجهت الرسل، فليس ما يقال له دليل فشل أو خصوصية، بل طريق الرسالة الذي انتهى بالنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص559–568.","url":""}]},{"id":"s41-96","number":96,"surah":41,"verses":[43],"verseLabel":"فصلت: 43","question":"ما سر الجمع بين سعة مغفرة الرب وشدة عقابه، وتقديم المغفرة؟","answer":"قدمت المغفرة لتفتح الرجاء أمام المكذب، ثم شدة العقاب لمن أصر؛ فجمع باب العودة وحاجز الاستهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص564–570.","url":""}]},{"id":"s41-97","number":97,"surah":41,"verses":[44],"verseLabel":"فصلت: 44","question":"ما دلالة الاحتجاج الافتراضي بقوله ﴿وَلَوْ جَعَلْنَاهُ قُرْآنًا أَعْجَمِيًّا﴾؟","answer":"لو كان أعجميًا لاعترضوا بعدم تفصيله ولسانه، فلما جاء عربيًا أعرضوا؛ فالافتراض يكشف أن الاعتراض متحرك لا طلب فهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص570–579.","url":""}]},{"id":"s41-98","number":98,"surah":41,"verses":[44],"verseLabel":"فصلت: 44","question":"ما سر جمع القرآن للمؤمنين بين الهدى والشفاء، وتقديم الهدى؟","answer":"الهدى يبين الطريق أولًا، والشفاء يزيل أمراض الشك والشهوة التي تمنع سلوكه؛ فقدم الدليل ثم العلاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص579–583.","url":""}]},{"id":"s41-99","number":99,"surah":41,"verses":[44],"verseLabel":"فصلت: 44","question":"ما سر تصوير حال غير المؤمنين بأن في آذانهم وقرًا وأن القرآن عليهم عمى؟","answer":"الوقر يمنع وصول الصوت النافع، والعمى يمنع رؤية المعنى؛ فصار القرآن نفسه عليهم عمى بسبب موقفهم لا لخفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص581–587.","url":""}]},{"id":"s41-100","number":100,"surah":41,"verses":[44],"verseLabel":"فصلت: 44","question":"ما وجه تمثيل غير المنتفعين بالقرآن بقوم ﴿يُنَادَوْنَ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"يسمع البعيد صوتًا لا تتبين حروفه، وكذلك يصلهم القرآن دون فهم بسبب حواجزهم؛ البعد معنوي صنعه الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص586–590.","url":""}]},{"id":"s41-101","number":101,"surah":41,"verses":[45],"verseLabel":"فصلت: 45","question":"ما دلالة وصل اختلاف بني إسرائيل في الكتاب بإمهالهم إلى كلمة سبقت من الله؟","answer":"اختلافهم لم يعاجل بالحسم لأن كلمة الإمهال إلى أجل سبقت؛ فتأخر القضاء لا يدل على رضا أو غياب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص590–607.","url":""}]},{"id":"s41-102","number":102,"surah":41,"verses":[46],"verseLabel":"فصلت: 46","question":"ما دلالة مقابلة اللام في ﴿فَلِنَفْسِهِ﴾ بـ﴿فَعَلَيْهَا﴾ في قاعدة الجزاء؟","answer":"اللام تعيد نفع الصالح إلى صاحبه، و﴿عَلَيْهَا﴾ تحمل المسيء تبعته؛ فترسم المسؤولية في حرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص607–613.","url":""}]},{"id":"s41-103","number":103,"surah":41,"verses":[46],"verseLabel":"فصلت: 46","question":"ما سر التعبير بـ﴿الْعَبِيدِ﴾ في قوله ﴿وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ﴾؟","answer":"العبيد يبرز كثرة الخلق وعبوديتهم مع ضعفهم، فنفي أدنى الظلم عنهم أبلغ في تقرير عدله الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص613–618.","url":""}]},{"id":"s41-104","number":104,"surah":41,"verses":[47],"verseLabel":"فصلت: 47","question":"ما سر الجمع بين اختصاص الله بعلم الساعة وعلمه بخروج الثمرات والحمل والوضع؟","answer":"جمع أعظم غيب منتظر بأدق تغيرات الحياة اليومية؛ فعلمه يحيط بالزمن الكوني وتفاصيل الثمر والرحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص618–632.","url":""}]},{"id":"s41-105","number":105,"surah":41,"verses":[47],"verseLabel":"فصلت: 47","question":"ما دلالة سؤال المشركين يوم القيامة ﴿أَيْنَ شُرَكَائِي﴾ ثم قولهم ﴿آذَنَّاكَ مَا مِنَّا مِنْ شَهِيدٍ﴾؟","answer":"السؤال يطالبهم بشركائهم المزعومين، فيعلنون أنهم أعلموه بعدم وجود شاهد منهم؛ فتنهار الدعوى عند المعاينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص630–643.","url":""}]},{"id":"s41-106","number":106,"surah":41,"verses":[48],"verseLabel":"فصلت: 48","question":"ما دلالة قوله ﴿وَضَلَّ عَنْهُمْ مَا كَانُوا يَدْعُونَ مِنْ قَبْلُ﴾ ثم يقينهم أنه لا محيص؟","answer":"غابت المعبودات التي اعتادوها، ثم تيقنوا أن لا مهرب؛ فسقط المأمول الخارجي والطريق الذاتي معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص638–645.","url":""}]},{"id":"s41-107","number":107,"surah":41,"verses":[49],"verseLabel":"فصلت: 49","question":"ما دلالة الجمع بين عدم سآمة الإنسان من دعاء الخير وشدة يأسه عند مس الشر؟","answer":"لا يمل من طلب النعمة لتعلق قلبه بها، فإذا مسه الشر قطع الرجاء بسرعة؛ فجمع طول الطمع وسرعة الانهيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص645–655.","url":""}]},{"id":"s41-108","number":108,"surah":41,"verses":[9],"verseLabel":"فصلت: 49؛ هود: 9","question":"ما سر وصف الإنسان هنا بأنه ﴿يَئُوسٌ قَنُوطٌ﴾، وفي هود بأنه ﴿يَئُوسٌ كَفُورٌ﴾؟","answer":"في فصلت اجتمع اليأس من الفرج والقنوط الشديد لتصوير الحالة النفسية، وفي هود أضيف الكفران لبيان أثرها في جحود النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص645–655.","url":""}]},{"id":"s41-109","number":109,"surah":41,"verses":[50],"verseLabel":"فصلت: 50","question":"ما دلالة تصوير الرحمة بعد الضر بأنها مذاقة من الله؟","answer":"الإذاقة تستحضر أثر الرحمة المباشر بعد ألم الضر، وتؤكد أن ما وجده من الله لا من استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص655–662.","url":""}]},{"id":"s41-110","number":110,"surah":41,"verses":[50],"verseLabel":"فصلت: 50","question":"ما سر انتقال الإنسان من الرحمة إلى قوله ﴿هَذَا لِي﴾ ثم إنكاره الساعة؟","answer":"ينسب النعمة إلى حق ذاتي ﴿هَذَا لِي﴾، ثم يقوده الغرور إلى إنكار الحساب؛ فالاستحقاق الموهوم يغذي الاستغناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص657–668.","url":""}]},{"id":"s41-111","number":111,"surah":41,"verses":[50],"verseLabel":"فصلت: 50","question":"ما دلالة الجمع في زعم الإنسان بين الشك في قيام الساعة وتوقع الحسنى عند ربه؟","answer":"يشك في أصل الساعة حين يطلب منه العمل، لكنه يضمن لنفسه الحسنى إن رجع؛ فجمع إنكار المسؤولية وادعاء الامتياز.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص663–671.","url":""}]},{"id":"s41-112","number":112,"surah":41,"verses":[50],"verseLabel":"فصلت: 50","question":"ما دلالة مقابلة زعم الكافر بالحسنى بتوعّده أن يُنبأ بما عمل ويُذاق من عذاب غليظ؟","answer":"سيكشف له عمله بدل الحسنى المتوهمة، ثم يذوق عذابًا غليظًا؛ فقوبلت الدعوى بالبيان والنعيم المزعوم بالألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص668–675.","url":""}]},{"id":"s41-113","number":113,"surah":41,"verses":[51],"verseLabel":"فصلت: 51","question":"ما سر الجمع بين إعراض الإنسان ونأيه بجانبه عند النعمة؟","answer":"الإعراض ترك الشكر، والنأي بالجانب هيئة المتكبر المنحرف؛ فجمع البعد المعنوي وصورته الجسدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص675–683.","url":""}]},{"id":"s41-114","number":114,"surah":41,"verses":[51],"verseLabel":"فصلت: 51","question":"ما دلالة وصف دعاء الإنسان عند مس الشر بأنه ﴿دُعَاءٍ عَرِيضٍ﴾؟","answer":"العريض ممتد كثير الجوانب، فصور دعاءه طويلًا متكررًا بعد أن كان معرضًا عند النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص683–687.","url":""}]},{"id":"s41-115","number":115,"surah":41,"verses":[52],"verseLabel":"فصلت: 52","question":"ما دلالة الاحتجاج بقوله ﴿إِنْ كَانَ مِنْ عِنْدِ اللَّهِ ثُمَّ كَفَرْتُمْ بِهِ﴾؟","answer":"الشرط يلزمهم بأخطر احتمال: إن كان القرآن من الله فكفرهم به أبعد الضلال؛ والعاقل لا يجازف أمام هذه الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص687–696.","url":""}]},{"id":"s41-116","number":116,"surah":41,"verses":[52],"verseLabel":"فصلت: 52","question":"ما سر تصوير الكافرين بالقرآن بأنهم في ﴿شِقَاقٍ بَعِيدٍ﴾؟","answer":"الشقاق يجعلهم في شق مقابل للحق، ووصفه بالبعد يصور اتساع الفجوة حتى يصعب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص692–696.","url":""}]},{"id":"s41-117","number":117,"surah":41,"verses":[53],"verseLabel":"فصلت: 53","question":"ما سر الجمع بين آيات الآفاق وآيات الأنفس، وتقديم الآفاق؟","answer":"بدأ بالآفاق الأوسع والأظهر لجميع الناس، ثم قرب الدليل إلى أنفسهم؛ فحاصر البرهان الخارج والداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص697–701.","url":""}]},{"id":"s41-118","number":118,"surah":41,"verses":[53],"verseLabel":"فصلت: 53","question":"ما دلالة قوله ﴿حَتَّى يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ﴾ بعد الوعد بإراءة الآيات؟","answer":"تتوالى الآيات إلى غاية انكشاف صدق القرآن والوعد، لا لمجرد الإبهار؛ فالرؤية طريق إلى حكم معرفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص699–704.","url":""}]},{"id":"s41-119","number":119,"surah":41,"verses":[53],"verseLabel":"فصلت: 53","question":"ما سر الانتقال من آيات الآفاق والأنفس إلى الاكتفاء بشهادة الله على كل شيء؟","answer":"دلائل الكون والإنسان كثيرة، لكن شهادة الله بوحيه وعلمه تكفي أصلًا؛ فانتقل من الشواهد المخلوقة إلى الشاهد المحيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص701–708.","url":""}]},{"id":"s41-120","number":120,"surah":41,"verses":[54],"verseLabel":"فصلت: 54","question":"ما دلالة تكرار ﴿أَلَا إِنَّ﴾ في ختام السورة، بين شكهم في لقاء ربهم وإحاطة الله بكل شيء؟","answer":"الأولى تنبه إلى شكهم الخطير، والثانية إلى الحقيقة التي تبطله؛ فتكرار التنبيه يهزهم بين المرض والجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص708–710.","url":""}]},{"id":"s41-121","number":121,"surah":41,"verses":[54],"verseLabel":"فصلت: 54","question":"ما سر التعبير بلقاء الرب عن البعث والحساب مع إضافته إلى ضميرهم؟","answer":"اللقاء يستحضر المواجهة بالحساب والوقوف بين يدي المربي، وإضافته إليهم تهدم توهم البعد: هو ربهم الذي سيلاقونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص708–710.","url":""}]},{"id":"s41-122","number":122,"surah":41,"verses":[54],"verseLabel":"فصلت: 54","question":"ما سر ختم السورة بقوله ﴿أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُحِيطٌ﴾؟","answer":"الإحاطة تعني أن لا شيء يخرج عن علمه وقدرته، فتختم جواب الشك في البعث وتضمن تحقق كل وعيد ووعد سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص708–710.","url":""}]},{"id":"s42-1","number":1,"surah":42,"verses":[1],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الشورى» مع أن لفظ الشورى لم يرد فيها إلا مرة واحدة؟","answer":"الشورى مبدأ جامع لإدارة أمر الجماعة مع بقاء مرجعيتها للوحي؛ فناسب أن تسمى السورة به وهي تؤصل وحدة الدين ومسؤولية المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص715–718.","url":""}]},{"id":"s42-2","number":2,"surah":42,"verses":[1],"verseLabel":"مقدمة السورة","question":"ما دلالة اجتماع الوحي ووحدة الدين والشورى في بناء سورة واحدة؟","answer":"الوحي يحدد أصل الدين، ووحدته تمنع التفرق، والشورى تنظم تنزيله في حياة الجماعة؛ فاجتمع المصدر والمقصد وطريقة العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص717–723.","url":""}]},{"id":"s42-3","number":3,"surah":42,"verses":[1],"verseLabel":"مقدمة السورة","question":"ما سر افتتاح السورة بالوحي وختمها به؟","answer":"افتتحت بسنّة الوحي إلى محمد ومن قبله، وختمت بتفصيل طرق التكليم ووصف القرآن روحًا ونورًا؛ فأحاط الوحي بناء السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص719–723.","url":""}]},{"id":"s42-4","number":4,"surah":42,"verses":[1,2],"verseLabel":"الشورى: 1–2","question":"ما سر اختصاص سورة الشورى بمطلع ﴿حم عسق﴾ وفصل ﴿حم﴾ عن ﴿عسق﴾ في آيتين؟","answer":"اختصاصها يزيد المطلع تميزًا ويناسب تفصيل الوحي فيها، وفصل الآيتين يجعل ﴿حم﴾ وحدة ثم ﴿عسق﴾ وحدة مستقلة في التلاوة والتنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص724–728.","url":""}]},{"id":"s42-5","number":5,"surah":42,"verses":[1,2,3],"verseLabel":"الشورى: 1–3","question":"ما مناسبة الحروف المقطعة للانتقال المباشر إلى قوله ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾؟","answer":"الحروف من مادة كلام العرب ثم أعقبها الوحي المعجز المؤلف منها؛ فانتقل من المبنى الذي يعرفونه إلى المصدر الذي لا يملكون مثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص724–736.","url":""}]},{"id":"s42-6","number":6,"surah":42,"verses":[3],"verseLabel":"الشورى: 3","question":"ما دلالة التعبير بالمضارع في ﴿يُوحِي إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ﴾، وتقديم خطاب النبي ﷺ؟","answer":"المضارع يستحضر تجدد الوحي واستمرار سنته، وقدم النبي لأنه المخاطب المتلقي الآن ثم وصله بسلسلة الرسل قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص728–733.","url":""}]},{"id":"s42-7","number":7,"surah":42,"verses":[3],"verseLabel":"الشورى: 3","question":"ما مناسبة ختم الحديث عن الوحي باسمي ﴿الْعَزِيزُ الْحَكِيمُ﴾ وتقديم العزيز؟","answer":"العزيز لا يغلب وحيه، والحكيم يضع رسالاته مواضعها؛ وقدمت العزة لمقام نفاذ التنزيل رغم المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص730–735.","url":""}]},{"id":"s42-8","number":8,"surah":42,"verses":[3,4],"verseLabel":"الشورى: 3–4","question":"ما دلالة الانتقال من الوحي إلى تقرير ملك الله لما في السماوات والأرض؟","answer":"من يملك العالمين هو صاحب الحق في التشريع والوحي؛ فانتقل من كلامه المنزل إلى سلطان من أنزله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص728–740.","url":""}]},{"id":"s42-9","number":9,"surah":42,"verses":[4],"verseLabel":"الشورى: 4","question":"ما مناسبة وصف مالك السماوات والأرض بأنه ﴿الْعَلِيُّ الْعَظِيمُ﴾؟","answer":"العلو يناسب ملكه فوق كل سلطان، والعظمة تناسب سعة السماوات والأرض؛ فالاسمان نتيجة لما سبق من عموم الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص736–740.","url":""}]},{"id":"s42-10","number":10,"surah":42,"verses":[4,5],"verseLabel":"الشورى: 4–5","question":"ما سر الانتقال من وصف الله بـ﴿الْعَلِيُّ الْعَظِيمُ﴾ إلى صورة السماوات تكاد يتفطرن من فوقهن؟","answer":"إذا ثبت علوه وعظمته جاءت صورة السماوات المتأثرة بجلاله وبفداحة الشرك المنسوب إليه؛ فانتقل من الصفة إلى أثرها الكوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص737–746.","url":""}]},{"id":"s42-11","number":11,"surah":42,"verses":[5],"verseLabel":"الشورى: 5","question":"ما دلالة التعبير بـ﴿تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ مِنْ فَوْقِهِنَّ﴾؟","answer":"تصور السماوات على ضخامتها تكاد تتشقق من أعلاها، تهويلًا لجلال الله أو لفداحة قول أهل الأرض في حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص740–746.","url":""}]},{"id":"s42-12","number":12,"surah":42,"verses":[5],"verseLabel":"الشورى: 5","question":"ما سر الانتقال من تفطر السماوات إلى تسبيح الملائكة واستغفارهم لمن في الأرض؟","answer":"يقابل اضطراب السماوات نظام الملائكة في التسبيح، ثم يتحول تعظيمهم لله إلى رحمة بأهل الأرض عبر الاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص744–750.","url":""}]},{"id":"s42-13","number":13,"surah":42,"verses":[5],"verseLabel":"الشورى: 5","question":"ما دلالة التعبير بـ﴿يَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ﴾ دون تخصيص المؤمنين؟","answer":"اللفظ عام، وقيل يراد به المؤمنون بدلالة النصوص الأخرى، أو دعاؤهم لأهل الأرض بالهداية والمغفرة؛ فاختير العموم لإظهار سعة الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص745–750.","url":""}]},{"id":"s42-14","number":14,"surah":42,"verses":[5],"verseLabel":"الشورى: 5","question":"ما مناسبة ختم مشهد التفطر والتسبيح والاستغفار بقوله ﴿أَلَا إِنَّ اللَّهَ هُوَ الْغَفُورُ الرَّحِيمُ﴾؟","answer":"بعد هول التفطر جاء الاستغفار، فختم بالمغفرة والرحمة ليقرر أن الجلال لا يحجب باب التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص747–751.","url":""}]},{"id":"s42-15","number":15,"surah":42,"verses":[6],"verseLabel":"الشورى: 6","question":"ما سر مقابلة ﴿اللَّهُ حَفِيظٌ عَلَيْهِمْ﴾ بقوله للنبي ﷺ ﴿وَمَا أَنْتَ عَلَيْهِمْ بِوَكِيلٍ﴾؟","answer":"الله يحفظ أعمالهم ويحاسبهم، أما الرسول فمبلغ لا يملك إجبارهم ولا تدبير مصائرهم؛ فتحدد المسؤوليتان بدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص751–758.","url":""}]},{"id":"s42-16","number":16,"surah":42,"verses":[3,7],"verseLabel":"الشورى: 3، 7","question":"ما دلالة الانتقال من ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾ إلى ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا﴾؟","answer":"المضارع يقرر سنة الوحي العامة المستمرة، والماضي يخص القرآن العربي الذي تم إنزاله إلى الرسول؛ فانتقل من القانون إلى تطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص728–762.","url":""}]},{"id":"s42-17","number":17,"surah":42,"verses":[7],"verseLabel":"الشورى: 7","question":"ما سر وصف الوحي بأنه ﴿قُرْآنًا عَرَبِيًّا﴾ وربط إنذاره بـ﴿أُمَّ الْقُرَى وَمَنْ حَوْلَهَا﴾؟","answer":"عربيته تقيم الحجة على أم القرى بلسانها، ومنها يمتد الإنذار إلى من حولها؛ فجمع وضوح الوسيلة واتساع الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص758–766.","url":""}]},{"id":"s42-18","number":18,"surah":42,"verses":[7],"verseLabel":"الشورى: 7","question":"ما دلالة تكرار ﴿وَتُنْذِرَ﴾ عند الانتقال من إنذار أم القرى إلى إنذار يوم الجمع؟","answer":"الأول إنذار للمكان وأهله، والثاني إنذار بالغاية الكبرى يوم الجمع؛ وتكرار الفعل يستقل بكل متعلق ويعظمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص761–768.","url":""}]},{"id":"s42-19","number":19,"surah":42,"verses":[7],"verseLabel":"الشورى: 7","question":"ما سر تسمية القيامة ﴿يَوْمَ الْجَمْعِ﴾ ثم تقسيم الخلق إلى ﴿فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ﴾؟","answer":"يجمع الله الأولين والآخرين ثم يفصل بينهم إلى مصيرين؛ فاسم الجمع يسبق لحظة التمييز النهائي بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص763–770.","url":""}]},{"id":"s42-20","number":20,"surah":42,"verses":[7,8],"verseLabel":"الشورى: 7–8","question":"ما دلالة الانتقال من انقسام الخلق إلى قوله ﴿وَلَوْ شَاءَ اللَّهُ لَجَعَلَهُمْ أُمَّةً وَاحِدَةً﴾؟","answer":"الانقسام وقع وفق حكمة الاختيار والجزاء، مع قدرة الله على جمعهم قسرًا على حال واحدة؛ فالمشيئة لا تنفي التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص765–775.","url":""}]},{"id":"s42-21","number":21,"surah":42,"verses":[8],"verseLabel":"الشورى: 8","question":"ما سر التعبير بدخول من يشاء الله ﴿فِي رَحْمَتِهِ﴾؟","answer":"صورت الرحمة كحيز واسع يحيط بمن يدخله الله، لا عطاء جزئي؛ فالدخول أمن شامل ورعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص772–775.","url":""}]},{"id":"s42-22","number":22,"surah":42,"verses":[8],"verseLabel":"الشورى: 8","question":"ما دلالة إظهار ﴿الظَّالِمُونَ﴾ ثم نفي الولي والنصير عنهم معًا؟","answer":"إظهار الاسم يثبت أن ظلمهم سبب الحرمان، ونفي الولي والنصير يسقط الرعاية الدائمة والمساعدة العارضة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص773–778.","url":""}]},{"id":"s42-23","number":23,"surah":42,"verses":[6,9],"verseLabel":"الشورى: 6، 9","question":"ما سر تكرار اتخاذ الأولياء من دون الله ثم قصر الولاية بقوله ﴿فَاللَّهُ هُوَ الْوَلِيُّ﴾؟","answer":"اتخاذ الأولياء دعوى بشرية متكررة، ثم جاء القصر ليحسم الحقيقة: الله وحده صاحب الولاية النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص751–755، 779–784.","url":""}]},{"id":"s42-24","number":24,"surah":42,"verses":[9],"verseLabel":"الشورى: 9","question":"ما مناسبة الاستدلال على ولاية الله بأنه يحيي الموتى وهو على كل شيء قدير؟","answer":"الولي الحق قادر على إنقاذ عباده من أعظم عجز وهو الموت، ومن قدر على الإحياء قدر على كل نصر ورعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص782–787.","url":""}]},{"id":"s42-25","number":25,"surah":42,"verses":[10],"verseLabel":"الشورى: 10","question":"ما سر التعبير عن مرجع الاختلاف بقوله ﴿فَحُكْمُهُ إِلَى اللَّهِ﴾ دون «فالله يحكم فيه»؟","answer":"جعل الحكم نفسه صائرًا إلى الله يفيد اختصاصه بالمرجع والحسم، وهو أرسخ من مجرد الإخبار بأنه يحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص787–791.","url":""}]},{"id":"s42-26","number":26,"surah":42,"verses":[10],"verseLabel":"الشورى: 10","question":"ما دلالة التوازي بين ﴿عَلَيْهِ تَوَكَّلْتُ﴾ و﴿إِلَيْهِ أُنِيبُ﴾، واختلاف زمن الفعلين؟","answer":"﴿عَلَيْهِ﴾ تعلق الاعتماد في الماضي والحاضر، و﴿إِلَيْهِ أُنِيبُ﴾ تجدد الرجوع؛ فالتوكل اعتماد والإنابة حركة متكررة نحوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص789–795.","url":""}]},{"id":"s42-27","number":27,"surah":42,"verses":[11],"verseLabel":"الشورى: 11","question":"ما سر الجمع بين جعل الأزواج للناس والأنعام والتعبير بـ﴿يَذْرَؤُكُمْ فِيهِ﴾؟","answer":"جعل التزاوج في الإنسان والأنعام سبب استمرار النوع، و﴿يَذْرَؤُكُمْ فِيهِ﴾ أي يكثركم في هذا النظام أو بسببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص795–806.","url":""}]},{"id":"s42-28","number":28,"surah":42,"verses":[11],"verseLabel":"الشورى: 11","question":"ما سر التعبير في قوله ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ﴾ دون «ليس مثله شيء»؟","answer":"زيادة الكاف قيلت للتوكيد، فتنفي حتى مثل المثل، والمقصود القطع المطلق بأنه لا يشبهه شيء بلا تعطيل لصفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص795–817.","url":""}]},{"id":"s42-29","number":29,"surah":42,"verses":[11],"verseLabel":"الشورى: 11","question":"ما دلالة الجمع بين نفي المماثلة وإثبات السمع والبصر في آية واحدة؟","answer":"نزّه ذاته عن مشابهة المخلوق ثم أثبت له سمعًا وبصرًا يليقان به؛ فجمع التنزيه والإثبات ومنع التشبيه والتعطيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص803–817.","url":""}]},{"id":"s42-30","number":30,"surah":42,"verses":[12],"verseLabel":"الشورى: 12","question":"ما سر التعبير عن ملك الله بـ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾ ثم ذكر بسط الرزق وتقديره؟","answer":"المقاليد مفاتيح الخزائن والسلطان عليها؛ فمن بيده خزائن الكون يبسط الرزق ويقدره بعلم، لا بعجز أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص795–817.","url":""}]},{"id":"s42-31","number":31,"surah":42,"verses":[103],"verseLabel":"الشورى: 13؛ آل عمران: 103","question":"ما سر التعبير هنا بـ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾ بتاءين، وفي آل عمران ﴿وَلَا تَفَرَّقُوا﴾ بتاء واحدة؟","answer":"زيادة التاء هنا توافق بناءً أطول في سياق إقامة الدين والتحذير من التفرق فيه، والحذف في آل عمران تخفيف لغوي جائز؛ والمعنى الأصلي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص10–28.","url":""}]},{"id":"s42-32","number":32,"surah":42,"verses":[13],"verseLabel":"الشورى: 13","question":"ما دلالة التعبير بالوصية مع نوح وإبراهيم وموسى وعيسى، وبالوحي مع النبي ﷺ؟","answer":"الوصية تبرز العهد المؤكد المشترك للرسل، والوحي للنبي يبرز طريق تلقيه هذا العهد؛ فاجتمع ثبات المضمون وتجدد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص10–17.","url":""}]},{"id":"s42-33","number":33,"surah":42,"verses":[13],"verseLabel":"الشورى: 13","question":"ما سر ترتيب أسماء الرسل الخمسة في آية وحدة الدين؟","answer":"بدأ بنوح أول رسول إلى أهل الأرض، ثم ذكر إبراهيم، ثم موسى وعيسى بحسب التعاقب، وأحاط بهم وحي محمد المخاطب في صدر الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص11–17.","url":""}]},{"id":"s42-34","number":34,"surah":42,"verses":[13],"verseLabel":"الشورى: 13","question":"ما دلالة الجمع بين الأمر بإقامة الدين والنهي عن التفرق فيه؟","answer":"إقامة الدين بناء إيجابي لأصوله والعمل بها، وعدم التفرق حماية لهذا البناء من تمزيق الهوى؛ فجمع الإنشاء والصيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص14–22.","url":""}]},{"id":"s42-35","number":35,"surah":42,"verses":[13],"verseLabel":"الشورى: 13","question":"ما سر تكرار ﴿إِلَيْهِ﴾ في ختام الآية، والتمييز بين من يجتبيه الله ومن يهديه؟","answer":"الأول غاية الاجتباء: يختار الله إليه من يشاء ابتداءً، والثاني غاية الهداية: يوفق للرجوع من أقبل بالإنابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص18–29.","url":""}]},{"id":"s42-36","number":36,"surah":42,"verses":[13,14],"verseLabel":"الشورى: 13–14","question":"ما دلالة الانتقال من النهي عن التفرق إلى تقرير أنهم لم يتفرقوا إلا بعد مجيء العلم؟","answer":"جاء النهي أولًا قاعدة الوحي، ثم كشف التاريخ أنهم خالفوها بعد العلم؛ فالمشكلة ليست نقص البيان بل فساد الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص14–35.","url":""}]},{"id":"s42-37","number":37,"surah":42,"verses":[14],"verseLabel":"الشورى: 14","question":"ما سر تعليل التفرق بعد العلم بقوله ﴿بَغْيًا بَيْنَهُمْ﴾؟","answer":"البغي طلب الاستعلاء والمصلحة على حساب الحق، و﴿بَيْنَهُمْ﴾ يبين أن النزاع نشأ داخل الجماعة لا لغياب الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص29–35.","url":""}]},{"id":"s42-38","number":38,"surah":42,"verses":[14],"verseLabel":"الشورى: 14","question":"ما دلالة إمهال المختلفين إلى ﴿أَجَلٍ مُسَمًّى﴾ بسبب كلمة سبقت من الله؟","answer":"الكلمة السابقة هي تأخير الفصل إلى موعد معلوم؛ فلولاها لعوجلوا بالحكم، فالإمهال تقدير لا رضا بالاختلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص33–39.","url":""}]},{"id":"s42-39","number":39,"surah":42,"verses":[14],"verseLabel":"الشورى: 14","question":"ما سر التعبير عن المتأخرين بـ﴿الَّذِينَ أُورِثُوا الْكِتَابَ مِنْ بَعْدِهِمْ﴾، ووصفهم بأنهم في ﴿شَكٍّ مُرِيبٍ﴾؟","answer":"الإيراث يوحي بأن الكتاب وصلهم من أسلاف دون تلقي حي واعٍ، فصاروا مع قربه في شك يوقع الريبة ولا يدع طمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص36–45.","url":""}]},{"id":"s42-40","number":40,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"إلى ماذا يشير قوله ﴿فَلِذَلِكَ فَادْعُ﴾، وما سر تقديم الإشارة على الأمر بالدعوة؟","answer":"تشير إلى الدين الواحد أو إلى ما وقع من التفرق؛ أي فلأجل إقامة الحق وجمع الناس عليه فادع، وتقديمها يربط الأمر بعلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص45–49.","url":""}]},{"id":"s42-41","number":41,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"ما دلالة الجمع بين ﴿فَادْعُ﴾ و﴿وَاسْتَقِمْ كَمَا أُمِرْتَ﴾ والنهي عن اتباع أهوائهم؟","answer":"الدعوة تبليغ للناس، والاستقامة ثبات للداعي، وترك أهوائهم حماية للمنهج؛ فجمعت الآية أثر الرسالة في الخارج والداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص45–51.","url":""}]},{"id":"s42-42","number":42,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"ما سر الانتقال من الأمر بالدعوة والاستقامة إلى إعلان الإيمان بكل كتاب أنزله الله؟","answer":"الاستقامة على وحدة الدين تقتضي التصديق بكل وحي صحيح، فلا تكون الدعوة حزبية لكتاب مع جحد سائر رسالات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص48–53.","url":""}]},{"id":"s42-43","number":43,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"ما دلالة اقتران الإيمان بالكتب كلها بالأمر بالعدل بين المخاطبين؟","answer":"الإيمان بالكتب يمنح العدل مرجعيته، والعدل يثبت أن التصديق ليس دعوى بل إنصاف عملي لأتباع الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص50–54.","url":""}]},{"id":"s42-44","number":44,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"ما سر التوازي بين ﴿اللَّهُ رَبُّنَا وَرَبُّكُمْ﴾ و﴿لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ﴾؟","answer":"وحدة الرب لا تلغي المسؤولية الفردية؛ ربنا واحد، لكن لكل فريق كسبه الذي يحاسب عليه، فلا تحمل جماعة عمل الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص51–56.","url":""}]},{"id":"s42-45","number":45,"surah":42,"verses":[15],"verseLabel":"الشورى: 15","question":"ما دلالة الانتقال من ﴿لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ﴾ إلى ﴿اللَّهُ يَجْمَعُ بَيْنَنَا﴾؟","answer":"بعد وضوح الحق لا تبقى خصومة نافعة، وسيجمع الله الجميع للحكم؛ فانتقل من انتهاء الجدل في الدنيا إلى الفصل في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص53–61.","url":""}]},{"id":"s42-46","number":46,"surah":42,"verses":[16],"verseLabel":"الشورى: 16","question":"ما الصورة التي يرسمها وصف حجة المحاجّين بأنها ﴿دَاحِضَةٌ عِنْدَ رَبِّهِمْ﴾؟","answer":"الدحض هو الزلق والسقوط؛ فصورت حجتهم وقد انزلقت عن موضع الثبات وسقط اعتبارها في ميزان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص61–69.","url":""}]},{"id":"s42-47","number":47,"surah":42,"verses":[16],"verseLabel":"الشورى: 16","question":"ما دلالة تدرج جزاء المحاجّين من دحض الحجة إلى الغضب ثم العذاب الشديد؟","answer":"تسقط حجتهم أولًا، ثم يحل غضب الله على عنادهم، ثم يظهر أثره في العذاب؛ فتدرج من بطلان القول إلى الحكم فالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص64–76.","url":""}]},{"id":"s42-48","number":48,"surah":42,"verses":[17],"verseLabel":"الشورى: 17","question":"ما سر الجمع بين إنزال الكتاب بالحق وإنزال الميزان؟","answer":"الكتاب يبين الحق، والميزان يقيس به الأقوال والأعمال بعدل؛ فجمع مصدر الحكم وأداة تنزيله في الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص78–84.","url":""}]},{"id":"s42-49","number":49,"surah":42,"verses":[17],"verseLabel":"الشورى: 17","question":"ما مناسبة الانتقال من الكتاب والميزان إلى التنبيه على قرب الساعة؟","answer":"إذا نزل الكتاب والميزان قامت الحجة واستحق العمل، ثم ذُكرت الساعة لأن تمام الوزن والفصل يقع فيها وقد تكون قريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص81–88.","url":""}]},{"id":"s42-50","number":50,"surah":42,"verses":[17],"verseLabel":"الشورى: 17","question":"ما سر وصف الساعة المؤنثة بقوله ﴿قَرِيبٌ﴾؟","answer":"قريب على تأويل الساعة باليوم أو الوقت، أو لأن فعيلًا يستوي فيه المذكر والمؤنث؛ والمعنى تأكيد دنوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82–87.","url":""}]},{"id":"s42-51","number":51,"surah":42,"verses":[18],"verseLabel":"الشورى: 18","question":"ما دلالة مقابلة استعجال غير المؤمنين بالساعة بإشفاق المؤمنين منها وعلمهم أنها الحق؟","answer":"غير المؤمن يستعجلها استهزاءً لعدم تصديقه، والمؤمن يخافها لأنه يعلم حقيقتها؛ فالموقفان يكشفان أثر العلم والإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص88–95.","url":""}]},{"id":"s42-52","number":52,"surah":42,"verses":[17,18],"verseLabel":"الشورى: 17–18","question":"ما سر الجمع بين قرب الساعة ووصف الممارين فيها بأنهم في ﴿ضَلَالٍ بَعِيدٍ﴾؟","answer":"هي قريبة في الزمن والوقوع، لكن من يجادل فيها بعيد عن الحق؛ فقرب الحقيقة لم يمنع بعد القلب عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82–103.","url":""}]},{"id":"s42-53","number":53,"surah":42,"verses":[19],"verseLabel":"الشورى: 19","question":"ما دلالة الجمع بين لطف الله بعباده ومشيئته في الرزق وقوته وعزته؟","answer":"لطفه يوصل الرزق بدقائق الحكمة، ومشيئته تخصص المقادير، وقوته وعزته تنفيان أن يكون التقدير عن عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص103–112.","url":""}]},{"id":"s42-54","number":54,"surah":42,"verses":[19],"verseLabel":"الشورى: 19","question":"ما مناسبة وصف الله بـ﴿لَطِيفٌ﴾ في سياق الرزق، ثم ختم الآية بـ﴿الْقَوِيُّ الْعَزِيزُ﴾؟","answer":"اللطف يناسب إيصال الرزق من طرق خفية دقيقة، والقوة والعزة تضمنان القدرة على بسطه ومنعه؛ فاجتمع الرفق والاقتدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص103–112.","url":""}]},{"id":"s42-55","number":55,"surah":42,"verses":[20],"verseLabel":"الشورى: 20","question":"ما سر التعبير عن عمل الدنيا والآخرة بالحرث في ﴿حَرْثَ الْآخِرَةِ﴾ و﴿حَرْثَ الدُّنْيَا﴾؟","answer":"الحرث عمل يودع اليوم لينتظر ثمره غدًا؛ فاختيار اللفظ يصور الدنيا والآخرة محصولين يتشكلان بحسب نية الزارع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص112–120.","url":""}]},{"id":"s42-56","number":56,"surah":42,"verses":[20],"verseLabel":"الشورى: 20","question":"ما دلالة اختلاف الجزاء بين ﴿نَزِدْ لَهُ فِي حَرْثِهِ﴾ لمريد الآخرة و﴿نُؤْتِهِ مِنْهَا﴾ لمريد الدنيا؟","answer":"مريد الآخرة يزاد له في أصل زرعه وثمره، أما طالب الدنيا فيعطى بعضًا منها فقط ولا يكون له نصيب باق في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص114–125.","url":""}]},{"id":"s42-57","number":57,"surah":42,"verses":[21],"verseLabel":"الشورى: 21","question":"ما سر المشاكلة بين ﴿شُرَكَاءُ﴾ و﴿شَرَعُوا لَهُمْ مِنَ الدِّينِ﴾؟","answer":"سموا آلهتهم شركاء فناسب أن ينسب إليهم فعل التشريع الذي هو من خصائص الرب؛ فتكشف المشاكلة اغتصابهم حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص126–132.","url":""}]},{"id":"s42-58","number":58,"surah":42,"verses":[21],"verseLabel":"الشورى: 21","question":"ما دلالة التعبير بالإذن في نفي مشروعية ما شرعه الشركاء من الدين؟","answer":"الدين لا يصير مشروعًا إلا بإذن الله ووحيه؛ فنفي الإذن يسقط أصل السلطة قبل مناقشة تفاصيل ما اخترعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص127–132.","url":""}]},{"id":"s42-59","number":59,"surah":42,"verses":[14,21],"verseLabel":"الشورى: 14، 21","question":"ما سر تنكير ﴿كَلِمَةٌ﴾ في الآية 14 وتعريفها بـ﴿كَلِمَةُ الْفَصْلِ﴾ في الآية 21؟","answer":"نُكرت الأولى لأنها كلمة سابقة بالإمهال، وعُرفت الثانية لأنها العهد المعهود بالفصل النهائي؛ ففرق التعريف بين التأخير والحسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص33–39، 130–136.","url":""}]},{"id":"s42-60","number":60,"surah":42,"verses":[16,21],"verseLabel":"الشورى: 16، 21","question":"ما دلالة وصف عذاب المحاجّين بـ﴿شَدِيدٌ﴾ ووصف عذاب أصحاب التشريع الباطل بـ﴿أَلِيمٌ﴾؟","answer":"الشدة تبرز قوة العذاب لمن واصل المحاجة، والألم يبرز إحساس من اتبع تشريعًا باطلًا بعاقبته؛ وكل وصف يلائم زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص66–76، 133–141.","url":""}]},{"id":"s42-61","number":61,"surah":42,"verses":[22],"verseLabel":"الشورى: 22","question":"ما سر الإخبار عن العذاب بأنه ﴿وَاقِعٌ بِهِمْ﴾ مع أن الظالمين مشفقون منه؟","answer":"إشفاقهم خوف متوقع قبل الوقوع، لكن الجملة تقطع توهم إمكان الفرار: ما يخافونه نازل بهم حتمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص141–147.","url":""}]},{"id":"s42-62","number":62,"surah":42,"verses":[22],"verseLabel":"الشورى: 22","question":"ما دلالة مقابلة ﴿وَهُوَ وَاقِعٌ بِهِمْ﴾ للظالمين بـ﴿لَهُمْ مَا يَشَاءُونَ عِنْدَ رَبِّهِمْ﴾ للمؤمنين؟","answer":"الظالمون يخافون شيئًا واقعًا لا يملكون دفعه، والمؤمنون يملكون عند ربهم ما يشاؤون؛ فقوبل حتم المكروه بسعة المرغوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص141–158.","url":""}]},{"id":"s42-63","number":63,"surah":42,"verses":[22],"verseLabel":"الشورى: 22","question":"ما سر التعبير عن نعيم المؤمنين بـ﴿فِي رَوْضَاتِ الْجَنَّاتِ﴾؟","answer":"الروضة تجمع الخضرة والبهجة والسعة، وجمعها داخل الجنات يضاعف الصورة: هم محاطون بمواضع النعيم المتنوعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص144–151.","url":""}]},{"id":"s42-64","number":64,"surah":42,"verses":[22,23],"verseLabel":"الشورى: 22–23","question":"ما دلالة الانتقال من ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ﴾ إلى ﴿ذَلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ﴾؟","answer":"الأول يقرر حقيقة النعيم ودرجته، والثاني يقربه بوصفه البشرى التي يبلغها الله لعباده الآن؛ فانتقل من الغائب إلى الوعد المسموع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص150–163.","url":""}]},{"id":"s42-65","number":65,"surah":42,"verses":[23],"verseLabel":"الشورى: 23","question":"ما سر استعمال ﴿يَقْتَرِفْ﴾ مع الحسنة ثم الوعد بزيادة الحسن فيها؟","answer":"الاقتراف اكتساب مقصود، واستعمل للحسنة ليبرز كلفة تحصيلها، ثم وعد أن ينمي الله هذا المكتسب الصغير فوق قدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص166–172.","url":""}]},{"id":"s42-66","number":66,"surah":42,"verses":[23],"verseLabel":"الشورى: 23","question":"ما مناسبة ختم آية البشرى وزيادة الحسنة بقوله ﴿إِنَّ اللَّهَ غَفُورٌ شَكُورٌ﴾، وتقديم المغفرة؟","answer":"قدمت المغفرة لإزالة السيئات التي تعوق القبول، ثم الشكر لمضاعفة الحسنات؛ فجمع محو النقص وزيادة الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص169–179.","url":""}]},{"id":"s42-67","number":67,"surah":42,"verses":[24],"verseLabel":"الشورى: 24","question":"ما سر حذف الواو رسمًا من ﴿وَيَمْحُ اللَّهُ الْبَاطِلَ﴾ مع رفع الفعل؟","answer":"حذفت الواو في الرسم اتباعًا للرسم العثماني، وقرأ الفعل مرفوعًا على الاستئناف لا معطوفًا على جواب الشرط؛ كأنه حقيقة مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص183–188.","url":""}]},{"id":"s42-68","number":68,"surah":42,"verses":[24],"verseLabel":"الشورى: 24","question":"ما دلالة المقابلة بين ﴿يَمْحُ اللَّهُ الْبَاطِلَ﴾ و﴿يُحِقُّ الْحَقَّ بِكَلِمَاتِهِ﴾؟","answer":"المحو يزيل الباطل وأثره، والإحقاق يثبت الحق وينفذه بكلمات الله؛ فجمع تطهير الساحة وبناء الثابت فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص183–190.","url":""}]},{"id":"s42-69","number":69,"surah":42,"verses":[24,25],"verseLabel":"الشورى: 24–25","question":"ما مناسبة الانتقال من علم الله بذات الصدور إلى علمه بأفعال العباد مع فتح باب التوبة والعفو؟","answer":"من يعلم خفايا الصدور يعلم الأعمال الظاهرة، ومع هذا العلم فتح التوبة والعفو؛ فالإحاطة ليست لإغلاق الرجاء بل لتصحيح الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص187–209.","url":""}]},{"id":"s42-70","number":70,"surah":42,"verses":[25],"verseLabel":"الشورى: 25","question":"ما الفرق الدلالي بين قبول التوبة والعفو عن السيئات، وما دلالة التعبير بـ﴿عَنْ عِبَادِهِ﴾؟","answer":"قبول التوبة استقبال رجوع العبد، والعفو محو تبعة السيئة؛ و﴿عَنْ عِبَادِهِ﴾ تشعر بتجاوز الذنب وإبعاده عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص197–207.","url":""}]},{"id":"s42-71","number":71,"surah":42,"verses":[26],"verseLabel":"الشورى: 26","question":"ما دلالة مقابلة استجابة المؤمنين وزيادتهم من فضل الله بعذاب الكافرين الشديد؟","answer":"المؤمنون استجابوا فاستجاب الله لهم وزادهم، والكافرون قابلوا الدعوة بالرفض فلهم العذاب؛ فكان الجزاء من جنس الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص209–220.","url":""}]},{"id":"s42-72","number":72,"surah":42,"verses":[27],"verseLabel":"الشورى: 27","question":"ما سر بيان الحكمة من عدم بسط الرزق للعباد بقوله ﴿لَبَغَوْا فِي الْأَرْضِ﴾؟","answer":"البسط المطلق قد يطغي النفوس ويدفعها إلى تجاوز الحدود؛ فالتقدير حماية وتربية، لا مجرد حرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص220–225.","url":""}]},{"id":"s42-73","number":73,"surah":42,"verses":[27],"verseLabel":"الشورى: 27","question":"ما دلالة الانتقال من البسط إلى التنزيل في ﴿وَلَكِنْ يُنَزِّلُ بِقَدَرٍ مَا يَشَاءُ﴾؟","answer":"البسط يوحي بالسعة الممتدة، والتنزيل يوحي بوصول مقادير متتابعة محسوبة؛ فانتقل من الفرض العام إلى طريقة التدبير الحكيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص220–228.","url":""}]},{"id":"s42-74","number":74,"surah":42,"verses":[27],"verseLabel":"الشورى: 27","question":"ما مناسبة ختم تقدير الرزق بقوله ﴿إِنَّهُ بِعِبَادِهِ خَبِيرٌ بَصِيرٌ﴾ وتقديم الخبير؟","answer":"الخبير يعلم بواطن حاجاتهم وآثار الرزق فيهم، والبصير يرى أحوالهم الظاهرة؛ فقدم العلم الأدق الذي ينبني عليه التقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص225–234.","url":""}]},{"id":"s42-75","number":75,"surah":42,"verses":[27,28],"verseLabel":"الشورى: 27–28","question":"ما دلالة الانتقال من تنزيل الرزق بقدر إلى إنزال الغيث بعد القنوط؟","answer":"الرزق كله ينزل بقدر، ثم قدم الغيث مثالًا يأتي في اللحظة التي تشتد فيها الحاجة؛ فالتقدير يظهر رحمة لا تضييقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص220–240.","url":""}]},{"id":"s42-76","number":76,"surah":42,"verses":[28],"verseLabel":"الشورى: 28","question":"ما سر اختيار ﴿الْغَيْثَ﴾ دون المطر، وربطه بحال القنوط؟","answer":"الغيث هو المطر الذي يغيث وينقذ، فناسب اليأس من المطر؛ اختيار الاسم يستحضر الأثر الرحيم لا مجرد الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص234–240.","url":""}]},{"id":"s42-77","number":77,"surah":42,"verses":[28],"verseLabel":"الشورى: 28","question":"ما سر التعبير بـ﴿يَنْشُرُ رَحْمَتَهُ﴾ بعد إنزال الغيث؟","answer":"بعد نقطة نزول الماء تتسع آثاره في النبات والرزق والحياة، فصور الرحمة منشورة ممتدة في الأرض وبين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص237–242.","url":""}]},{"id":"s42-78","number":78,"surah":42,"verses":[28],"verseLabel":"الشورى: 28","question":"ما مناسبة ختم آية الغيث والرحمة بقوله ﴿وَهُوَ الْوَلِيُّ الْحَمِيدُ﴾؟","answer":"الولي يتولى إنقاذهم بالغيث، والحميد يستحق الحمد على حسن تدبيره؛ فجمعت الخاتمة الرعاية والثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص239–245.","url":""}]},{"id":"s42-79","number":79,"surah":42,"verses":[29],"verseLabel":"الشورى: 29","question":"ما سر اختيار ﴿بَثَّ﴾ في قوله ﴿وَمَا بَثَّ فِيهِمَا مِنْ دَابَّةٍ﴾؟","answer":"البث نشر الكثير في جهات متفرقة؛ فيصور تنوع الدواب وكثرتها واتساع مواطنها في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص247–252.","url":""}]},{"id":"s42-80","number":80,"surah":42,"verses":[29],"verseLabel":"الشورى: 29","question":"ما دلالة تثنية الضمير في ﴿فِيهِمَا﴾ وإطلاق ﴿دَابَّةٍ﴾ على ما بث في السماوات والأرض؟","answer":"التثنية تُدخل السماوات والأرض في محل البث، والدابة كل ما يدب من خلق يناسب عالمه؛ والآية تثبت ما نعلمه وما غاب عنا دون تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص247–252.","url":""}]},{"id":"s42-81","number":81,"surah":42,"verses":[29],"verseLabel":"الشورى: 29","question":"ما سر التعبير بـ﴿وَهُوَ عَلَى جَمْعِهِمْ إِذَا يَشَاءُ قَدِيرٌ﴾، واختيار ﴿إِذَا﴾ دون «إن»؟","answer":"﴿إِذَا﴾ تشعر بأن الجمع متعلق بوقت يريده الله واقعًا، لا باحتمال القدرة؛ فهو قادر حين يشاء بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص249–256.","url":""}]},{"id":"s42-82","number":82,"surah":42,"verses":[30],"verseLabel":"الشورى: 30","question":"ما سر إسناد كسب السيئات إلى الأيدي في ﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾؟","answer":"الأيدي أبرز آلات الفعل والاكتساب، فنسب إليها ما باشره الإنسان، والمراد جميع أعماله الاختيارية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص256–262.","url":""}]},{"id":"s42-83","number":83,"surah":42,"verses":[30],"verseLabel":"الشورى: 30","question":"ما دلالة مقابلة إصابة المصيبة ببعض ما كسبت الأيدي بالعفو عن كثير؟","answer":"لا يؤاخذهم بكل ذنب، بل قد تصيبهم مصيبة ببعض الكسب ويعفو عن كثير؛ فظهر العدل محاطًا بالرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص256–266.","url":""}]},{"id":"s42-84","number":84,"surah":42,"verses":[31],"verseLabel":"الشورى: 31","question":"ما سر الجمع بين نفي الإعجاز في الأرض ونفي الولي والنصير من دون الله؟","answer":"لا يستطيعون الهرب من سلطانه بأنفسهم، ولا يجدون من يتولى أمرهم أو ينصرهم عليه؛ فسقط الفرار والاعتماد على الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص256–266.","url":""}]},{"id":"s42-85","number":85,"surah":42,"verses":[31],"verseLabel":"الشورى: 31","question":"ما دلالة التوازن بين ﴿وَمَا أَنْتُمْ بِمُعْجِزِينَ﴾ و﴿وَمَا لَكُمْ مِنْ دُونِ اللَّهِ مِنْ وَلِيٍّ وَلَا نَصِيرٍ﴾؟","answer":"الجملة الأولى تنفي القدرة الذاتية على الإفلات، والثانية تنفي الحماية الخارجية؛ فتطابق النفيان لإحكام معنى العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص263–272.","url":""}]},{"id":"s42-86","number":86,"surah":42,"verses":[29,32],"verseLabel":"الشورى: 29، 32","question":"ما سر تكرار ﴿وَمِنْ آيَاتِهِ﴾ عند خلق السماوات والأرض ثم عند ذكر السفن؟","answer":"الأولى تلفت إلى آية الخلق العام، والثانية إلى آية التسخير في البحر؛ فالتكرار يجدد النظر من الكون الثابت إلى الحركة التي ينتفع بها الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص246–249، 274–277.","url":""}]},{"id":"s42-87","number":87,"surah":42,"verses":[32],"verseLabel":"الشورى: 32","question":"ما سر التعبير عن السفن بـ﴿الْجَوَارِ﴾ وتشبيهها في البحر بالأعلام؟","answer":"الجوار وصف يستحضر حركتها المستمرة، والأعلام هي الجبال أو الرايات الشاهقة؛ فجمعت الصورة سرعة الجريان وضخامة الأجسام فوق الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص274–281.","url":""}]},{"id":"s42-88","number":88,"surah":42,"verses":[32,33],"verseLabel":"الشورى: 32–33","question":"ما مناسبة الانتقال من صورة السفن كالأعلام إلى إمكان إسكان الريح فتبقى رواكد؟","answer":"بعد أن بدت السفن قوية كالجبال كشف أنها معلقة بسبب خفي هو الريح؛ فسكونه يحول الحركة المهيبة إلى عجز تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص274–288.","url":""}]},{"id":"s42-89","number":89,"surah":42,"verses":[33],"verseLabel":"الشورى: 33","question":"ما سر اختيار ﴿رَوَاكِدَ عَلَى ظَهْرِهِ﴾ في تصوير السفن إذا سكنت الريح؟","answer":"الركود سكون طويل بعد الحركة، وظهر البحر سطحه الذي يحملها؛ فبدت الأعلام واقفة على صفحة الماء بلا قدرة ذاتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص282–288.","url":""}]},{"id":"s42-90","number":90,"surah":42,"verses":[33],"verseLabel":"الشورى: 33","question":"ما سر الجمع بين ﴿صَبَّارٍ﴾ و﴿شَكُورٍ﴾ فيمن يدرك آيات الله في البحر، وتقديم الصبر؟","answer":"الصبر يحفظ القلب عند شدة البحر، والشكر يستجيب للنجاة والتسخير؛ وقدم الصبر لأن الشدة تسبق انكشاف النعمة غالبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص286–294.","url":""}]},{"id":"s42-91","number":91,"surah":42,"verses":[33,34],"verseLabel":"الشورى: 33–34","question":"إذا كان إسكان الريح يوقف السفن، فما سر الانتقال بعده إلى ﴿أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا﴾ دون تعيين وسيلة الإهلاك؟","answer":"أطلق وسيلة الإهلاك ليعم الريح والعاصفة والغرق وغيره، فالمقصود تعلق مصيرها بقدرة الله وبكسب أصحابها لا بوسيلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص282–300.","url":""}]},{"id":"s42-92","number":92,"surah":42,"verses":[30,34],"verseLabel":"الشورى: 30، 34","question":"ما سر تكرار معنى العفو عن كثير في سياق المصائب ثم في سياق إيباق السفن؟","answer":"في المصائب العامة وفي خطر البحر قرر أن المؤاخذة ببعض الكسب وأن العفو أوسع؛ فتكرر الأصل ليجمع العدل والرحمة في البر والبحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص259–264، 294–300.","url":""}]},{"id":"s42-93","number":93,"surah":42,"verses":[35],"verseLabel":"الشورى: 35","question":"ما سر الانتقال من آيات البحر إلى المجادلين في آيات الله، وختمه بنفي المحيص؟","answer":"آيات البحر برهان لا مجال للمكابرة فيه، فمن يجادل بعده يعلم أنه لا مهرب من سلطان صاحب الآيات؛ فختم بنفي المحيص.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص300–307.","url":""}]},{"id":"s42-94","number":94,"surah":42,"verses":[36],"verseLabel":"الشورى: 36","question":"ما سر قصر ما أوتيه الناس على ﴿مَتَاعُ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"القصر يحصر عطايا الدنيا في منفعة مؤقتة، فيمنع تحويل كثرتها إلى دليل كرامة أو غاية نهائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص307–312.","url":""}]},{"id":"s42-95","number":95,"surah":42,"verses":[36],"verseLabel":"الشورى: 36","question":"ما دلالة الجمع بين ﴿خَيْرٌ﴾ و﴿أَبْقَى﴾ في وصف ما عند الله، وتقديم الخيرية؟","answer":"الخيرية تثبت تفوقه في ذاته، والبقاء يثبت دوام الانتفاع به؛ وقدمت القيمة لأن البقاء وحده لا يجعل الشيء خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص310–315.","url":""}]},{"id":"s42-96","number":96,"surah":42,"verses":[36],"verseLabel":"الشورى: 36","question":"ما مناسبة تخصيص ما عند الله بالمؤمنين المتوكلين، وتقديم ﴿عَلَى رَبِّهِمْ﴾؟","answer":"الإيمان يصدق الوعد، والتوكل يعلق القلب بالمعطي لا بالعطاء؛ وتقديم الجار والمجرور يقوي اختصاص اعتمادهم بربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص312–320.","url":""}]},{"id":"s42-97","number":97,"surah":42,"verses":[37],"verseLabel":"الشورى: 37","question":"ما سر اختيار الاجتناب دون الترك في قوله ﴿يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ﴾؟","answer":"الاجتناب جعل الشيء في جانب بعيد، فهو أبلغ من ترك قد يقع مع القرب والمراودة؛ يصور الوقاية من مقدمات الكبائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص320–325.","url":""}]},{"id":"s42-98","number":98,"surah":42,"verses":[37],"verseLabel":"الشورى: 37","question":"ما الفرق الدلالي بين ﴿كَبَائِرَ الْإِثْمِ﴾ و﴿الْفَوَاحِشَ﴾، وما سر عطف إحداهما على الأخرى؟","answer":"كبائر الإثم تشمل الذنوب العظيمة، والفواحش ما اشتد قبحه وتجاوز الحد؛ وعطفها يبرز هذا الجنس الفادح داخل عموم الكبائر أو بجانبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص320–325.","url":""}]},{"id":"s42-99","number":99,"surah":42,"verses":[37],"verseLabel":"الشورى: 37","question":"ما دلالة التعبير بـ﴿وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ﴾، ولا سيما زيادة ﴿مَا﴾ وإبراز الضمير؟","answer":"زيادة ﴿مَا﴾ تؤكد ظرف تكرر الغضب، وإبراز ﴿هُمْ﴾ يثبت أن المغفرة خلقهم هم مع وجود الداعي للانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص322–329.","url":""}]},{"id":"s42-100","number":100,"surah":42,"verses":[38],"verseLabel":"الشورى: 38","question":"ما سر ترتيب الاستجابة لله وإقامة الصلاة والشورى والإنفاق في صفات المؤمنين؟","answer":"بدأ بأصل الانقياد لله، ثم عموده الصلاة، ثم نظام الجماعة الشورى، ثم أثر التكافل الإنفاق؛ فتدرج من الصلة بالله إلى بناء المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص332–345.","url":""}]},{"id":"s42-101","number":101,"surah":42,"verses":[38],"verseLabel":"الشورى: 38","question":"ما سر العدول عن «يتشاورون» إلى الجملة الاسمية ﴿وَأَمْرُهُمْ شُورَى بَيْنَهُمْ﴾؟","answer":"الجملة الاسمية تجعل الشورى وصفًا ثابتًا لأمرهم كله، لا فعلًا طارئًا عند أزمة؛ والمصدر يفيد تداول الرأي ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص334–340.","url":""}]},{"id":"s42-102","number":102,"surah":42,"verses":[38],"verseLabel":"الشورى: 38","question":"ما سر توسط الشورى بين الصلاة والإنفاق؟","answer":"الصلاة تصلهم بالله، والإنفاق يصلهم بالناس، والشورى بينهما تنظم الشأن المشترك على هدي العبادة والبذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص335–341.","url":""}]},{"id":"s42-103","number":103,"surah":42,"verses":[38],"verseLabel":"الشورى: 38","question":"ما دلالة تقديم ﴿مِمَّا رَزَقْنَاهُمْ﴾ وحذف مفعول ﴿يُنْفِقُونَ﴾؟","answer":"التقديم يذكر أن المنفَق فضل من رزق الله، وحذف المفعول يعمم وجوه الإنفاق النافع ولا يحصرها في مصرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص336–342.","url":""}]},{"id":"s42-104","number":104,"surah":42,"verses":[37,39],"verseLabel":"الشورى: 37، 39","question":"ما سر الجمع في صفات المؤمنين بين المغفرة عند الغضب والانتصار عند إصابة البغي؟","answer":"المغفرة تضبط الغضب الشخصي وتمنع التشفي، والانتصار يوقف بغيًا يضر الجماعة؛ فليس الحلم استسلامًا ولا القوة عدوانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص322–350.","url":""}]},{"id":"s42-105","number":105,"surah":42,"verses":[40],"verseLabel":"الشورى: 40","question":"ما سر تسمية عقوبة السيئة ﴿سَيِّئَةٌ﴾ في قوله ﴿جَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾؟","answer":"سميت سيئة لمشابهتها الأولى في الصورة وما تسوء به المعتدي، لا لأنها مذمومة شرعًا إذا التزمت العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص350–354.","url":""}]},{"id":"s42-106","number":106,"surah":42,"verses":[40],"verseLabel":"الشورى: 40","question":"ما دلالة تقييد جزاء السيئة بالمماثلة قبل فتح باب العفو والإصلاح؟","answer":"المماثلة تسد باب تجاوز الحق تحت اسم الانتقام، ثم جاء العفو ليفتح رتبة أعلى إذا حقق الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص350–356.","url":""}]},{"id":"s42-107","number":107,"surah":42,"verses":[40],"verseLabel":"الشورى: 40","question":"ما سر الجمع بين العفو والإصلاح وجعل الأجر على الله دون بيان مقداره؟","answer":"العفو بلا إصلاح قد يشجع الظالم، فجمعهما، وجعل الأجر على الله ليعظمه ويترك مقداره فوق كل تقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص352–357.","url":""}]},{"id":"s42-108","number":108,"surah":42,"verses":[40],"verseLabel":"الشورى: 40","question":"ما مناسبة نفي محبة الظالمين بعد إباحة الجزاء بالمثل وندب العفو؟","answer":"بعد إباحة المثل منع أن تتحول إلى ظلم زائد، وبعد مدح العفو بين أن الله لا يحب أصل العدوان؛ فالميزان هو العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص355–365.","url":""}]},{"id":"s42-109","number":109,"surah":42,"verses":[40,41],"verseLabel":"الشورى: 40–41","question":"ما دلالة الانتقال من فضل العفو إلى نفي الحرج عمن انتصر بعد ظلمه؟","answer":"العفو فضيلة اختيارية، لكن المظلوم لا يأثم باسترداد حقه في حدوده؛ فجمعت الآيتان مقام الإحسان وحق العدالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص350–372.","url":""}]},{"id":"s42-110","number":110,"surah":42,"verses":[41,42],"verseLabel":"الشورى: 41–42","question":"ما سر تكرار لفظ ﴿السَّبِيلُ﴾ مع نفيه عن المظلوم وإثباته على الظالم؟","answer":"لا سبيل للمؤاخذة على من انتصر بحق، والسبيل قائم على من بدأ الظلم والبغي؛ فاللفظ نفسه ينقل التبعة إلى موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص365–377.","url":""}]},{"id":"s42-111","number":111,"surah":42,"verses":[42],"verseLabel":"الشورى: 42","question":"ما سر الجمع بين ظلم الناس والبغي في الأرض بغير الحق؟","answer":"ظلم الناس اعتداء على حقوق الأفراد، والبغي في الأرض تجاوز يفسد النظام العام؛ فجمع الضرر الخاص والعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص370–375.","url":""}]},{"id":"s42-112","number":112,"surah":42,"verses":[41,42,43],"verseLabel":"الشورى: 41–43","question":"ما سر العودة إلى مدح الصبر والمغفرة بعد تقرير جواز الانتصار؟","answer":"جواز الانتصار يحفظ الحق، ثم أعاد مدح الصبر والمغفرة حتى لا يصبح الجواز هو المرتبة الوحيدة ويضيع فضل الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص365–385.","url":""}]},{"id":"s42-113","number":113,"surah":42,"verses":[43],"verseLabel":"الشورى: 43","question":"ما دلالة الجمع بين الصبر والمغفرة، وتقديم الصبر؟","answer":"الصبر يحبس النفس عن المبادرة بما لا يليق، والمغفرة ثمرة هذا الضبط تجاه المسيء؛ فقدم السبب على أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص377–383.","url":""}]},{"id":"s42-114","number":114,"surah":42,"verses":[43],"verseLabel":"الشورى: 43","question":"ما سر التعبير عن الصبر والمغفرة بأنهما ﴿لَمِنْ عَزْمِ الْأُمُورِ﴾؟","answer":"العزم قوة القرار في الأمور الرفيعة الشاقة؛ فالصبر مع القدرة على الرد والمغفرة يحتاجان إرادة ثابتة لا ضعفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص378–385.","url":""}]},{"id":"s42-115","number":115,"surah":42,"verses":[44],"verseLabel":"الشورى: 44","question":"ما دلالة الانتقال من تقرير إضلال الظالمين إلى مشهد رؤيتهم العذاب؟","answer":"بعد بيان أن الضلال يحرم الولي انتقل من الحكم المجرد إلى صورته عند العذاب، ليشاهد القارئ نتيجة الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص385–393.","url":""}]},{"id":"s42-116","number":116,"surah":42,"verses":[44],"verseLabel":"الشورى: 44","question":"ما سر سؤال الظالمين عند رؤية العذاب ﴿هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ﴾؟","answer":"طلبوا أي طريق للعودة إلى الدنيا أو النجاة حين انقطع زمنها؛ فسؤالهم نفسه اعتراف بأن المسار الأول لا يُستدرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص388–396.","url":""}]},{"id":"s42-117","number":117,"surah":42,"verses":[45],"verseLabel":"الشورى: 45","question":"ما سر تصوير الظالمين عند العرض بقوله ﴿خَاشِعِينَ مِنَ الذُّلِّ يَنْظُرُونَ مِنْ طَرْفٍ خَفِيٍّ﴾؟","answer":"طأطأهم الذل، فلا يرفعون أبصارهم بل يسرقون النظر من جانب خفي خوفًا؛ فصورت الهيئة انهيار كبريائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص396–403.","url":""}]},{"id":"s42-118","number":118,"surah":42,"verses":[45],"verseLabel":"الشورى: 45","question":"ما دلالة تكرار مادة الخسر في ﴿إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَأَهْلِيهِمْ﴾؟","answer":"الأول اسم يحدد الخاسرين حقًا، والثاني فعل يشرح الخسارة: أضاعوا ذواتهم وأهليهم؛ فكرر الجذر للتوكيد والتفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص401–408.","url":""}]},{"id":"s42-119","number":119,"surah":42,"verses":[45],"verseLabel":"الشورى: 45","question":"ما سر مقابلة نظرهم من طرف خفي بكونهم في ﴿عَذَابٍ مُقِيمٍ﴾؟","answer":"نظرتهم خاطفة كأنهم يرجون انقضاء المشهد، لكن العذاب مقيم لا يزول؛ فقوبل خفاء اللحظة بدوام المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص398–413.","url":""}]},{"id":"s42-120","number":120,"surah":42,"verses":[44,46],"verseLabel":"الشورى: 44، 46","question":"ما سر تكرار ﴿وَمَنْ يُضْلِلِ اللَّهُ﴾ ثم اختلاف الجواب بين ﴿فَمَا لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِهِ﴾ و﴿فَمَا لَهُ مِنْ سَبِيلٍ﴾؟","answer":"الأول ينفي من يتولى إنقاذه بعد الله، والثاني ينفي الطريق نفسه؛ فمرة سقط المنقذ ومرة سقطت الوسيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص385–424.","url":""}]},{"id":"s42-121","number":121,"surah":42,"verses":[46],"verseLabel":"الشورى: 46","question":"ما سر الجمع بين نفي الأولياء الناصرين ونفي سبيل النجاة؟","answer":"الأولياء أشخاص يتوقع نصرتهم، والسبيل طريق الخلاص ولو بلا ناصر؛ فنفى النجاة بواسطة وبغير واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص416–426.","url":""}]},{"id":"s42-122","number":122,"surah":42,"verses":[47],"verseLabel":"الشورى: 47","question":"ما سر اختيار ﴿اسْتَجِيبُوا لِرَبِّكُمْ﴾ دون «أطيعوا ربكم»؟","answer":"الاستجابة قبول نداء سبق وصوله، فتشعر بسرعة الرجوع الطوعي إلى دعوة الرب، وهي أخص بالمقام من مطلق الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص426–430.","url":""}]},{"id":"s42-123","number":123,"surah":42,"verses":[47],"verseLabel":"الشورى: 47","question":"ما سر التعبير بمجيء اليوم في ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ مِنَ اللَّهِ﴾؟","answer":"صور اليوم كأنه قادم إليهم لا يستطيعون إيقافه، وأضاف نفي الرد إلى الله لأن حكمه هو الذي يسوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص427–433.","url":""}]},{"id":"s42-124","number":124,"surah":42,"verses":[47],"verseLabel":"الشورى: 47","question":"ما الفرق الدلالي بين نفي المرد والملجأ والنكير في الآية؟","answer":"لا مرد لوقوع اليوم، ولا ملجأ يحمي داخله، ولا نكير يتيح جحد الأعمال أو تغيير الحكم؛ فانتفت الوقاية والمأوى والاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص428–437.","url":""}]},{"id":"s42-125","number":125,"surah":42,"verses":[48],"verseLabel":"الشورى: 48","question":"ما سر مقابلة نفي كون الرسول ﷺ حفيظًا على المعرضين بقصر مهمته على البلاغ؟","answer":"الحفيظ يراقبهم ويجبرهم أو يحاسبهم، وذلك لله؛ أما الرسول فعليه إيصال الرسالة، فتحدد مهمته دون تحميله اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص437–443.","url":""}]},{"id":"s42-126","number":126,"surah":42,"verses":[48],"verseLabel":"الشورى: 48","question":"ما دلالة التعبير بإذاقة الإنسان الرحمة ثم فرحه بها؟","answer":"الإذاقة تشعر بمباشرة أثر الرحمة ولو كان قليلًا، ثم الفرح يكشف تعلق الإنسان السريع بالنعمة الحاضرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص441–447.","url":""}]},{"id":"s42-127","number":127,"surah":42,"verses":[48],"verseLabel":"الشورى: 48","question":"ما سر التحول من إفراد الإنسان في ﴿أَذَقْنَا الْإِنْسَانَ﴾ إلى ضمير الجمع في ﴿تُصِبْهُمْ سَيِّئَةٌ﴾ ثم العودة إلى الإفراد؟","answer":"الإفراد يرصد طبيعة الإنسان، والجمع يستحضر الأفراد حين تصيبهم المصائب، ثم عاد إلى الجنس في حكم الكفران؛ فنوع الأسلوب مع وحدة الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص441–452.","url":""}]},{"id":"s42-128","number":128,"surah":42,"verses":[48],"verseLabel":"الشورى: 48","question":"ما دلالة المقابلة بين الفرح بالرحمة والكفران عند إصابة السيئة بما قدمت الأيدي؟","answer":"ينسب النعمة إلى الحاضر ويفرح بها، فإذا جاءت المصيبة بسبب كسبه جحد النعم والمنعم؛ فظهر اضطراب ميزانه بين الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص441–459.","url":""}]},{"id":"s42-129","number":129,"surah":42,"verses":[49],"verseLabel":"الشورى: 49","question":"ما مناسبة تقرير ملك الله للسماوات والأرض للانتقال إلى تنوع أحوال الذرية؟","answer":"من له ملك الكون يتصرف في الخلق والتكوين، ومن ذلك توزيع الذرية؛ فاختلافها مظهر ملك ومشيئة لا معيار كرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص459–468.","url":""}]},{"id":"s42-130","number":130,"surah":42,"verses":[49],"verseLabel":"الشورى: 49","question":"ما سر اختيار الهبة في الحديث عن الأولاد، وتكرار ﴿لِمَنْ يَشَاءُ﴾؟","answer":"الهبة عطاء بلا استحقاق ولا قدرة من الوالدين، وتكرار المشيئة مع كل قسم يؤكد استقلال التدبير الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص461–467.","url":""}]},{"id":"s42-131","number":131,"surah":42,"verses":[49],"verseLabel":"الشورى: 49","question":"ما سر تقديم هبة الإناث على هبة الذكور؟","answer":"قدمت الإناث ردًا على عادة الجاهلية في تأخيرهن وكراهتهن، فبدأ القرآن بما كانوا يزدرونه ليصحح الميزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص461–466.","url":""}]},{"id":"s42-132","number":132,"surah":42,"verses":[49],"verseLabel":"الشورى: 49","question":"ما دلالة تنكير ﴿إِنَاثًا﴾ وتعريف ﴿الذُّكُورَ﴾؟","answer":"نُكرت الإناث لتعدد صور الهبة أو لمقابلة تصورهم، وعُرف الذكور لاستغراق الجنس الذي كانوا يعدونه معلوم الفضل؛ وفي البناء كشف لمعيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص461–467.","url":""}]},{"id":"s42-133","number":133,"surah":42,"verses":[49,50],"verseLabel":"الشورى: 49–50","question":"ما سر تقديم الإناث على الذكور عند إفراد الهبة، ثم تقديم الذكران على الإناث عند الجمع بينهما؟","answer":"عند الإفراد قدم ما كانوا يؤخرونه إنصافًا، وعند الجمع قدم الذكور لمناسبة الازدواج المعتاد أو مراعاة ترتيب اللفظ؛ فلا دلالة تفضيل مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص461–470.","url":""}]},{"id":"s42-134","number":134,"surah":42,"verses":[50],"verseLabel":"الشورى: 50","question":"ما دلالة الانتقال من ﴿يَهَبُ﴾ إلى ﴿يُزَوِّجُهُمْ﴾ ثم إلى ﴿وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا﴾؟","answer":"الهبة تفرد كل صنف، والتزويج يجمع الصنفين في ذرية واحدة، ثم العقم يحجب الجميع؛ فاستوعبت الأفعال أحوال البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص466–472.","url":""}]},{"id":"s42-135","number":135,"surah":42,"verses":[50],"verseLabel":"الشورى: 50","question":"ما مناسبة ختم تقسيم أحوال الذرية بقوله ﴿إِنَّهُ عَلِيمٌ قَدِيرٌ﴾، وتقديم العلم؟","answer":"العلم يختار ما يلائم حكمة كل حال، والقدرة تنفذ هذا الاختيار؛ فقدم أساس التقدير على إنفاذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص470–476.","url":""}]},{"id":"s42-136","number":136,"surah":42,"verses":[51],"verseLabel":"الشورى: 51","question":"ما سر اختيار وصف ﴿بَشَرٍ﴾ في قوله ﴿وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ﴾؟","answer":"البشرية تذكر بحدود المخلوق وطبيعته، فتقرر أن تكليم الله له يقع على وجوه تليق بجلال الخالق لا بالمواجهة البشرية المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص476–480.","url":""}]},{"id":"s42-137","number":137,"surah":42,"verses":[51],"verseLabel":"الشورى: 51","question":"ما دلالة تقسيم التكليم الإلهي إلى وحي، أو من وراء حجاب، أو بواسطة رسول؟","answer":"استوعب الاتصال الخفي المباشر، والكلام المسموع مع حجاب، والوحي بواسطة الملك؛ فثبت التكليم مع تنزيه الله وتنويع الوسائط.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص477–485.","url":""}]},{"id":"s42-138","number":138,"surah":42,"verses":[51],"verseLabel":"الشورى: 51","question":"ما سر تقديم الوحي على سائر طرق التكليم، وتكرار ﴿أَوْ﴾ في تقسيمها؟","answer":"الوحي أعم وأخفى الوجوه وأكثرها، فقدم، وكررت ﴿أَوْ﴾ للفصل الحقيقي بين الطرق الثلاث ومنع خلطها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص477–484.","url":""}]},{"id":"s42-139","number":139,"surah":42,"verses":[51],"verseLabel":"الشورى: 51","question":"ما مناسبة ختم تفصيل طرق التكليم بقوله ﴿إِنَّهُ عَلِيٌّ حَكِيمٌ﴾، وتقديم العلو؟","answer":"علوه يمنع تصور التكليم على هيئة كلام المخلوقين، وحكمته تختار لكل رسول وطريق ما يلائمه؛ فقدم التنزيه للمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص482–488.","url":""}]},{"id":"s42-140","number":140,"surah":42,"verses":[51,52],"verseLabel":"الشورى: 51–52","question":"ما دلالة الانتقال من طرق تكليم الله للبشر إلى قوله للنبي ﷺ ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"بعد تقرير القاعدة العامة أشار إلى تحقق أحد وجوهها في النبي؛ فـ﴿كَذَلِكَ﴾ تصل تجربته بسنة التكليم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص476–493.","url":""}]},{"id":"s42-141","number":141,"surah":42,"verses":[52],"verseLabel":"الشورى: 52","question":"ما سر وصف القرآن أولًا بـ﴿رُوحًا﴾ ثم وصفه بـ﴿نُورًا﴾؟","answer":"هو روح لأنه يحيي القلوب بعد موت الجهل، ونور لأنه يكشف الطريق بعد ظلمة الحيرة؛ فالحياة تسبق الإبصار والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص488–501.","url":""}]},{"id":"s42-142","number":142,"surah":42,"verses":[52],"verseLabel":"الشورى: 52","question":"ما دلالة مقابلة قوله ﴿نَهْدِي بِهِ مَنْ نَشَاءُ مِنْ عِبَادِنَا﴾ بقوله للنبي ﷺ ﴿وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"الهداية الأولى خلق التوفيق والقبول وهي لله، والثانية دلالة الرسول وبيانه للطريق؛ فالله يهدي القلوب والنبي يهدي بالإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص498–507.","url":""}]},{"id":"s42-143","number":143,"surah":42,"verses":[6],"verseLabel":"الشورى: 52؛ الفاتحة: 6","question":"ما الفرق بين ﴿وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾ و﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾؟","answer":"هداية الرسول متعدية بـ﴿إِلَى﴾ لأنها دلالة على الطريق، ودعاء الفاتحة يطلب من الله الإيصال والثبات داخل الصراط؛ فهذه إرشاد وتلك توفيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص500–507.","url":""}]},{"id":"s42-144","number":144,"surah":42,"verses":[52,53],"verseLabel":"الشورى: 52–53","question":"ما سر إبدال ﴿صِرَاطِ اللَّهِ﴾ من ﴿صِرَاطٍ مُسْتَقِيمٍ﴾، ثم تعريف الله بملك السماوات والأرض؟","answer":"الإبدال يفسر الطريق المستقيم بأنه طريق الله، ثم وصف الله بالملك ليبين أن الطريق يوصل إلى مالك الكون وصاحب الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص500–513.","url":""}]},{"id":"s42-145","number":145,"surah":42,"verses":[53],"verseLabel":"الشورى: 53","question":"ما سر ختم السورة بقوله ﴿أَلَا إِلَى اللَّهِ تَصِيرُ الْأُمُورُ﴾، وما مناسبة ذلك لمطلعها؟","answer":"كل الأمور ترجع في النهاية إلى الله كما صدر الوحي في المطلع منه؛ فالتنبيه ﴿أَلَا﴾ يختم انتقال الرسالة والخلق والحكم إلى مرجع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص510–520.","url":""}]},{"id":"s43-1","number":1,"surah":43,"verses":[1],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزخرف»، مع أن اللفظ لم يرد فيها إلا مرة واحدة؟","answer":"الزخرف رمز بريق الدنيا الذي اتخذه المشركون ميزانًا للفضل، ثم بينت السورة هوانه أمام الوحي والتقوى؛ فاختصر الاسم نقد الموازين الزائفة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص524–527.","url":""}]},{"id":"s43-2","number":2,"surah":43,"verses":[1],"verseLabel":"مقدمة السورة","question":"ما دلالة المقابلة في السورة بين زخرف الدنيا وقيمة الوحي والميزان الإلهي؟","answer":"يعظمون المال والزينة ويقيسون بهما النبوة، بينما يجعل الله الوحي والتقوى والآخرة معيار الكرامة؛ فتكشف المقابلة الفرق بين سعر الأشياء وقيمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص525–531.","url":""}]},{"id":"s43-3","number":3,"surah":43,"verses":[1],"verseLabel":"مقدمة السورة","question":"ما سر تكرر ذكر ﴿الرَّحْمَنِ﴾ في سياق مجادلة المشركين؟","answer":"كانوا يشركون بالرحمن ويحتجون بمشيئته وينسبون إليه الولد؛ فتكرر الاسم الذي يدل على سعة الرحمة ليفضح مقابلة نعمته بالجحود، ويبين أن الوحي والإمهال من رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص526–530.","url":""}]}]);
